import { assetUrl } from "./assetUrl";
import type { Chapter, ConceptNode, VisualModel } from "./data";
import type { Instrument, Journey, SourceLink, SystemBook, TaxonomyGroup } from "./systemTypes";

type Seed = { id: number; shortTitle: string; formalTitle: string; overview: string; thesis?: string; moves: Array<{ title: string; body: string }>; closer: Array<{ title: string; body: string }>; distinction: [string, string, string, string, string]; misreading: string; reflection: string; audit: string[]; nodes: string[]; model: VisualModel };
const bab = (id: number) => (id === 1 ? "the author's introduction" : id <= 6 ? "the first chapter" : id <= 15 ? "the second chapter" : id <= 22 ? "the third chapter" : id <= 25 ? "the fourth chapter" : id <= 31 ? "the fifth chapter" : id <= 45 ? "the sixth chapter" : "the seventh chapter");
const makeChapter = (seed: Seed): Chapter => ({
  id: seed.id, shortTitle: seed.shortTitle, formalTitle: seed.formalTitle, overview: seed.overview,
  reflection: seed.reflection, relatedNodes: seed.nodes, visualModel: seed.model,
  deep: { thesis: seed.thesis ?? seed.moves[0].body, context: seed.overview, moves: seed.moves, closeReading: seed.closer,
    distinction: { title: seed.distinction[0], firstLabel: seed.distinction[1], first: seed.distinction[2], secondLabel: seed.distinction[3], second: seed.distinction[4] },
    misreading: seed.misreading, observation: seed.reflection, selfAudit: seed.audit,
    sourceAnchor: `Book 1, ${bab(seed.id)}, ${seed.formalTitle}.` },
});
const chain = (title: string, caption: string, items: Array<[string, string, "support" | "balance" | "warning"]>): VisualModel => ({ kind: "chain", title, caption, items: items.map(([label, body, role]) => ({ label, body, role })) });
const pair = (title: string, caption: string, items: Array<[string, string, "support" | "balance" | "warning"]>): VisualModel => ({ kind: "pair", title, caption, items: items.map(([label, body, role]) => ({ label, body, role })) });
const spectrum = (title: string, caption: string, items: Array<[string, string, "support" | "balance" | "warning"]>): VisualModel => ({ kind: "spectrum", title, caption, items: items.map(([label, body, role]) => ({ label, body, role })) });

export const book01Chapters: Chapter[] = [
  makeChapter({
    id: 1, shortTitle: "Why the Ihya was written", formalTitle: "The author's introduction: the critic, the lost knowledge, the four quarters and the two reasons for them",
    overview: "Before the Book of Knowledge begins, Ghazali explains why he wrote the whole Ihya. He answers a critic and says the knowledge of the road to the next life has been forgotten. Then he lays out the forty books in four quarters, and gives two reasons for that plan.",
    thesis: "The guides on the road to the next life are the scholars, and most of them have turned to what pays in this world. So the knowledge that leads to God has been folded up and forgotten. The Ihya is meant to bring it back to life, and it starts with knowledge because that is where the damage began.",
    moves: [
      { title: "Four openings", body: "Ghazali begins by praising God and sending blessings on His messengers. Then he asks God for guidance in his plan to write a book called The Revival of the Religious Sciences. Fourth, he turns to a critic. This man blames him harshly and is loud among the people who deny and scoff. Ghazali says the critic's stubbornness is what finally made him speak." },
      { title: "What the critic mocks", body: "The critic mocks someone who has stepped a little away from the usual customs of scholars. That person wants to act on what he knows, to purify himself and set his heart right, and to make up for years he has wasted. He does not want to be among those the Prophet described. The Prophet said: “The person most severely punished on the Day of Resurrection is a scholar whom God did not let benefit from his knowledge.”" },
      { title: "The illness behind it", body: "Ghazali says the critic's pride has one cause, and it has spread to almost everyone. People do not see how serious the matter is. The next life is coming towards us and this world is turning away. Death is near, the journey is long, the provisions are thin and the danger is great. Only what is done sincerely for God will be accepted by the One who sees clearly. The road to the next life is full of traps, and walking it without a guide or a companion is exhausting." },
      { title: "The guides are gone", body: "The guides for this road are the scholars, the heirs of the prophets. But the age has run short of them, Ghazali says. Only people who wear the outward form of scholars remain, and Satan has taken hold of most of them. Each one is in love with his share of this world. They see good as bad and bad as good. So religious knowledge has faded, and the lights of guidance have gone out across the earth." },
      { title: "Three things they call knowledge", body: "These people have made everyone believe that knowledge is only three things. One is legal rulings, which judges use to settle quarrels among rough crowds. Another is debate, which a person who wants to show off wears like armour to win and silence others. The third is fancy rhyming speech, which a preacher uses to draw in ordinary people. They saw no other way to catch what is forbidden and gather worldly scraps." },
      { title: "What was forgotten", body: "The knowledge of the road to the next life has been folded away and forgotten. This is what the early Muslims walked on, and what God in His Book called understanding, wisdom, knowledge, light, radiance, guidance and right direction. Because this is a real breach in the religion, Ghazali decided to write the book. He wanted to revive the religious sciences, show the ways of the early imams, and make clear which kinds of knowledge are really useful." },
      { title: "Forty books in four quarters", body: "He built it on four quarters: the Quarter of Worship, the Quarter of Customs, the Quarter of Things that Destroy, and the Quarter of Things that Save. Each has ten books. Worship covers knowledge, belief, purity, prayer, alms, fasting, pilgrimage, reciting the Quran, remembrance and prayers of asking, and the daily round of devotions. Customs covers eating, marriage, earning, the lawful and unlawful, companionship, solitude, travel, music and ecstasy, commanding good and forbidding wrong, and the Prophet's way of living and character." },
      { title: "The last two quarters", body: "The Quarter of Things that Destroy covers the wonders of the heart, training the self, and the two appetites of stomach and sex. Then come the tongue, anger and envy, the world, money and greed, status and showing off, pride and self-admiration, and self-deception. The Quarter of Things that Save covers repentance, patience and gratitude, fear and hope, and poverty and doing without. Then come God's oneness and trust, love and longing, intention and sincerity, watching and taking account of oneself, reflection, and remembering death." },
      { title: "What each quarter gives", body: "In Worship, Ghazali gives the hidden manners, fine points and inner meanings of each act, which the lawyers' books mostly leave out. In Customs, he gives the inner side of dealings between people and the fine points of caution in them. In the Destroyers, he takes each blamed trait the Quran tells us to remove. He gives its definition, its cause, the harms it brings, its signs and its cure. In the Savers, he does the same for each praised trait: its definition, cause, fruit, signs and merit." },
      { title: "Five things that make it different", body: "Other people have written on these topics, but Ghazali says this book stands apart in five ways. It unties what they knotted and explains what they left vague. It puts in order what they scattered. It shortens what they dragged out and pins down what they settled. It drops what they repeated. And it takes up hard questions that no book had touched, since one traveller on a shared road can notice what his companions missed." },
      { title: "Two reasons for the plan", body: "The first reason for four quarters is that the subject demands it. Knowledge aimed at the next life is of two kinds. Knowledge of unveiling is sought only to know; knowledge of practice is sought in order to act. This book is only about practice. The prophets spoke openly only about the road, and about unveiling only in hints. Practice is either outward, in the limbs, or inward, in the heart. The outward is custom or worship; the inward is blamed or praised. That makes four." },
      { title: "Dressed as a law book", body: "The second reason is practical. Ghazali saw students eager for law, the subject that people who do not fear God use to gain status and win rivalries. Law books come in four quarters. So he gave his book the same shape, gently to draw hearts in, since whoever dresses like the beloved is loved. A doctor once did the same thing. He laid out medicine in tables like an astrologer's almanac, and called it The Almanac of Health, so that rulers would read it. Drawing hearts to the medicine of the soul matters far more than drawing them to the medicine of the body." },
    ],
    closer: [
      { title: "The seven chapters", body: "The Book of Knowledge has seven chapters. They cover the excellence of knowledge, teaching and learning, and the praised and blamed sciences with the two kinds of duty. Next comes what people count as religious knowledge that is not. Then come the harms of debate, and the manners of teacher and student. The last two are the harms of knowledge with the signs of the two kinds of scholar, and reason, its merit and its kinds." },
      { title: "Why knowledge comes first", body: "Ghazali puts this book at the head of the forty because it matters most. He wants to show which knowledge God made a duty on everyone, and to separate useful knowledge from harmful. He also wants to show how people of his time had settled for the shell and left the kernel." },
    ],
    distinction: ["Two kinds of knowledge aimed at the next life", "Knowledge of practice", "Learned in order to act on it. The prophets taught it openly, and the whole Ihya is about it.", "Knowledge of unveiling", "Sought only to know. The goal of the seekers, but not to be put in books, and given by the prophets only in hints."],
    misreading: "Do not read the attack on the scholars as an attack on law, debate or preaching as such. The complaint is that these three had been made to stand for all of knowledge, while the knowledge of the road to God was forgotten.",
    reflection: "Think of the three things Ghazali says had been passed off as all of knowledge. Which of them would people around you call knowledge today?",
    audit: ["Do I act on what I already know?", "Which of the four quarters do I most need?", "Do I have a guide for the road?", "Would I read a book like this if it were not dressed as something I already wanted?"],
    nodes: ["ihya", "ilm", "muamala"],
    model: chain("How the four quarters come out", "Ghazali's own division of the knowledge of practice.", [["Knowledge of practice", "Learned to be acted on; the subject of the whole Ihya.", "support"], ["Outward, in the limbs", "Split into worship and customs: the first two quarters.", "balance"], ["Inward, in the heart", "Split into blamed traits and praised traits: the last two quarters.", "balance"], ["Unveiling", "The goal of the road, kept out of books and given only in hints.", "warning"]]),
  }),
  makeChapter({
    id: 2, shortTitle: "What the Quran and the Prophet say", formalTitle: "The excellence of knowledge: the verses of the Quran and the reports from the Prophet",
    overview: "Ghazali opens the first chapter with the evidence of revelation. He sets out the verses that honour knowledge and then a long run of the Prophet's sayings, with short comments of his own.",
    thesis: "God put the people of knowledge third, after Himself and the angels. The Prophet called the scholars heirs of the prophets and put the scholar far above the worshipper. Knowledge is the thing that gives worship its value.",
    moves: [
      { title: "Third after the angels", body: "The first verse is: “God bears witness that there is no god but Him, and so do the angels and those who have knowledge, upholding justice.” Ghazali asks us to look at the order. God begins with Himself, then the angels, then the people of knowledge. That, he says, is honour and excellence enough. God also says: “God will raise those of you who believe and those who were given knowledge by degrees.” Ibn Abbas said the scholars are seven hundred degrees above the believers, and between each two degrees is a journey of five hundred years." },
      { title: "Knowing and fearing", body: "“Say: are those who know equal to those who do not know?” “Only those of His servants who have knowledge truly fear God.” “Enough is God as a witness between me and you, and whoever has knowledge of the Book.” When Solomon asked who could bring the queen's throne, “the one who had knowledge from the Book” said he would bring it in the blink of an eye. Ghazali notes that he was able to do it by the power of knowledge." },
      { title: "The next life is known by knowledge", body: "When Korah paraded his wealth, “those who were given knowledge said: woe to you! God's reward is better for whoever believes and does good.” This shows that the greatness of the next life is only understood through knowledge. “These are the examples We give to people, but only those who know understand them.” And God says that if people had referred a matter to the messenger and those in charge, “those who can work it out would have known it.” Ghazali says this puts their judgment next to the prophets' in uncovering God's ruling." },
      { title: "Clothing, feathers and a gift", body: "Someone explained the verse “We have sent down to you clothing to cover your shame, and feathers.” The clothing is knowledge, the feathers are certainty, and the clothing of mindfulness is modesty. God says He brought people a Book “explained with knowledge”. He says the Quran is “clear signs in the hearts of those given knowledge”. And “He created the human being and taught him clear speech” — told as a gift God reminds us of." },
      { title: "Heirs of the prophets", body: "The Prophet said: “When God wants good for someone, He gives him understanding of the religion and inspires him with right guidance.” He said: “The scholars are the heirs of the prophets.” Ghazali comments that there is no level above prophethood, so there is no honour above inheriting it. The Prophet said that everything in the heavens and the earth asks forgiveness for the scholar. What position is higher than one where the angels of heaven and earth are busy asking forgiveness for you? He said: “Wisdom adds honour to the honourable, and lifts a slave until he reaches the level of kings.” That is its fruit in this world, and the next is better and lasts longer." },
      { title: "Two things a hypocrite never has", body: "The Prophet said: “Two traits are never found together in a hypocrite: a good bearing and understanding of the religion.” Ghazali warns: do not doubt this report because some lawyers of your time are hypocrites. The Prophet did not mean the kind of law you are thinking of. The meaning of understanding will come later. The lowest level of true understanding is to know the next life is better than this one. When that knowledge is real and takes over, it frees a person from hypocrisy and showing off." },
      { title: "Nearest to prophethood", body: "The Prophet said: “The best of people is the believer with knowledge, who helps when he is needed and is content when he is not.” “Faith is naked. Its clothing is mindfulness, its ornament is modesty, and its fruit is knowledge.” “The people nearest to the level of prophethood are the people of knowledge and of striving.” The first guided people to what the messengers brought; the second fought with their swords for it. He said: “The death of a whole tribe is easier than the death of one scholar.” And: “People are mines, like mines of gold and silver. The best of them before Islam are the best in Islam, once they understand.”" },
      { title: "Ink and blood", body: "“On the Day of Resurrection the ink of the scholars will be weighed against the blood of the martyrs.” “Whoever preserves forty reports of my Sunna for my community, to pass them on, I will be his intercessor and witness.” “Whoever understands God's religion, God will take care of his worries and provide for him from where he never expected.” God revealed to Abraham: “I am All-Knowing, and I love everyone who knows.” “The scholar is God's trustee on earth.” “Two kinds of people in my community decide how the people are. When they are good, the people are good; when they are corrupt, the people are corrupt. They are the rulers and the scholars.”" },
      { title: "Knowledge above worship", body: "The Prophet said: “Some days I do not grow in knowledge that brings me nearer to God. May the sunrise of such a day not be blessed for me.” He said: “The excellence of the scholar over the worshipper is like my excellence over the least of my Companions.” Ghazali says: see how he placed knowledge next to prophethood, and lowered action without knowledge. Even the worshipper must know something about the worship he keeps up, or it would not be worship at all. “The scholar is above the worshipper as the full moon is above all the stars.” “Three will intercede on the Day of Resurrection: the prophets, then the scholars, then the martyrs.” Ghazali says: how great is a level that comes after prophethood and above martyrdom!" },
      { title: "Worth more than a thousand worshippers", body: "“God is not worshipped with anything better than understanding of the religion. One person of understanding is harder on Satan than a thousand worshippers. Everything has a pillar, and the pillar of this religion is understanding.” “The best of your religion is the easiest of it, and the best worship is understanding.” The believer with knowledge is seventy degrees above the believer who only worships. Between the scholar and the worshipper are a hundred degrees, and between each two is seventy years' galloping of a trained racehorse." },
      { title: "A time when knowledge is better", body: "The Prophet said: “You are in a time when people of understanding are many and reciters and preachers are few, when askers are few and givers are many. In it action is better than knowledge. A time will come when people of understanding are few and preachers are many, askers are many and givers are few. In it knowledge will be better than action.” Someone asked him which deed is best. He said: “Knowledge of God.” They said they were asking about deeds. He said: “A little action helps with knowledge of God, and a lot of action does not help with ignorance of God.”" },
      { title: "The scholars forgiven", body: "Last, the Prophet said: “God will raise His servants on the Day of Resurrection. Then He will raise the scholars and say: O scholars, I did not place My knowledge in you except because I knew you. I did not place it in you to punish you. Go, for I have forgiven you.” Ghazali ends the reports with a prayer that God give us a good end." },
    ],
    closer: [
      { title: "The order in the verse", body: "Ghazali's first comment is on word order alone. God, then the angels, then the people of knowledge. He needs no argument for the honour; the sentence carries it." },
      { title: "The warning inside the praise", body: "Even here he stops to warn. The report about hypocrites and understanding does not mean the lawyers of his day. The true measure of understanding is knowing that the next life is better, and letting that knowledge rule you." },
    ],
    distinction: ["Two things compared in the reports", "The scholar", "Guides people to what the messengers brought. His ink is weighed with the martyrs' blood, and he intercedes after the prophets.", "The worshipper", "Does good only for himself, and even his worship depends on some knowledge. The scholar is above him as the moon is above the stars."],
    misreading: "Do not take these reports as praise for anyone with a title. Ghazali stops mid-list to say that “understanding” in the reports is not the law of his day. The rest of the book spells out which knowledge earns this praise.",
    reflection: "Pick one saying from this section that surprised you. Ask what it would change if you really believed it.",
    audit: ["Do I think of learning as worship?", "Is my worship built on knowing what I am doing?", "Does my knowledge make me fear God more?", "Is there a day I have not grown in knowledge that brings me near to God?"],
    nodes: ["ilm", "warith"],
    model: spectrum("Who stands where", "The order the reports give.", [["The prophets", "The highest level; they intercede first.", "support"], ["The scholars", "Their heirs; they intercede next, and their ink is weighed with blood.", "support"], ["The martyrs", "They intercede after the scholars.", "balance"], ["The worshipper", "Below the scholar as the stars are below the full moon.", "balance"]]),
  }),
  makeChapter({
    id: 3, shortTitle: "What the early Muslims said", formalTitle: "The excellence of knowledge: the sayings of the Companions and those after them",
    overview: "After the Prophet's reports, Ghazali gathers sayings of Ali, Ibn Abbas, Ibn al-Mubarak and many others. Together they show knowledge as the thing that makes a person human, and the food without which the heart dies.",
    thesis: "Knowledge guards you, rules over wealth, and grows when you spend it. A person is human because of knowledge, not because of strength or size. A heart kept from knowledge dies, though it does not feel it until death wakes it.",
    moves: [
      { title: "Ali to Kumayl", body: "Ali said to Kumayl: “Kumayl, knowledge is better than money. Knowledge guards you, while you guard money. Knowledge is a judge, and money is judged. Money shrinks when you spend it, and knowledge grows when you give it.” Ali also said: “The scholar is better than the one who fasts, prays at night and fights in God's cause. When a scholar dies, a gap opens in Islam that only someone who follows him can fill.”" },
      { title: "Ali's verses", body: "Ali put it in a poem. There is no glory except for the people of knowledge, he says, because they guide anyone who asks for guidance. Each person is worth what he does well, and the ignorant are enemies of the people of knowledge. So win knowledge, and live by it forever. People are dead, and the people of knowledge are alive." },
      { title: "Kings over kings", body: "Abu al-Aswad said: “Nothing is mightier than knowledge. Kings rule over people, and scholars rule over kings.” Ibn Abbas said that Solomon son of David was given the choice between knowledge, wealth and kingship. He chose knowledge, and was given wealth and kingship along with it." },
      { title: "Who counts as people", body: "Someone asked Ibn al-Mubarak: “Who are the people?” He said: “The scholars.” “Who are the kings?” “Those who do without the world.” “Who are the lowest?” “Those who eat up the world by means of religion.” Ghazali explains why he counted only scholars as people. What sets humans apart from animals is knowledge. A camel is stronger than a man. An elephant is bigger. A lion is braver. An ox eats more. The smallest sparrow mates more. A human was created only for knowledge." },
      { title: "What did he gain, what did he lose", body: "One scholar said: “I wish I knew what someone who missed knowledge has gained, and what someone who gained knowledge has missed.” The Prophet said: “Whoever is given the Quran and thinks someone else was given something better has belittled what God made great.”" },
      { title: "The heart that starves", body: "Fath al-Mawsili asked: “If a sick man is kept from food, drink and medicine, won't he die?” They said yes. He said: “So too the heart. If it is kept from wisdom and knowledge for three days, it dies.” Ghazali says Fath was right. The heart's food is knowledge and wisdom, just as the body's food is bread. Whoever lacks knowledge has a sick heart, and its death is certain. But he does not feel it, because love of the world has numbed him." },
      { title: "Waking up at death", body: "This numbness is like fear so strong that a man does not feel his wounds in the moment, or like drunkenness. When death lifts the world's burdens off him, he feels his ruin and grieves bitterly, and it does him no good. It is like a man who feels his wounds only once he is safe, or who sobers up and finds what happened while he was drunk. Ghazali prays for refuge from the day the cover is lifted. “People are asleep. When they die, they wake up.”" },
      { title: "Before it is taken away", body: "Al-Hasan said the scholars' ink will be weighed against the martyrs' blood, and the ink will weigh more. Ibn Mas'ud said: “Hold on to knowledge before it is lifted away, and its lifting is the death of those who carry it. By the One who holds my soul, men killed as martyrs in God's cause will see the honour scholars receive. Then they will wish God had raised them as scholars. No one is born a scholar; knowledge comes only by learning.” Ibn Abbas said: “Studying knowledge together for part of a night is dearer to me than spending the whole night in prayer.” The same is reported from Abu Hurayra and Ahmad ibn Hanbal." },
      { title: "What swims with you", body: "Al-Hasan explained the prayer “Our Lord, give us good in this world and good in the next.” Good in this world is knowledge and worship, and good in the next is the Garden. A wise man was asked what things are worth owning. He said: “Things that swim with you if your ship sinks,” meaning knowledge. Some said the sinking ship means the body dying. Another said: “Whoever takes wisdom as a bridle, people take him as a leader. Whoever is known for wisdom, eyes look at him with respect.”" },
      { title: "Happy to be linked to it", body: "Al-Shafi'i said: “Part of the honour of knowledge is that anyone linked with it, even in something small, is glad; and anyone denied it is sad.” Umar said: “People, hold on to knowledge. God has a cloak He loves. Whoever seeks a branch of knowledge, God wraps him in His cloak. If he sins, God calls him back three times, so as not to strip the cloak from him, even if that sin stays with him until he dies.”" },
      { title: "The freed slave and the governor", body: "Al-Ahnaf said: “Scholars almost became lords. Every honour not made firm by knowledge ends in disgrace.” Salim ibn Abi al-Ja'd said: “My master bought me for three hundred dirhams and set me free. I asked myself what trade to take up, and I took up knowledge. Within a year the governor of Medina came to visit me, and I did not let him in.”" },
      { title: "Wealth when poor, beauty when rich", body: "Al-Zubayr ibn Abi Bakr said his father wrote to him in Iraq: “Hold on to knowledge. If you become poor, it will be your wealth. If you become rich, it will be your beauty.” Luqman told his son: “My son, sit with the scholars and press close to them with your knees. God brings hearts to life with the light of wisdom, as He brings the earth to life with heavy rain.” A wise man said: “When a scholar dies, the fish in the water and the birds in the air weep for him. His face is missed, and his memory is not forgotten.” Al-Zuhri said: “Knowledge is manly, and only manly men love it.”" },
    ],
    closer: [
      { title: "Why only scholars are people", body: "Ibn al-Mubarak's answer sounds harsh until Ghazali explains it. Every other strength a human has, some animal has more of. Knowledge is the one thing that is his own." },
      { title: "A death you do not feel", body: "The most frightening image here is Fath's. The heart can be dead already while the person feels fine, the way a drunk man does not feel his wounds. Death is when he sobers up." },
    ],
    distinction: ["Knowledge and money, in Ali's words", "Knowledge", "Guards you, rules, and grows when you give it away.", "Money", "Needs you to guard it, is ruled, and shrinks when you spend it."],
    misreading: "Salim's closed door to the governor is not rudeness for its own sake. It shows what the early Muslims thought knowledge was worth: a freed slave could stand above a governor because of it.",
    reflection: "Fath says the heart dies after three days without knowledge and wisdom. Count how many days it has been since you fed yours.",
    audit: ["What do I own that would swim with me if the ship sank?", "Would I choose knowledge over wealth, like Solomon?", "Is my heart numb to its own hunger?", "What strength do I rely on that an animal has more of?"],
    nodes: ["ilm", "qalb"],
    model: pair("Two kinds of wealth", "Ali's comparison to Kumayl.", [["Knowledge", "Guards its owner, judges, and grows by being spent.", "support"], ["Money", "Guarded by its owner, judged, and shrinks by being spent.", "warning"]]),
  }),
  makeChapter({
    id: 4, shortTitle: "Why learning is worth it", formalTitle: "The excellence of learning: verses, reports and sayings",
    overview: "Ghazali turns from knowledge to the act of seeking it. The verses and reports promise a road to the Garden, the wings of the angels, and a reward greater than voluntary prayer. The early Muslims add their own sayings.",
    thesis: "Seeking knowledge is itself worship. It is better than a hundred units of voluntary prayer, and the angels lower their wings for the student. Anyone who dies while seeking knowledge to revive Islam is one degree below the prophets in the Garden.",
    moves: [
      { title: "Some should go and learn", body: "God says: “Why should not a group from every part of them go out to gain understanding of the religion?” And: “Ask the people of remembrance if you do not know.” The Prophet said: “Whoever walks a road seeking knowledge, God sets him on a road to the Garden.” He said: “The angels lower their wings for the seeker of knowledge, pleased with what he is doing.”" },
      { title: "Better than a hundred units of prayer", body: "“To go out in the morning and learn one chapter of knowledge is better than praying a hundred units of prayer.” “One chapter of knowledge that a man learns is better for him than the world and everything in it.” “Seek knowledge, even as far as China.” “Seeking knowledge is a duty on every Muslim.”" },
      { title: "Four are rewarded", body: "The Prophet said: “Knowledge is a set of treasure-houses, and the keys are questions. So ask, for four are rewarded: the one who asks, the scholar, the listener, and the one who loves them.” He said: “The ignorant should not keep quiet about their ignorance, and the scholar should not keep quiet about his knowledge.”" },
      { title: "More than a thousand units", body: "Abu Dharr reported that attending a scholar's gathering is better than praying a thousand units of prayer, visiting a thousand sick people and attending a thousand funerals. Someone asked: “Messenger of God, and better than reciting the Quran?” He said: “Does the Quran benefit anyone without knowledge?” The Prophet also said: “Someone may die while seeking knowledge to revive Islam with it. There will be one degree between him and the prophets in the Garden.”" },
      { title: "Humble as a seeker", body: "Ibn Abbas said: “I was humble as a seeker, so I was honoured as the one sought.” Ibn Abi Mulayka said: “I never saw anyone like Ibn Abbas. When you saw him, he had the finest face. When he spoke, he had the clearest tongue. When he gave a ruling, he had the most knowledge.” Ibn al-Mubarak said: “I am amazed at anyone who does not seek knowledge. How does his self call him to anything noble?”" },
      { title: "The two men to pity", body: "A wise man said: “I pity no one as much as one of two men. One seeks knowledge and does not understand. The other understands and does not seek it.” Abu al-Darda said: “Learning one question is dearer to me than praying all night.” He also said: “Be a scholar, a student or a listener. Do not be the fourth, or you will be ruined.”" },
      { title: "Ata, Umar and al-Shafi'i", body: "Ata said: “One gathering of knowledge makes up for seventy gatherings of idle fun.” Umar said: “A thousand worshippers may pray all night and fast all day. Their death is lighter than the death of one scholar who sees clearly what God allows and forbids.” Al-Shafi'i said: “Seeking knowledge is better than voluntary prayer.”" },
      { title: "Malik and the midday prayer", body: "Ibn Abd al-Hakam said: “I was reading with Malik when the time for the midday prayer came. I gathered up my books to go and pray. He said: ‘What you have got up for is not better than what you were doing, if the intention is right.’” Then there is Abu al-Darda. He said: “Going out in the morning to seek knowledge is striving in God's cause. Whoever thinks otherwise has a flaw in his judgment and his reason.”" },
    ],
    closer: [
      { title: "The condition in Malik's words", body: "Malik places study above voluntary prayer, but with a condition: “if the intention is right.” The whole book will keep coming back to that condition." },
      { title: "The fourth kind", body: "Abu al-Darda leaves only three safe roles: to know, to learn, or to listen. The ruined one is the person who is none of these." },
    ],
    distinction: ["Two men Ghazali's source pities", "Seeks and does not understand", "Wants knowledge but cannot take it in.", "Understands and does not seek", "Could take it in, and does not bother."],
    misreading: "These reports do not tell anyone to give up the obligatory prayers for study. Malik's pupil was getting up for a voluntary prayer, and al-Shafi'i compares study with voluntary worship.",
    reflection: "Abu al-Darda's four kinds: scholar, student, listener, and the ruined fourth. Which one were you this week?",
    audit: ["Do I ask when I do not know?", "Do I treat going to learn as striving in God's cause?", "Is my intention in learning right?", "Am I ever the fourth kind?"],
    nodes: ["talab", "ilm"],
    model: spectrum("Abu al-Darda's four", "Be one of the first three.", [["The scholar", "Knows and teaches.", "support"], ["The student", "Is learning.", "support"], ["The listener", "Sits and hears.", "balance"], ["The fourth", "None of these, and ruined.", "warning"]]),
  }),
  makeChapter({
    id: 5, shortTitle: "Why teaching is worth it", formalTitle: "The excellence of teaching: verses, reports and sayings",
    overview: "Teaching is commanded, and hiding knowledge is forbidden. The Prophet said he was sent as a teacher, and compared his message to rain falling on three kinds of ground. The early Muslims wept when no one came to ask them.",
    thesis: "God took a covenant from those given knowledge to make it clear and not hide it. The teacher's reward goes on after his death, everything asks forgiveness for him, and whoever hides knowledge will be bridled with fire.",
    moves: [
      { title: "The covenant to explain", body: "God says that those who go out to learn should “warn their people when they return to them, so that they may take care.” Ghazali says this means teaching and guiding. God took a covenant from those given the Book: “You must make it clear to people and not hide it.” That makes teaching a duty. He says: “A group of them hide the truth while they know it.” That forbids hiding it, as He said of testimony: “Whoever hides it, his heart is sinful.” The Prophet said: “God never gave a scholar knowledge without taking a covenant from him. It was the covenant He took from the prophets: to make it clear to people and not hide it.”" },
      { title: "One person guided", body: "God says: “Who is better in speech than someone who calls to God and does good?” “Call to the way of your Lord with wisdom and good advice.” And of the Prophet: “He teaches them the Book and wisdom.” The Prophet sent Mu'adh to Yemen. He told him: “For God to guide one man through you is better for you than the world and everything in it.” He said: “Whoever learns a chapter of knowledge in order to teach people is given the reward of seventy truthful saints.” Jesus said: “Whoever learns, acts and teaches is called great in the kingdom of heaven.”" },
      { title: "Like some of My angels", body: "The Prophet said that on the Day of Resurrection God will say to the worshippers and fighters: “Enter the Garden.” The scholars will say: “It was by the excellence of our knowledge that they worshipped and fought.” God will say: “To Me you are like some of My angels. Intercede, and your intercession will be accepted.” They will intercede, and then enter the Garden. Ghazali notes that this is for knowledge that passes to others by teaching, not knowledge kept to oneself." },
      { title: "Taken away with the scholars", body: "“God does not snatch knowledge out of people after giving it to them. It goes as the scholars go. Each time a scholar dies, the knowledge he carried goes with him, until only ignorant leaders remain. When asked, they give rulings without knowledge, so they go astray and lead others astray.” And: “Whoever knows something and hides it, God will bridle him with a bridle of fire on the Day of Resurrection.”" },
      { title: "A word worth a year", body: "“What a fine gift: a word of wisdom you hear, keep hold of, and carry to a Muslim brother to teach him. It equals a year of worship.” “The world is cursed, and what is in it is cursed, except the remembrance of God and what goes with it, and a teacher or a learner.” “God blesses the one who teaches people good. So do His angels and the people of the heavens and the earth, even the ant in its hole and the fish in the sea.” “A Muslim gives his brother nothing better than a good saying that reached him and that he passes on.”" },
      { title: "I was sent as a teacher", body: "One day the Prophet came out and saw two circles. One was calling on God and asking Him. The other was teaching people. He said: “These are asking God; if He wills He gives them, and if He wills He holds back. These are teaching people, and I was only sent as a teacher.” Then he went over and sat with them." },
      { title: "Three kinds of ground", body: "The Prophet said: “The guidance and knowledge God sent me with is like heavy rain falling on land. One part of it took in the water and grew plenty of grass and plants. One part held the water, and God let people benefit from it: they drank, watered their animals and farmed. And one part was bare flat ground that neither held water nor grew grass.” Ghazali explains that the first is someone who benefits from his knowledge. The second benefits others. The third is shut out from both." },
      { title: "After death", body: "“When a person dies, his deeds stop except for three,” one of them being knowledge that goes on benefiting people. “The one who points to good is like the one who does it.” “There is no envy except in two cases. One is a man God gave wisdom, who judges by it and teaches it. The other is a man God gave wealth, who spends it all on good.” “God's mercy be on my successors.” Who are they? “Those who revive my Sunna and teach it to God's servants.”" },
      { title: "A town where knowledge dies", body: "Umar said: “Whoever passes on a report and someone acts on it has the same reward as the one who acts.” Ibn Abbas said: “Everything asks forgiveness for the one who teaches people good, even the fish in the sea.” A scholar said: “The scholar steps between God and His creatures, so he should look at how he steps.” Sufyan al-Thawri came to Ascalon and stayed, and no one asked him anything. He said: “Hire me a mount so I can leave this town. This is a town where knowledge dies.” Ata found Sa'id ibn al-Musayyib weeping. He said: “No one asks me about anything.”" },
      { title: "Lamps of their age", body: "Someone said: “Scholars are the lamps of the ages. Each one is the lamp of his time, and the people of his age take light from him.” Al-Hasan said: “Without the scholars, people would be like animals.” Ghazali explains: by teaching, they lift people out of the level of animals to the level of humans. Ikrima said: “This knowledge has a price.” What is it? “That you place it with someone who will carry it well and not waste it.”" },
      { title: "Kinder than parents", body: "Yahya ibn Mu'adh said: “Scholars are more merciful to the community of Muhammad than their fathers and mothers.” How? “Their parents protect them from the fire of this world, and the scholars protect them from the fire of the next.” It was said: “The first step of knowledge is silence, then listening, then memorising, then acting, then spreading it.” And: “Teach what you know to those who do not know, and learn what you do not know from those who do. Then you will learn what you did not know and keep what you know.”" },
      { title: "Mu'adh's long saying", body: "Mu'adh ibn Jabal said, and Ghazali saw it also reported from the Prophet: “Learn knowledge. Learning it for God is fear of Him, seeking it is worship, studying it is glorifying God, and searching for it is striving. Teaching it to someone who does not know is charity, and giving it to those fit for it brings you near to God. It is company when you are alone and a friend in private. It guides to religion, keeps you patient in good times and bad, is a helper among friends and near among strangers, and lights the way to the Garden.”" },
      { title: "What knowledge does", body: "Mu'adh goes on: “By it God raises people and makes them leaders in good, whose footsteps are followed and whose deeds are watched. The angels want their friendship and brush them with their wings. Everything wet and dry asks forgiveness for them. So do the fish of the sea and its creatures, the wild beasts and cattle of the land, and the sky and its stars. Knowledge is life for hearts against blindness, light for eyes against darkness, and strength for bodies against weakness. By it a person reaches the levels of the righteous. Thinking about it equals fasting, and studying it equals praying at night. By it God is obeyed, worshipped, declared one and glorified. By it people are careful, keep family ties and know the lawful and forbidden. It leads and action follows. The fortunate are inspired with it and the wretched are denied it.”" },
    ],
    closer: [
      { title: "Knowledge that passes on", body: "Ghazali adds one line to the report about the scholars' intercession. It is for knowledge that passes to others through teaching, not for knowledge that stays with its owner." },
      { title: "The two who wept", body: "Sufyan leaving Ascalon and Sa'id ibn al-Musayyib weeping are the same story. They did not miss being famous. They were afraid of knowledge dying because no one asked for it." },
    ],
    distinction: ["Two kinds of knowledge in the teaching reports", "Knowledge that passes on", "Taught to others. It is what earns the scholars' intercession, and it goes on working after death.", "Knowledge kept", "Stays with its owner. Hidden when asked for, it earns a bridle of fire."],
    misreading: "The three kinds of ground are not three kinds of student sorted by cleverness. The second ground only holds the water and does not grow anything itself, yet people still drink from it. Passing knowledge on is praised even when the carrier is not the one who most benefits.",
    reflection: "Think of one useful thing you know but have never passed on to anyone. Who could you give it to this week?",
    audit: ["Do I hide what I know when someone needs it?", "Which ground am I in the parable of the rain?", "Do I place knowledge with people who will carry it well?", "Would I weep, like Sa'id, if no one asked me anything?"],
    nodes: ["talim", "ilm"],
    model: spectrum("The rain and three kinds of ground", "The Prophet's parable, as Ghazali reads it.", [["Ground that grows", "Takes in the water and grows plants: benefits from knowledge.", "support"], ["Ground that holds", "Stores the water for others to drink: benefits others.", "support"], ["Bare ground", "Neither holds nor grows: shut out from both.", "warning"]]),
  }),
  makeChapter({
    id: 6, shortTitle: "The argument from reason", formalTitle: "The rational evidence: what excellence means, why knowledge is sought, and why teaching is the noblest craft",
    overview: "Ghazali now argues without quotations. He defines excellence, sorts the things people want, and shows knowledge is wanted both for itself and for what it leads to. Then he sorts all human crafts and shows teaching is the noblest after prophethood.",
    thesis: "Knowledge is an excellence in itself, without comparing it to anything, because it is a perfection of God and the honour of angels and prophets. It is sweet in itself and it is the only road to lasting happiness. Teaching is the noblest craft because it works on the noblest part of the noblest creature.",
    moves: [
      { title: "First, what excellence means", body: "The aim of this chapter is to know the excellence of knowledge. But you cannot know if a thing has an excellence until you know what excellence is. Anyone who wants to know if Zayd is wise before he understands wisdom has lost his way. Excellence comes from a word meaning “more”. Two things may share a quality, and one may have more of it. Then we say it excels, as long as the extra is in what makes that kind of thing perfect." },
      { title: "The horse and the donkey", body: "So a horse is better than a donkey. It shares the donkey's strength for carrying loads, and adds charging, turning, speed and good looks. Suppose a donkey had a huge growth on its back. We would not call it better. That is extra body and less meaning, and animals are valued for their qualities, not their bulk. Speed is an excellence in a horse only compared with other animals. Knowledge is an excellence in itself, without comparing it to anything. It is a quality of God's perfection, and by it the angels and prophets are honoured. Even among horses, the clever one is better than the dull." },
      { title: "Three ways of being wanted", body: "Precious things are wanted in three ways. Some are wanted for something else, like coins of gold and silver. They are just two stones with no use; if God had not made them a means of meeting needs, they would be no different from gravel. Some are wanted for themselves, like happiness in the next life and the joy of looking at God's face. Some are wanted for both reasons, like a healthy body. A healthy leg is wanted because it is free of pain, and also because it carries you where you need to go." },
      { title: "Knowledge is wanted both ways", body: "Looked at this way, knowledge is sweet in itself, so it is wanted for its own sake. It is also the means to the next life and its happiness, and the way to nearness to God, which can only be reached through it. The greatest thing for a human is lasting happiness, and the best thing is what leads to it. That is only reached by knowledge and action, and action is only reached by knowing how to act. So the root of happiness in both worlds is knowledge, and it is the best of all works." },
      { title: "Its fruit in both worlds", body: "A thing's excellence is also known by its fruit. The fruit of knowledge in the next life is nearness to the Lord of the worlds. It is joining the horizon of the angels, and keeping company with the highest assembly. In this world its fruit is honour and dignity, authority over kings, and a respect built into human nature. Even dull Turks and uncouth desert Arabs honour their elders because they know more from experience. Even an animal by instinct respects a human, sensing a perfection beyond its own. After this, the sciences differ in excellence, as will be shown." },
      { title: "Why learning and teaching follow", body: "The excellence of learning and teaching follows from this. If knowledge is the best thing, learning it is seeking the best, and teaching it is giving the best. People's aims all come down to religion and this world, and religion is only in order when this world is in order. This world is the farm of the next life. It is a tool that takes you to God if you use it as a tool and a stopping place, not as a home to settle in forever. This world is kept in order only by what people do." },
      { title: "Three kinds of craft", body: "Human crafts come in three kinds. First are the roots, without which the world cannot stand. There are four: farming for food, weaving for clothing, building for shelter, and governing, which brings people together to cooperate in making a living. Second are crafts that serve the roots, like blacksmithing, which makes tools for farming, or carding and spinning, which prepare work for weaving. Third are crafts that complete and adorn the roots, like milling and baking for farming, and bleaching and tailoring for weaving." },
      { title: "Like the parts of a body", body: "These relate to the world as parts relate to a body. Some organs are roots, like the heart, liver and brain. Some serve them, like the stomach, veins, arteries and nerves. Some complete and adorn, like nails, fingers and eyebrows. The noblest crafts are the roots, and the noblest root is governing, by bringing people together and setting them right. It asks more perfection of the person who does it than any other craft, and so it uses all the other craftsmen." },
      { title: "Four levels of guiding people", body: "Governing people and guiding them to the straight road has four levels. Highest is the prophets, whose authority covers the elite and the common, in their outward and inward lives. Second are caliphs, kings and sultans, who rule the elite and the common, but only outwardly. Third are the scholars who know God and His religion, the heirs of the prophets. Their authority is over the inner life of the elite only; ordinary people cannot rise to learn from them, and they cannot force anyone outwardly. Fourth are the preachers, whose authority is over the inner life of ordinary people only." },
      { title: "Three measures of a craft", body: "So the noblest of these after prophethood is giving knowledge, and training people away from destructive traits towards traits that bring happiness. That is what teaching means. A craft's nobility is measured three ways. One is the faculty that grasps it; the rational sciences are above language, since reason is above hearing. Another is how widely it helps; farming is above goldsmithing. The last is the material it works on; goldsmithing is above tanning, since one works gold and the other the hide of a dead animal." },
      { title: "Teaching passes all three", body: "The religious sciences, which are understanding of the road to the next life, are grasped by perfect reason and a clear mind. Reason is the noblest human quality, since by it God's trust is accepted and people reach nearness to Him. As for benefit, there is no doubt: its fruit is happiness in the next life. As for material, the teacher works on human hearts. The noblest thing on earth is the human race, and the noblest part of a human is the heart. The teacher is busy perfecting it, polishing it, cleansing it and leading it towards God." },
      { title: "The keeper of the treasury", body: "So teaching knowledge is in one way worship of God, and in another way acting as God's deputy, and the greatest kind. God has opened the heart of the scholar to knowledge, the most special of His qualities. The scholar is like the keeper of His most precious treasury, with permission to spend from it on everyone in need. What level is higher than standing between a person's Lord and His creatures, bringing them nearer to God and leading them to the Garden? Ghazali closes with a prayer to be among them." },
    ],
    closer: [
      { title: "Not bigger, but more of what matters", body: "The donkey with the lump is Ghazali's quiet warning. More of something is not excellence unless it is more of what makes the thing good. A lot of learning that adds nothing to the heart may be a lump, not a gift." },
      { title: "Why this world matters too", body: "The argument runs through farming and weaving before it reaches teaching. This world is the farm of the next, so the crafts that keep it running are part of the case, not a distraction from it." },
    ],
    distinction: ["Two ways a thing can be excellent", "Compared with others", "Like a horse's speed: an excellence only when set beside other animals.", "In itself", "Like knowledge: an excellence without comparing it to anything, because it is a perfection of God."],
    misreading: "Ghazali does not look down on farmers or weavers here. They are the roots the world stands on. The ranking is about what each craft works on and what it serves, and it puts governing among the roots with them.",
    reflection: "Ghazali says the world is a tool for those who use it as a tool, and a trap for those who settle in it. Which way are you using it this week?",
    audit: ["Do I want knowledge for itself, for the road, or only for status?", "Is my learning extra meaning, or just extra bulk?", "Do I treat this world as a stopping place or a home?", "What do I help to polish in other people's hearts?"],
    nodes: ["ilm", "talim", "aql"],
    model: chain("The argument in steps", "From definition to the teacher's level.", [["Excellence", "More of what perfects a thing; knowledge is excellent in itself.", "support"], ["Wanted both ways", "Sweet in itself and the only road to lasting happiness.", "support"], ["Three kinds of craft", "Roots, servants and completers; governing is the noblest root.", "balance"], ["Teaching", "Works on the noblest material, by the noblest faculty, for the widest good.", "support"]]),
  }),
  makeChapter({
    id: 7, shortTitle: "More than twenty answers", formalTitle: "The knowledge that is a personal duty: the twenty groups, and Ghazali's rule of the act and its time",
    overview: "The Prophet said seeking knowledge is a duty on every Muslim. More than twenty groups argued over which knowledge he meant, and each named its own subject. Ghazali's answer is not a subject. It is knowing how to do what is due, when it becomes due.",
    thesis: "The duty is knowledge of practice: what to believe, what to do and what to avoid. It grows with a person's life. Someone who comes of age at mid-morning owes only the two testimonies and their meaning. Each later duty brings its knowledge with it.",
    moves: [
      { title: "The famous saying", body: "The Prophet said: “Seeking knowledge is a duty on every Muslim.” He also said: “Seek knowledge, even as far as China.” People disagreed about which knowledge is a duty on every Muslim, and split into more than twenty groups. Ghazali will not list every detail. The sum of it is that each group put the duty on the knowledge it was already busy with." },
      { title: "Each group names its own", body: "The theologians said it is theology, because through it God's oneness is grasped, and His being and qualities are known. The lawyers said it is law, because through it worship, the lawful and forbidden, and what is allowed and forbidden in dealings are known. They meant what ordinary people need, not rare cases. The Quran commentators and the hadith scholars said it is the Book and the Sunna, because every other science is reached through them." },
      { title: "The Sufis, and Abu Talib", body: "The Sufis said it is their knowledge. Some said it is a person knowing his own state and level with God. Some said it is knowing sincerity and the harms of the self, and telling the angel's prompting from Satan's. Some said it is inner knowledge, which is a duty only on the particular people suited to it. Those last ones turned the word “every” away from its plain meaning. Abu Talib al-Makki said it is knowing what is in the report about the five pillars. Those five are what is required, so one must know how to do them." },
      { title: "Ghazali's answer", body: "What a careful person should hold firmly is this. As said in the introduction, knowledge is either of practice or of unveiling. This saying means only knowledge of practice. The practice required of a sane adult is of three kinds: belief, doing and not doing. Suppose a sane man comes of age at mid-morning, either by the signs of puberty or by reaching the age. His first duty is to learn the two testimonies of faith and understand them: there is no god but God, and Muhammad is the messenger of God." },
      { title: "Belief without proofs", body: "He does not have to work this out for himself by study, searching and setting out proofs. It is enough that he believes it firmly, without a flicker of doubt or unease. That can come simply by accepting what he hears from others, without searching or proof. The Prophet accepted belief and acknowledgement from the rough desert Arabs without their learning any proof. If the man does that, he has done the duty of the moment. If he died straight after, he would die obeying God, not disobeying Him." },
      { title: "Duties arrive one by one", body: "Anything more becomes due only because of something that comes up, and that is not the same for everyone. It comes up in doing, in not doing, or in belief. Suppose he lives from mid-morning to the time of the midday prayer. Now he must learn purification and prayer. Suppose he is healthy, and waiting until noon would leave him no time both to learn and to pray in time. Then it may be said he must learn beforehand. It may also be said the knowledge that is a condition of an act is only due once the act is due. The same holds for the other prayers." },
      { title: "The fast", body: "If he lives until Ramadan, he must now learn about fasting. Its time runs from dawn to sunset. What is required is the intention and holding back from food, drink and intercourse. It goes on until the new moon is seen, or two witnesses say they saw it." },
      { title: "Only the alms on camels", body: "If he comes into wealth, or had some when he came of age, he must learn the alms due on it. But not straight away. It is due when a full year has passed since he became Muslim. If all he owns is camels, he only has to learn the alms on camels, and the same for every other kind of property." },
      { title: "The pilgrimage can wait", body: "When the months of pilgrimage come, he does not have to rush to learn about it, since the pilgrimage itself may be delayed. So learning it is not urgent either. But the scholars of Islam should tell him that the pilgrimage is a duty, which may be delayed, on everyone who has provisions and a mount. Then he may decide it is wiser to go soon. When he decides to go, he must learn how to do it. He only has to learn its pillars and required parts, not the extras. If an act is voluntary, learning it is voluntary too. Whether it is sinful to stay silent about the duty of pilgrimage is a question for the lawyers." },
    ],
    closer: [
      { title: "What the twenty groups shared", body: "Each gave real reasons. What Ghazali notices is that the answers match the answerers. Not one group said the duty was something it had not yet learned." },
      { title: "The man who dies at noon", body: "The picture of the young man who dies the same day is the heart of the rule. If he learned and believed the testimony that morning, he died obeying God. Nothing else had yet become due." },
    ],
    distinction: ["Two ways to read the duty", "A subject to master", "Each group's reading: the duty is my field, whole.", "The act and its time", "Ghazali's reading: learn what is now due for you to do, avoid or believe, when it becomes due."],
    misreading: "Ghazali is not saying the scholars' subjects are useless, or that the duty is small. It grows with each new situation, and he goes on to make the heart's sicknesses a duty for almost everyone.",
    reflection: "List what became due for you this month: a prayer, a fast, a purchase, a trip. Did you learn what each one required?",
    audit: ["What is due for me right now?", "Have I learned the pillars of what I am about to do?", "Do I confuse my favourite subject with my duty?", "What have I put off learning that is already due?"],
    nodes: ["fard-ayn", "parties", "occasion"],
    model: chain("How the duty grows", "Ghazali's own examples, in order.", [["Coming of age", "The two testimonies and their meaning, believed firmly.", "support"], ["Noon", "Purification and prayer.", "support"], ["Ramadan", "The fast: its time, intention and what breaks it.", "support"], ["Wealth and pilgrimage", "Alms after a year, only on what you own; pilgrimage when you decide to go.", "balance"]]),
  }),
  makeChapter({
    id: 8, shortTitle: "What you avoid, believe and feel", formalTitle: "The personal duty continued: things to avoid, doubts in belief, the sicknesses of the heart, and the next life",
    overview: "The same rule covers what a person must avoid and what he must believe. It also reaches the heart. Because almost no one is free of greed, desire and self-admiration, learning their cure is a duty for nearly everyone, and nearly everyone has left it.",
    thesis: "What you must avoid depends on your situation. What you must believe grows with the doubts that come to you. The sicknesses of the heart are with everyone, so knowing their causes and cures is a personal duty. Most of the Quarter of Things that Destroy is a personal duty that people have abandoned.",
    moves: [
      { title: "What you must avoid", body: "Knowledge of what to avoid is due as situations arise, and it differs by person. Someone who cannot speak does not have to learn which speech is forbidden. A blind person does not have to learn which looking is forbidden. A desert nomad does not have to learn which town dwellings are forbidden to sit in. What he is sure never to meet, he need not learn. What he is involved in, he must be told about. If, when he becomes Muslim, he is wearing silk, sitting on stolen land or looking at someone he should not, he must be told." },
      { title: "What is close at hand", body: "What he is not yet involved in, but soon will be, like eating and drinking, he must also be taught. If he lives in a town where people drink wine and eat pork, he must be taught about that and warned. Whatever must be taught to him, he must learn." },
      { title: "Doubts in belief", body: "Beliefs and the acts of the heart must be learned as thoughts come. If a doubt comes to him about what the two testimonies mean, he must learn enough to remove it. Suppose no such doubt comes. He dies before believing that God's speech is eternal, that God will be seen, or that God is not a place where changes happen. He still dies a Muslim, by agreement of all. Some such thoughts arise by nature. Others come from hearing what people in the town say." },
      { title: "Protect the young early", body: "Suppose he lives in a town where theology has spread and people talk of heresies. Then he should be protected at the start of adulthood by being taught the truth. If falsehood were put into his heart first, it would then have to be removed, and that can be hard. It is like a Muslim trader in a town where dealing in interest has spread: he must learn to guard against it. This, Ghazali says, is the truth about the personal duty. It means knowing how to do what is required. Whoever knows the required knowledge and when it is due has the knowledge that is a personal duty." },
      { title: "The Sufis were partly right", body: "What the Sufis said about understanding the enemy's whispers and the angel's prompting is also true, but for those who take up that path. Yet most people are never free of urges to evil, showing off and envy. So each person must learn from the Quarter of Things that Destroy whatever he sees he needs. How could it not be a duty? The Prophet said: “Three things destroy: greed that is obeyed, desire that is followed, and a person's admiration of himself.” No human being is free of them." },
      { title: "Why it is a duty", body: "The other blamed states of the heart, like pride and self-admiration and their sisters, follow from these three. Removing them is a personal duty. They cannot be removed without knowing their definitions, their causes, their signs and their cure. Whoever does not know evil falls into it. The cure is to meet a cause with its opposite, and how can you do that without knowing the cause and what it produces? Most of what is in the Quarter of Things that Destroy is a personal duty. People have all left it, busy with what does not concern them." },
      { title: "The Garden and the Fire", body: "One more thing should be taught to him quickly, if he has not simply moved from one religion to another. It is belief in the Garden and the Fire, and in the gathering and the raising of the dead. This completes the two testimonies. After accepting that Muhammad is God's messenger, he should understand the message he brought. Whoever obeys God and His messenger has the Garden, and whoever disobeys them has the Fire." },
      { title: "Your day and night", body: "Once you notice this step-by-step pattern, you will see this is the right view. Every person, day and night, meets situations in his worship and dealings that bring new duties. So he must ask about each unusual thing that happens to him. He must hurry to learn what is likely to happen soon. The Prophet said “seeking the knowledge”, with the definite article. He meant the knowledge of practice whose duty is well known to Muslims, nothing else. Then both the steps and the time each becomes due are clear." },
    ],
    closer: [
      { title: "The duty nobody takes up", body: "Ghazali's strongest claim in this chapter is that knowing the heart's sicknesses is a personal duty, and that everyone has left it. The lawyers and theologians had each named their own field; he names the one no one had named." },
      { title: "Three roots", body: "Greed obeyed, desire followed and self-admiration are the roots. Pride and the other diseases are their branches. Knowing the roots is the start of the cure." },
    ],
    distinction: ["Two kinds of personal duty in this section", "Outward duties", "Knowing what to do and avoid in the situations you are actually in.", "The heart's duty", "Knowing the causes, signs and cures of the destroying traits that nearly everyone carries."],
    misreading: "Ghazali does not tell every beginner to study theology. He says the opposite: if no doubt arises, a person who dies without theology dies a Muslim. Teaching the truth early is for towns where false ideas are already in the air.",
    reflection: "Pick one of the three destroyers: greed, desire, or admiring yourself. Can you name its cause in your own life?",
    audit: ["What forbidden thing am I close to that I have not learned about?", "Which doubts have come to me, and have I cleared them?", "Do I know the signs of my own pride?", "Have I left a personal duty for things that do not concern me?"],
    nodes: ["fard-ayn", "muhlikat", "qalb"],
    model: chain("From the situation to the duty", "The rule, applied beyond acts.", [["What you avoid", "Due when you are in it or close to it.", "support"], ["What you believe", "Due as doubts come, or early in a town full of heresy.", "support"], ["The three destroyers", "Greed, desire, self-admiration: in everyone.", "warning"], ["Their cure", "A personal duty, and the one people have abandoned.", "support"]]),
  }),
  makeChapter({
    id: 9, shortTitle: "The map of the sciences", formalTitle: "The knowledge that is a communal duty: religious and non-religious sciences, and their four kinds",
    overview: "To see what is a communal duty, Ghazali maps the sciences. Non-religious sciences can be praised, blamed or permitted. Religious sciences are all praised, and come in four kinds: roots, branches, tools and completions.",
    thesis: "A communal duty is whatever a town cannot do without. If no one does it, everyone sins; if one does it, the others are free. That includes medicine and arithmetic, and also farming, weaving, cupping and tailoring. All the religious sciences are communal duties too.",
    moves: [
      { title: "Religious and not", body: "A duty cannot be picked out without listing the sciences. For this purpose they are religious or not. By religious Ghazali means what was learned from the prophets. Reason does not lead to it, as it does to arithmetic. Experience does not lead to it, as it does to medicine. Hearing does not lead to it, as it does to language. Non-religious sciences are praised, blamed or permitted." },
      { title: "Medicine and arithmetic", body: "The praised ones are those tied to the good of this world, like medicine and arithmetic. Some are communal duties and some are just extra merit. A communal duty is knowledge the world cannot do without. Medicine is needed to keep bodies alive. Arithmetic is needed for dealings, wills and inheritances. If a town has no one doing these, its people sin; if one person does them, it is enough and the duty lifts from the rest." },
      { title: "Even the cupper", body: "Do not be surprised that medicine and arithmetic are communal duties. The root crafts are too: farming, weaving, governing, even cupping and tailoring. If a town had no cupper, death would come quickly to its people, and they would sin by putting themselves in danger. The One who sent down the illness sent down the cure, pointed to how to use it and prepared the means. So neglecting it and courting death is not allowed." },
      { title: "Extra merit, blame and permission", body: "Going deep into fine points of arithmetic and the finer truths of medicine is extra merit, not a duty. It is not needed, but it adds strength to what is needed. The blamed sciences are magic and talismans, conjuring and tricks. The permitted are poetry with nothing indecent in it, histories and the like." },
      { title: "The religious sciences", body: "The religious sciences, which are the real subject here, are all praised. But some things are mistaken for them that are blamed. The praised ones have roots, branches, preliminaries and completions: four kinds. The roots are four: God's Book, the Sunna of His messenger, the agreement of the community, and the reports of the Companions. Agreement is a root because it points to the Sunna, so it is a root of the third degree." },
      { title: "Why the Companions count", body: "The Companions' reports also point to the Sunna. They witnessed revelation as it came down, and grasped from the circumstances what others did not see. Words cannot always hold what is grasped from circumstances. That is why scholars thought it right to follow them and hold to their reports, under particular conditions, for those who hold this view. Explaining those conditions does not belong in this book." },
      { title: "The branches", body: "The branches are what is understood from the roots, not from their literal words but from meanings that minds notice. Understanding widens until one understands from a word something beyond it. The Prophet said: “A judge should not judge while angry.” From this it is understood that he should not judge while afraid, hungry or in pain from illness. The branches are of two kinds. One concerns the good of this world; the law books hold it, the lawyers take charge of it, and they are the scholars of this world." },
      { title: "The branch for the next life", body: "The second kind concerns the good of the next life. It is the knowledge of the states of the heart and its praised and blamed traits, of what pleases God and what He dislikes. The second half of the Ihya holds it. Part of it is knowing what flows from the heart into the limbs, in their worship and customs. The first half of the Ihya holds that." },
      { title: "The tools", body: "The preliminaries are like tools. Language and grammar are tools for knowing God's Book and His Prophet's Sunna. They are not religious sciences in themselves, but religion requires them, because this law came in Arabic, and every law appears only in a language. So learning that language becomes a tool. Writing is also a tool, though not strictly necessary: the Prophet could not read or write. If memory could hold everything heard, writing would not be needed, but since memory usually fails, it has become necessary." },
      { title: "The completions", body: "The completions are, for the Quran, what concerns its wording, like the readings and how letters are pronounced. They include what concerns its meaning, like commentary, which also rests on transmission, since language alone is not enough. They include what concerns its rulings, like abrogating and abrogated verses, general and specific, explicit and apparent, and how they fit together. That is the science called the principles of law, and it covers the Sunna too. For reports, the completions are knowing the narrators. That means their names and lineages, the Companions' names and qualities, and the narrators' trustworthiness, states and ages. These tell strong from weak and connected from broken chains. All these are praised, and all are communal duties." },
    ],
    closer: [
      { title: "A religious duty to sew", body: "The list that puts cupping and tailoring beside medicine is the most surprising part. Ghazali's reason is plain: a town that neglects them puts itself in danger, and courting danger is a sin." },
      { title: "A religious science defined by its source", body: "The religious sciences are marked out by where they come from. Reason, experience and hearing all reach real knowledge. What they cannot reach is what came from the prophets." },
    ],
    distinction: ["Two kinds of praised non-religious knowledge", "Communal duty", "What the world cannot do without: medicine, arithmetic, the root crafts, cupping, tailoring.", "Extra merit", "Going deep into their fine points: not needed, but it strengthens what is needed."],
    misreading: "Calling law “a science of this world” here is not an insult. It sits among the praised religious sciences, and is a communal duty. The next section explains exactly why Ghazali puts it on the side of this world.",
    reflection: "Think of a craft in your town that no one would call religious. By Ghazali's test, is it a communal duty?",
    audit: ["Who in my community is carrying a duty for all of us?", "Do I treat language and grammar as ends or as tools?", "Is my deep study a strength for what is needed, or a distraction from it?", "Which of the four kinds of religious science do I know?"],
    nodes: ["fard-kifaya", "shariyya", "dunya"],
    model: chain("The map of the sciences", "Ghazali's divisions for this purpose.", [["Non-religious", "Praised (duty or extra), blamed (magic, tricks), or permitted (clean poetry, history).", "balance"], ["Religious roots", "The Book, the Sunna, agreement, the Companions' reports.", "support"], ["Branches", "Law for this world; the heart's knowledge for the next.", "support"], ["Tools and completions", "Language, grammar, writing; readings, commentary, principles, narrator studies.", "balance"]]),
  }),
  makeChapter({
    id: 10, shortTitle: "Why law serves this world", formalTitle: "Why law is counted a science of this world: the ruler, the law and the guard on the pilgrim road",
    overview: "Ghazali explains why he put law among the sciences of this world. People take the world with greed, so they quarrel. They need a ruler, and the ruler needs a law. The lawyer knows that law. It serves religion, but through this world.",
    thesis: "Law is the knowledge of the rules by which the ruler keeps people from harming each other. That keeps the world in order, and the world is the farm of the next life. So law is linked to religion, but at one remove, like the guard who keeps the pilgrim road safe.",
    moves: [
      { title: "From dust to the Garden", body: "Why is law with the sciences of this world? God brought Adam out of dust and his children out of an extract of clay and gushing water. He moved them from loins to wombs, then into the world, then to the grave, then to the reckoning, then to the Garden or the Fire. That is where they begin, where they end, and the stops along the way." },
      { title: "Why there are lawyers", body: "God created the world as provision for the return, for people to take from it what serves as provision. If they took from it fairly, quarrels would stop and lawyers would have nothing to do. But they took it with greed, so quarrels arose. They needed a ruler to govern them, and the ruler needed a law to govern them by. The lawyer is the one who knows that law, and how to settle between people when greed makes them fight." },
      { title: "Teacher of the ruler", body: "So the lawyer is the ruler's teacher and guide in governing and controlling people, so that their worldly affairs are kept in order. This is linked to religion too, Ghazali grants, but not in itself. It is linked through the world, because the world is the farm of the next life, and religion is only complete with the world." },
      { title: "Twins", body: "Kingship and religion are twins. Religion is the foundation and the ruler is the guard. What has no foundation falls down, and what has no guard is lost. Kingship and order only work with a ruler, and the way to order in settling disputes is law. Governing people is not religious knowledge in the first degree. It helps with what religion cannot be complete without. So is knowing how to govern." },
      { title: "Four things on the pilgrim road", body: "The pilgrimage can only be completed with an escort to guard against raiders on the road. But the pilgrimage is one thing. Travelling the road to it is a second. Guarding the road, without which the pilgrimage cannot happen, is a third. Knowing the methods, tricks and rules of guarding is a fourth. The whole of law is knowing the ways of governing and guarding." },
      { title: "Only three give rulings", body: "A report shows this: “Only three give rulings to people: a ruler, someone he appoints, or someone who takes it on without need.” The ruler is the imam, and in early times the rulers were the ones who gave rulings. The appointed one is his deputy. The third takes on that burden with no need. In some versions, instead of “takes it on” the word is “the show-off”. Whoever takes on the danger of giving rulings when he is not needed can only be after status and money." },
      { title: "The Companions passed it on", body: "The Companions used to avoid giving rulings, each passing the question to another. But they did not hold back when asked about the Quran and the road to the next life." },
      { title: "An objection", body: "Someone may say: this works for wounds, criminal penalties, fines and settling disputes. But it does not work for fasting and prayer in the Quarter of Worship, or for the lawful and forbidden in dealings. Ghazali answers: the nearest the lawyer comes to deeds of the next life are three: Islam, prayer and alms, and the lawful and forbidden. Look at how far his view reaches in these, and you will see it never passes beyond this world to the next. If that is true of these three, it is clearer still for the rest. The next section takes each one." },
    ],
    closer: [
      { title: "Religion and the guard", body: "The twin image is exact. Religion is the foundation; the ruler and his law are the guard. Neither is useless. But the guard is not the thing guarded." },
      { title: "The pilgrim's four", body: "The pilgrimage, the road, the guarding and the knowledge of guarding are four different things. Law, in Ghazali's picture, is the fourth." },
    ],
    distinction: ["Two things the pilgrim needs", "The pilgrimage itself", "The act of worship, done for God.", "The guarding of the road", "Needed for the pilgrimage to happen, but not part of it. Law and governing are like this."],
    misreading: "Ghazali does not say law is unimportant or unrelated to religion. He says it serves religion through the world, and that the world is the farm of the next life. His complaint is only about those who treat it as the road itself.",
    reflection: "Think of a rule you follow. Does it keep the road safe, or is it the journey itself?",
    audit: ["Do I confuse guarding the road with walking it?", "If I give rulings, is it because I am needed?", "Do I take from the world fairly, or with greed?", "What do I know about the road to the next life, beyond the rules?"],
    nodes: ["fiqh", "dunya"],
    model: chain("Four things on the pilgrim road", "Ghazali's picture of where law stands.", [["The pilgrimage", "The worship itself.", "support"], ["The road", "Travelling to it.", "balance"], ["The guard", "Needed for safety: the ruler.", "balance"], ["Knowing how to guard", "The law and its rules: the lawyer's field.", "balance"]]),
  }),
  makeChapter({
    id: 11, shortTitle: "What the lawyer can see", formalTitle: "The lawyer's reach in Islam, prayer, alms and the lawful: the four levels of caution, and why law is still above medicine",
    overview: "Ghazali takes the three places where law comes closest to the next life. In each, the lawyer judges only the outward act. The heart, where the next life is won, is outside his field. Yet law is still nobler than medicine, for three reasons.",
    thesis: "The lawyer rules on the tongue's testimony, the prayer's outward form, what satisfies the tax collector, and the lowest level of caution. None of that decides what happens in the next life. Law is still above medicine, because it comes from prophethood, everyone needs it, and it borders on the knowledge of the heart.",
    moves: [
      { title: "Islam: the tongue only", body: "On Islam, the lawyer speaks of what makes it valid or invalid and its conditions. He looks only at the tongue. The heart is outside his authority. The Prophet removed people of sword and power from judging it. A man killed someone who had spoken the testimony. He excused himself by saying the other only said it from fear of the sword. The Prophet said to him: “Did you split open his heart?”" },
      { title: "Under the shadow of swords", body: "The lawyer rules that Islam is valid even under the shadow of swords. He knows the sword has not shown him the man's intention or lifted ignorance and confusion from his heart. But he advises the man with the sword. The sword is reaching for his neck and the hand for his money. The word on the tongue protects both, as long as he has a neck and money. That is in this world. The Prophet said: “I was commanded to fight people until they say there is no god but God. When they say it, they protect their blood and property from me.” He tied its effect to blood and property. In the next life, money is no use. What helps there are the lights of hearts, their secrets and their sincerity. That is not law." },
      { title: "Prayer: valid but useless", body: "On prayer, the lawyer rules it valid if the outward acts and conditions are done. That holds even if the person was absent-minded from start to finish, busy working out his market accounts, except at the opening words. Such a prayer is no use in the next life, just as the tongue's testimony alone is no use. The lawyer's ruling means only that the form of the command was obeyed, and that it protects him from being killed or punished. Humility and presence of heart, which are the work of the next life and give outward acts their value, are not the lawyer's business." },
      { title: "Alms: Abu Yusuf's trick", body: "On alms, the lawyer looks at what ends the ruler's claim. If a man refused to pay and the ruler took it by force, the lawyer rules he is clear of it. It is said that Abu Yusuf the judge used to give his wealth to his wife near the end of the year. Then he took hers as a gift, to avoid alms. This was told to Abu Hanifa, who said: “That is part of his understanding.” Ghazali says he was right. It is the understanding of this world. But its harm in the next life is greater than any crime. This is harmful knowledge." },
      { title: "Four levels of caution", body: "On the lawful and forbidden: caution about the forbidden is part of religion, but caution has four levels. The first is the caution needed to be accepted as a witness. Without it a person cannot be a witness, judge or official. It is avoiding what is plainly forbidden. The second is the caution of the righteous: avoiding doubtful things where the possibilities are balanced. The Prophet said: “Leave what makes you doubt for what does not.” And: “Sin is what scratches at hearts.”" },
      { title: "The pious and the truthful", body: "The third is the caution of the God-fearing: leaving what is purely lawful for fear it may lead to the forbidden. The Prophet said: “A man is not among the God-fearing until he leaves what is harmless for fear of what is harmful.” An example is avoiding talk about people's affairs for fear of sliding into backbiting. Another is avoiding rich food for fear of stirring up lust and wildness that lead to sin. The fourth is the caution of the truthful saints: turning from everything but God. They fear spending one hour of life on what does not bring them nearer to Him, even when they know it leads to nothing forbidden." },
      { title: "Ask your heart", body: "All these levels are outside the lawyer's view except the first: the caution of witnesses and judges, and what harms uprightness. Keeping that level does not remove sin in the next life. The Prophet said to Wabisa: “Ask your heart for a ruling, even if they give you rulings, and give you rulings.” The lawyer does not speak of what scratches at hearts. His whole view is tied to the world, through which the road to the next life is kept in order. If he speaks of the heart or the next life, it is as a guest in someone else's house. He might equally mention some medicine, arithmetic, astronomy or theology, or as wisdom creeps into grammar and poetry." },
      { title: "Sufyan's judgment", body: "Sufyan al-Thawri, a leading scholar of outward knowledge, used to say that seeking this was not provision for the next life. How could it be? All agree that the honour of knowledge lies in acting on it. How could anyone think that means knowledge of a husband's oath of separation, or mutual cursing, or advance sales, hire and currency exchange? Whoever learns these to come near to God is mad. Action is by the heart and the limbs in acts of obedience, and the honour lies in those acts." },
      { title: "Above medicine, in three ways", body: "Someone may ask: have you made law equal to medicine? Medicine also concerns this world, the health of the body, and religion also depends on that. That would go against the agreement of Muslims. Ghazali answers that they are not equal. Law is nobler in three ways. First, it is a religious science, learned from prophethood; medicine is not. Second, no one on the road to the next life can do without it, healthy or sick, while only the sick need medicine, and they are the few. Third, law borders on the knowledge of the road to the next life. It looks at the acts of the limbs, and their source is the traits of the heart. Praised acts come from praised traits that save in the next life, and blamed acts from blamed ones. Health and illness come from the body's balance, not from the heart. So beside medicine, law's honour shows; and beside the knowledge of the road, that knowledge's honour shows." },
    ],
    closer: [
      { title: "A valid prayer that is useless", body: "The absent-minded prayer is the sharpest example. The lawyer is right to call it valid. It is still of no use in the next life. Both are true at once, because they answer different questions." },
      { title: "Abu Hanifa was right", body: "Ghazali agrees with Abu Hanifa that the alms trick showed understanding. Then he turns the word around: the understanding of this world, whose harm in the next is greater than any crime." },
    ],
    distinction: ["Two judgments on the same prayer", "The lawyer's", "Valid, if the outward acts and conditions are met: the command's form is obeyed and he is safe from punishment.", "The next life's", "Worth only as much as the humility and presence of heart in it."],
    misreading: "This is not an attack on the Shafii, Hanafi or any other school. Ghazali himself was a leading lawyer. He is marking where the lawyer's authority ends, and warning against mistaking a valid act for an accepted one.",
    reflection: "Think of your last prayer. Would the lawyer call it valid? Would it count for much in the next life?",
    audit: ["Which of the four levels of caution do I keep?", "Have I used a legal trick to get out of a duty?", "Do I ask my heart, as well as the lawyer?", "Is my prayer valid only, or alive?"],
    nodes: ["fiqh", "wara", "qalb"],
    model: spectrum("Four levels of caution", "Only the first is the lawyer's concern.", [["Witnesses", "Avoiding the plainly forbidden; needed to be upright.", "balance"], ["The righteous", "Avoiding the doubtful: leave what makes you doubt.", "support"], ["The God-fearing", "Leaving some lawful things for fear of the forbidden.", "support"], ["The truthful", "Turning from all but God, to waste no hour.", "support"]]),
  }),
  makeChapter({
    id: 12, shortTitle: "The knowledge of the road", formalTitle: "The knowledge of the road to the next life: unveiling, practice, and the scholars who knew its worth",
    overview: "Ghazali now describes the knowledge of the road to the next life. It has two parts: unveiling, a light in the purified heart, and practice, the knowledge of the heart's praised and blamed states. The lawyers of his day knew every detail of rare rulings, and nothing of sincerity.",
    thesis: "Unveiling is the goal: a light in the cleansed heart by which the truth of God, His acts and the next life becomes as clear as seeing. The road to it is polishing the heart's mirror. The knowledge of practice teaches how, and it is a personal duty that the lawyers of the age had left.",
    moves: [
      { title: "Unveiling: a warning", body: "The knowledge of the road has two parts: unveiling and practice. Unveiling is inner knowledge, and it is the goal of all knowledge. One of the knowers said: “If someone has no share of this knowledge, I fear a bad end for him. The least share is to believe in it and leave it to its people.” Another said: “Two traits keep this knowledge shut to anyone: innovation and pride.” It was said that someone who loves the world or holds on to a desire will not attain it, though he may attain other sciences. The least punishment for denying it is never tasting any of it." },
      { title: "A light in the cleansed heart", body: "This is the knowledge of the truthful and those brought near. It is a light that appears in the heart when it is cleansed of its blamed traits. By this light many things become clear whose names a person heard before and pictured only vaguely. Real knowledge comes of God's being, His lasting and perfect qualities, and His acts. It comes of His wisdom in creating this world and the next, and why He set the next after this one." },
      { title: "What becomes clear", body: "It makes clear what prophethood and a prophet are, what revelation is, what Satan is, and what the words angels and devils mean. It shows how devils are enemies to people, how the angel appeared to the prophets, and how revelation reached them. It shows the unseen kingdom of the heavens and the earth. It shows the heart, with the armies of angels and devils clashing in it, and the difference between the angel's prompting and Satan's." },
      { title: "The next life, seen clearly", body: "It makes clear the next life, the Garden and the Fire, the punishment of the grave, the bridge, the scales and the reckoning. It shows the meaning of “Read your record; today you are enough to take account of yourself.” It shows the meaning of “The home of the next life is the true life, if only they knew.” It shows what meeting God means, and looking at His noble face, and being near Him and living in His neighbourhood. It shows the happiness of the company of the highest assembly, the angels and the prophets. It shows how the people of the Garden differ in level, so that some see others as one sees a shining star deep in the sky." },
      { title: "Different views", body: "After believing the basics of these things, people hold many views about their meaning. Some see all of it as images. They say that what God has prepared for His righteous servants is what no eye has seen, no ear has heard, and no heart has imagined. People only have the names and qualities of the Garden. Some see part as images and part as literally what the words say. Some say the end of knowing God is admitting you cannot know Him. Some claim great things in knowing God. Some say knowing God reaches no further than what ordinary people believe: that He exists, knows, is able, hears, sees and speaks." },
      { title: "The rusted mirror", body: "By unveiling Ghazali means that the cover is lifted, so the truth of these things becomes as clear as seeing with the eye, beyond any doubt. That is possible for the human soul, except that the heart's mirror has gathered rust and filth from the dirt of the world. By the knowledge of the road he means knowing how to polish this mirror of the filth that veils it from God, His qualities and His acts. It is cleaned by holding back from appetites and following the prophets in all their states. The more of the heart is cleared and faces the truth, the more its truths shine in it. The only way is training, explained later, and learning and teaching." },
      { title: "Not written in books", body: "These are sciences not written in books. Someone God blessed with some of them speaks of them only with others who share them, as reminders and in private. This is the hidden knowledge the Prophet meant: “Some knowledge is like a hidden treasure, known only to those who know God. When they speak of it, only those deceived about God deny it. So do not look down on a scholar God has given knowledge, for God did not look down on him when He gave it.”" },
      { title: "The heart's praised states", body: "The second part is the knowledge of practice, the knowledge of the heart's states. The praised states include patience, gratitude, fear, hope, contentment with God's decree, doing without and mindfulness of God. They include being satisfied with little, generosity, seeing God's favour in every state, doing good, thinking well of others, good character, good company, truthfulness and sincerity. Knowing their real nature and definitions, the causes by which they are gained, and their fruit and signs, is knowledge of the next life. So is knowing how to strengthen the weak and restore the lost." },
      { title: "The blamed states", body: "The blamed states include fear of poverty, resenting what God decrees, rancour, spite and envy. They include cheating, wanting to be above others, loving praise, and wanting a long life to enjoy. They include pride, showing off, anger, arrogance, enmity, hatred, greed, meanness, craving, extravagance, wild celebration and ingratitude. They include honouring the rich and scorning the poor, boasting, vanity, rivalry and showing off. They include refusing the truth, meddling, loving to talk, conceit, dressing up for people, flattery and self-admiration. They include being busy with others' faults instead of your own, and losing sadness and fear of God. They include rushing to defend yourself when slighted but not the truth, and public friends who are secret enemies. They include feeling safe from God taking back what He gave, relying on your good deeds, scheming, betrayal and deceit. They include long hopes, hardness and harshness, and joy in the world and grief at losing it. They include comfort with people and loneliness without them, coldness, rashness, haste, little shame and little mercy." },
      { title: "Seedbeds of sin", body: "These and their like are the seedbeds of indecency and the soil of forbidden acts. Their opposites, the praised traits, are the spring of obedience and nearness to God. Knowing their definitions, realities, causes, fruits and cures is the knowledge of the next life. In the ruling of the scholars of the next life, it is a personal duty. Whoever turns from it will be ruined by the power of the King of kings in the next life. In the same way, whoever neglects the outward acts is ruined by the sword of worldly rulers, by the ruling of the lawyers of this world." },
      { title: "Volumes on rare cases", body: "Ask a lawyer about any of these, even sincerity, trust in God, or how to guard against showing off, and he would hesitate. Yet it is his personal duty, and neglecting it ruins him in the next life. Ask him about mutual cursing, oaths of separation, racing or archery, and he would pour out volumes of fine details. Ages pass without anyone needing any of it. If it were ever needed, the town would have someone to handle it. Still he toils over it day and night, forgetting what matters for his own religion. If challenged, he says: “I am busy with it because it is religious knowledge and a communal duty.”" },
      { title: "Doctors missing, lawyers everywhere", body: "A sharp person knows that if his aim were to fulfil a communal duty, he would put his personal duty first, and many other communal duties too. How many towns have no doctor except protected non-Muslims (the dhimmis), whose testimony is not accepted on the legal questions that turn on doctors' reports! Yet no Muslim takes it up. They all rush to law, especially disputed questions and debate, while the town is packed with lawyers giving rulings. Why do the lawyers of religion allow themselves a communal duty that many already perform, and neglect one no one performs? Only because medicine does not lead to control of endowments and wills, or guardianship of orphans' money. It does not lead to posts as judges and officials, getting ahead of rivals, and power over enemies. The knowledge of religion has faded through the trickery of bad scholars." },
      { title: "The imam at the shepherd's feet", body: "The careful scholars of outward knowledge used to admit the merit of the scholars of the inner life. The imam al-Shafi'i would sit before Shayban the shepherd like a boy at school, asking him what to do in this or that case. Someone asked: “Does a man like you ask this nomad?” He said: “He has been given what we missed.” Ahmad ibn Hanbal and Yahya ibn Ma'in used to visit Ma'ruf al-Karkhi, who was not at their level in outward knowledge, and ask him questions. The Prophet was asked: “What should we do if something comes up that we find in neither the Book nor the Sunna?” He said: “Ask the righteous, and consult among them.”" },
      { title: "Hadith first, then Sufism", body: "Al-Junayd said his teacher al-Sari once asked him: “When you leave me, whom do you sit with?” He said: “Al-Muhasibi.” Al-Sari said: “Yes. Take his knowledge and his discipline, and leave his hair-splitting and his arguments against the theologians.” Junayd turned to go. He heard al-Sari say: “May God make you a scholar of hadith who is a Sufi, and not a Sufi who is a scholar of hadith.” He meant that someone who gains hadith and knowledge first and then takes up Sufism succeeds. Whoever takes up Sufism before knowledge puts himself in danger." },
    ],
    closer: [
      { title: "The mirror is the whole method", body: "Ghazali's image is simple. The truth is there to be seen; the heart is a mirror; the world's dirt has rusted it. Everything in the Ihya about practice is about polishing." },
      { title: "Why the doctors are missing", body: "The empty doctor's chair is Ghazali's proof of motive. If the lawyers were really doing a communal duty, they would fill the one nobody filled. They filled the one that led to office." },
    ],
    distinction: ["The two parts of the knowledge of the road", "Unveiling", "A light in the cleansed heart that shows God, His acts and the next life as clearly as sight. Not put in books.", "Practice", "Knowledge of the heart's praised and blamed states, and how to gain the first and cure the second. A personal duty."],
    misreading: "Ghazali is not telling people to skip outward knowledge and jump to the inner. He quotes al-Sari to say the opposite: knowledge first, then the path. The one who reverses the order is in danger.",
    reflection: "Read slowly through the list of blamed states. Mark the three you recognise in yourself.",
    audit: ["Could I define sincerity if asked?", "Which blamed state is the seedbed of my worst habit?", "Do I learn what gives me standing, or what is actually missing?", "Whom do I ask when the books run out?"],
    nodes: ["mukashafa", "muamala", "qalb"],
    model: pair("The heart's two lists", "The subject of the knowledge of practice.", [["Praised states", "Patience, gratitude, fear, hope, contentment, sincerity: the spring of obedience.", "support"], ["Blamed states", "Envy, pride, showing off, greed, long hopes: the seedbed of sin.", "warning"]]),
  }),
  makeChapter({
    id: 13, shortTitle: "Theology and philosophy", formalTitle: "Where theology and philosophy stand, and why the Companions were greater than lawyers and theologians",
    overview: "Ghazali places theology as a guard for ordinary people's belief, made necessary by heresy. Philosophy is not one science but four parts. Then he meets the objection that he has lowered the most famous scholars, and answers with the Companions.",
    thesis: "Theology is a communal duty only because heresy arose, just as hiring guards became needed when raiders appeared. The theologian is a guard, not a pilgrim. Merit with God comes from the knowledge of the next life, as the Companions' did, not from what makes a person famous.",
    moves: [
      { title: "What theology contains", body: "Why did Ghazali not list theology and philosophy among the sciences? Everything useful in theology's proofs is already in the Quran and the reports. What goes beyond them is either blamed argument, which is innovation, or quarrelling over the contradictions between sects, or long reports of opinions that are mostly nonsense. Some of it is about things unrelated to religion. None of it was known in the first generation, and going into it at all was then an innovation." },
      { title: "Why it became a duty", body: "But its ruling has now changed. Heresies arose that turned people from the Quran and the Sunna, and groups stitched together doubts and built arguments for them. So what was forbidden became allowed by necessity, and even a communal duty. That is, as much as is needed to answer a heretic who sets out to spread his heresy. It has a limit, which the next chapter gives." },
      { title: "Philosophy in four parts", body: "Philosophy is not a science of its own. It has four parts. The first is geometry and arithmetic. These are permitted. Only someone at risk of being led by them into blamed sciences is kept from them, since most who practise them have gone on to heresies. The weak are kept from them, not for what they are. It is as a child is kept from a riverbank for fear of falling in, or a new Muslim from mixing with unbelievers. Even so, the strong are not urged to mix with them either." },
      { title: "Logic, metaphysics, physics", body: "The second is logic, which studies how a proof works and its conditions, and how a definition works and its conditions. Both are part of theology. The third is metaphysics, about God's being and qualities. It too is part of theology. The philosophers did not have a different kind of knowledge here. They held their own views, some unbelief and some heresy, just as the Mu'tazila are not a separate science but a group of theologians with false views. The fourth is physics. Part of it goes against the law and the truth, so it is ignorance, not knowledge. Part studies the qualities of bodies and how they change, which is like medicine. But medicine is better, because it is needed, and their physics is not." },
      { title: "The guard is not a pilgrim", body: "So theology became a communal duty, to guard ordinary people's hearts from heretics' fancies. It arose with heresy, as hiring escorts on the pilgrim road arose when raiders began to attack. If the raiders stopped, guards would not be a condition of the road. If the heretic stopped his nonsense, nothing beyond what was known in the Companions' time would be needed. The theologian should know his limit. His place in religion is the guard's on the pilgrim road. If the guard does only guarding, he is not one of the pilgrims." },
      { title: "What the theologian has", body: "Suppose the theologian gives himself only to debate and defence, and does not walk the road to the next life or tend his heart. Then he is not a scholar of religion at all. His religion is only the belief he shares with ordinary people, an act of the outer heart and the tongue. What sets him apart is the craft of arguing and guarding. Knowing God, His qualities and His acts, as described under unveiling, does not come from theology. Theology can almost veil it and block it. The way there is striving, which God made the start of guidance: “Those who strive for Us, We will surely guide them on Our paths. God is with those who do good.”" },
      { title: "The objection", body: "Someone may say: you have reduced the theologian to guarding ordinary people's belief, like an escort guarding pilgrims' goods. You have reduced the lawyer to keeping the law by which the ruler stops people harming each other. Those are low levels compared with religious knowledge. Yet the famous scholars of the community are the lawyers and theologians, and they are the best of creation with God. How can you lower them so far?" },
      { title: "Know the truth, then its people", body: "Ghazali answers: whoever knows the truth by people wanders lost. Know the truth, and you will know its people, if you walk the road of truth. If you are content to follow what is famous, do not forget the Companions and their high place. Those you mentioned all agree the Companions came first, and that none can match them. They did not come first through theology or law, but through knowledge of the next life and walking its road. Abu Bakr did not surpass people by fasting or praying more, or by reporting, giving rulings or arguing. He surpassed them by something settled in his heart, as the Prophet said. So put your effort into seeking that secret. It is the precious jewel." },
      { title: "Thousands of Companions", body: "When the Prophet died, he left thousands of Companions, all knowers of God, whom he praised. Not one of them was good at theology. Only a dozen or so took on giving rulings. Ibn Umar was one of those. When asked for a ruling he would say: “Go to such-and-such a governor, who took charge of people's affairs and hung them on his neck.” He meant that rulings in cases and judgments go with governing. When Umar died, Ibn Mas'ud said: “Nine tenths of knowledge has died.” People said: “You say that, while the great Companions are among us?” He said: “I do not mean the knowledge of rulings and judgments. I mean knowledge of God.” Do you think he meant theology and debate? Umar closed the door of theology and debate. When Subaygh asked him about two verses that seemed to clash, Umar struck him with his whip, cut him off, and told people to cut him off too." },
      { title: "Fame and merit", body: "As for the famous scholars being lawyers and theologians: what gives merit with God is one thing, and what gives fame among people is another. Abu Bakr was famous for being caliph; his merit was the secret settled in his heart. Umar was famous for governing. His merit was knowledge of God, nine tenths of which died with him, and his aim of nearness to God in his rule, his justice and his kindness. That was inner and hidden. His other outward acts could have come from someone after status and fame. So fame lies in what can destroy, and merit in a secret no one sees." },
      { title: "Three kinds of nearness", body: "Lawyers and theologians are like caliphs, judges and scholars: they are divided. Some wanted God by their knowledge, rulings and defence of the Sunna, not show or fame. They have God's pleasure, and their merit is for acting on what they knew and wanting God. Every knowledge that is acted on is an earned act, but not every act is knowledge. A doctor can come near to God by his knowledge and be rewarded, as one acting for God. A ruler who stands between people for God is rewarded, not as a religious scholar, but for an office held for God. What brings nearness is of three kinds. There is knowledge alone, which is unveiling, and action alone, like a ruler's justice. Then there is both together: the knowledge of the road, whose owner is both a scholar and a worker. See whether you will be with God's scholars or His workers on the Day of Resurrection, or share in both. As the verse says: “Take what you see and leave what you heard of; in the rising sun is enough to spare you Saturn.”" },
    ],
    closer: [
      { title: "Know the truth first", body: "“Whoever knows the truth by people wanders lost.” This line answers every appeal to famous names in the book. Ghazali does not ask who is famous. He asks what brings a person near to God." },
      { title: "Guards were once not needed", body: "Theology's value depends on the heresy it answers, as a guard's depends on the raiders. The need is real, but it is a response, not the goal." },
    ],
    distinction: ["Two things a scholar can have", "Fame among people", "Won by what is outward and visible: office, rulings, debate. It can lie in what destroys.", "Merit with God", "Won by a secret in the heart and knowledge of God. Abu Bakr's and Umar's real greatness."],
    misreading: "Ghazali does not ban theology or call every theologian a fraud. He makes it a communal duty and wrote it himself. He limits it to guarding, and denies it is the road to knowing God.",
    reflection: "Ghazali says fame lies in what can destroy, and merit in a secret no one sees. What would you do differently if no one could ever see it?",
    audit: ["Do I know the truth first, or judge it by who says it?", "Am I a guard who has forgotten to be a pilgrim?", "What is settled in my heart?", "Will I be with God's scholars, His workers, or both?"],
    nodes: ["kalam", "falsafa", "mukashafa"],
    model: chain("Where theology stands", "Ghazali's pilgrim-road picture.", [["The pilgrim", "Walks the road to God: knowledge of the next life.", "support"], ["The raider", "The heretic who attacks ordinary people's belief.", "warning"], ["The guard", "The theologian: needed while raiders exist.", "balance"], ["The guard's limit", "Guarding is not the pilgrimage; debate can even veil knowing God.", "warning"]]),
  }),
  makeChapter({
    id: 14, shortTitle: "Al-Shafi'i", formalTitle: "The five imams of law and their five traits: al-Shafi'i as worshipper, ascetic, knower of the heart and seeker of God",
    overview: "To show his complaint is not against the great lawyers, Ghazali describes them. Each of the five imams was a worshipper, did without the world, knew the sciences of the next life, understood law, and wanted God by it. Later lawyers copied only the law. He starts with al-Shafi'i.",
    thesis: "The lawyers of Ghazali's time claimed to follow the imams in one of their five traits, the detail of law, because only that one also serves this world. Al-Shafi'i's night prayers, hunger, silence, generosity, fear of God and freedom from wanting to win show the other four.",
    moves: [
      { title: "Not an attack on the imams", body: "Ghazali says the early lawyers were wronged by those who claim their schools. They will be their fiercest opponents on the Day of Resurrection. The imams wanted only God by knowledge. They showed the signs of scholars of the next life. They were not given over to law alone but busy with knowing and watching the heart. What kept them from teaching and writing about it was what kept the Companions from writing about law, though they were lawyers." },
      { title: "Five imams, five traits", body: "The leaders of law with the most followers are five: al-Shafi'i, Malik, Ahmad ibn Hanbal, Abu Hanifa and Sufyan al-Thawri. Each was a worshipper, did without the world, knew the sciences of the next life, understood people's worldly good, and wanted God by his law. The lawyers of the age follow them in only one of these traits: effort and detail in the branches of law. The other four are only good for the next life. This one is good for both worlds; if meant for the next, it is less useful for this one. So they took it up and claimed to be like those imams. But you cannot compare angels with blacksmiths." },
      { title: "Worshipper: the night in thirds", body: "Al-Shafi'i divided the night in three: a third for knowledge, a third for worship, and a third for sleep. Al-Rabi' said al-Shafi'i finished the Quran sixty times in Ramadan, all in prayer. Al-Husayn al-Karabisi said: “I spent many nights with him. He prayed about a third of the night, and I never saw him recite more than fifty verses, or a hundred at most. At every verse of mercy he asked God for it for himself and all believers. At every verse of punishment he sought refuge and asked safety for himself and the believers.” Hope and fear were joined in him. Ghazali says his stopping at fifty verses shows how deeply he reflected on the Quran." },
      { title: "Never full", body: "Al-Shafi'i said: “I have not eaten my fill for sixteen years. A full stomach makes the body heavy, hardens the heart, dulls the mind, brings sleep, and weakens a person for worship.” Ghazali points to his wisdom in naming the harms of fullness, and his seriousness in dropping it for worship. The head of devotion is eating little. Al-Shafi'i also said: “I have never sworn by God, truly or falsely.” That shows his reverence for God and his knowledge of God's majesty." },
      { title: "Guarding the tongue", body: "He was asked a question and kept quiet. Someone said: “Won't you answer, God have mercy on you?” He said: “Not until I know whether the merit is in my silence or my answer.” Ghazali says: look at how he watched his tongue, the organ that most overpowers lawyers and is hardest to control. He neither spoke nor kept silent except to gain merit and reward." },
      { title: "The listener shares the sin", body: "Ahmad ibn Yahya ibn al-Wazir said: “One day al-Shafi'i left the lamp-sellers' market and we followed him. A man was insulting a scholar. Al-Shafi'i turned to us and said: ‘Keep your ears clean of hearing filth, as you keep your tongues clean of saying it. The listener shares with the speaker. A fool looks at the foulest thing in his jar and is eager to empty it into yours. Turn the fool's word back, and you are happy while he is wretched.’” Al-Shafi'i also told of a wise man's letter to another: “You have been given knowledge. Do not stain it with the darkness of sins. Otherwise you will be left in darkness on the day the people of knowledge walk by its light.”" },
      { title: "Doing without: ten thousand given away", body: "On doing without the world, al-Shafi'i said: “Whoever claims to have joined love of the world and love of its Creator in his heart has lied.” Al-Humaydi said al-Shafi'i went to Yemen with a governor and came back to Mecca with ten thousand dirhams. A tent was pitched for him outside Mecca, and people came to him. He did not leave that spot until he had given it all away. Once he came out of the bathhouse and gave the attendant a large sum. Once his whip fell and someone picked it up for him; he gave him fifty dinars. His generosity is too famous to tell. The head of doing without is generosity. Whoever loves a thing holds on to it; only someone to whom the world has become small parts with money." },
      { title: "Fainting at a verse", body: "Once Sufyan ibn Uyayna told a report about softening hearts, and al-Shafi'i fainted. People said he had died. Sufyan said: “If he has died, the best man of his time has died.” Umar ibn Nubata said: “I went out with al-Shafi'i and al-Harith ibn Labid to al-Safa. Al-Harith had a fine voice. He recited: ‘This is a day they will not speak, and they will not be allowed to make excuses.’ Al-Shafi'i's colour changed, his skin shivered, he shook violently and fell unconscious. When he came round he said: ‘I seek refuge in You from the place of liars and the turning away of the heedless. O God, the hearts of the knowers are humbled before You, and the necks of those who long for You are bowed. My God, give me Your generosity, cover me with Your veil, and pardon my failings by the nobility of Your face.’”" },
      { title: "Advice on the riverbank", body: "Al-Balawi told the same story. He said that later in Baghdad he was doing ablution on the riverbank. A man passed and said: “Young man, do your ablution well, and God will do well by you in this world and the next.” He followed him and asked him to teach him something. The man said: “Whoever is true with God is saved. Whoever is careful of his religion is safe from ruin. Whoever does without the world will be delighted tomorrow by God's reward. Shall I add more? Whoever has three traits has completed faith: he commands good and does it, forbids wrong and stops himself, and keeps God's limits. Shall I add more? Do without the world, long for the next life, and be true with God in all your affairs, and you will be saved with those who are saved.” The man was al-Shafi'i. Ghazali says this fear and this doing without come only from knowing God: “Only those of His servants who know truly fear God.” Al-Shafi'i did not get them from the chapters on advance sales and hire." },
      { title: "Knower of the heart", body: "His knowledge of the heart shows in his sayings. Asked about showing off, he said at once: “Showing off is a temptation that desire tied before the eyes of scholars' hearts. They looked at it with the bad choice of their selves, and it wiped out their deeds.” He said: “Do you fear self-admiration in your work? Then think whose pleasure you seek, what reward you want, what punishment you fear, what health you are thankful for, and what trial you remember. If you think of any one of these, your deed will look small.” He said: “Whoever does not guard himself, his knowledge will not help him,” and “Whoever obeys God with knowledge, his inner self benefits.” And: “Everyone has someone who loves him and someone who hates him, so be with the people who obey God.”" },
      { title: "Trial before firm footing", body: "A pious man, Abd al-Qahir ibn Abd al-Aziz, used to ask al-Shafi'i about caution, and al-Shafi'i welcomed him for his piety. He asked: “Which is better: patience, trial, or being made firm?” Al-Shafi'i said: “Being made firm is the level of the prophets, and it comes only after trial. When a person is tried, he is patient; when he is patient, he is made firm.” God tried Abraham, Moses, Job and Solomon and then made them firm. “So We made Joseph firm in the land.” After Job's great trial, “We gave him his family and as many again with them.” Asked when a man becomes a scholar, he said: “When he has mastered religious knowledge, and then looked into other sciences to see what he missed.” Galen, asked why he gave many mixed medicines for one illness, said the aim is one, and the others calm its sharpness, because a single one alone kills." },
      { title: "Wanting God by his law", body: "His wanting God by law and debate shows in his words: “I wish people would benefit from this knowledge and none of it be credited to me.” He said: “I never debated anyone and wished him to be wrong.” And: “I never spoke to anyone without wishing him to be guided, helped and protected by God. I never cared whether God showed the truth on my tongue or his.” And: “Whenever I brought someone the truth and he accepted it, I respected him and loved him. Whoever resisted the truth fell in my eyes.” Abu Thawr said: “Neither I nor anyone else has seen the like of al-Shafi'i.”" },
      { title: "Forty years of prayers", body: "Ahmad ibn Hanbal said: “I have not prayed a prayer for forty years without praying for al-Shafi'i.” Ghazali asks us to compare this fairness and this regard with the rivalry and hatred between scholars of his own time. Ahmad's son asked him what kind of man al-Shafi'i was, to be prayed for so much. Ahmad said: “My son, al-Shafi'i was like the sun for the world and like health for people. See if those two have any substitute.” Ahmad said: “No one has touched an inkwell without owing a debt to al-Shafi'i.” Yahya ibn Sa'id al-Qattan also prayed for him in every prayer for forty years. Ghazali says he took most of this from Nasr ibn Ibrahim al-Maqdisi's book on al-Shafi'i's virtues." },
    ],
    closer: [
      { title: "Angels and blacksmiths", body: "The later lawyers kept the one trait that pays in this world. Ghazali's image for comparing them with the imams is blunt: you cannot measure angels against blacksmiths." },
      { title: "The debater who wanted to lose", body: "Al-Shafi'i's wish that God show the truth on either tongue is the test the fourth chapter will use against debaters. The imam of debate himself passed it." },
    ],
    distinction: ["Two ways of following an imam", "Following his traits", "Worship, doing without, knowing the heart, law, and wanting God by it: all five.", "Borrowing his name", "Keeping only the detail of law, which serves this world, and claiming to be like him."],
    misreading: "These stories are not decoration. Ghazali tells them as evidence. The imams of law were first of all people of worship and fear, so the lawyers who claim them but lack those traits are not their followers.",
    reflection: "Al-Shafi'i wished people would benefit from his knowledge without it being credited to him. Could you teach something and let someone else get the credit?",
    audit: ["Do I follow my teachers in their worship, or only their subject?", "Do I guard my ears as I guard my tongue?", "Do I want the truth to win, even through my opponent?", "When did I last feel fear at a verse?"],
    nodes: ["aimma", "zuhd", "ikhlas"],
    model: chain("The five traits of the imams", "Ghazali's list, shown in al-Shafi'i.", [["Worshipper", "The night in thirds; fifty verses, weighed.", "support"], ["Doing without", "Ten thousand dirhams given away in one sitting.", "support"], ["Knower of the next life", "Fainting at a verse; defining showing off at once.", "support"], ["Lawyer, for God", "Wishing the truth on his opponent's tongue.", "support"]]),
  }),
  makeChapter({
    id: 15, shortTitle: "Malik, Abu Hanifa, Ahmad and Sufyan", formalTitle: "The five imams continued: Malik, Abu Hanifa, and a word on Ahmad and Sufyan",
    overview: "Ghazali shows the same traits in Malik and Abu Hanifa. Malik honoured the Prophet's words, said “I don't know” and refused a caliph's house. Abu Hanifa prayed all night, took a beating rather than hold office, and would not keep a ruler's gift.",
    thesis: "None of these men got their fear of God and their freedom from the world out of the chapters on advance sales and hire. Something higher produced it. The question for anyone claiming to follow them is whether the claim is true.",
    moves: [
      { title: "Malik: what binds you today", body: "Malik had all five traits too. Asked about seeking knowledge, he said: “It is good and fine. But look at what binds you from morning to evening, and hold to that.” He honoured religious knowledge greatly. When he meant to teach reports, he would do ablution, sit at the head of his seat, comb his beard, wear perfume, and settle with dignity before speaking. Asked why, he said: “I love to honour the words of the messenger of God.” He said: “Knowledge is a light God puts where He wills. It is not a lot of reporting.”" },
      { title: "Thirty-two times “I don't know”", body: "His wanting God by knowledge shows in his saying: “Arguing about religion is nothing.” Al-Shafi'i said: “I saw Malik asked forty-eight questions. To thirty-two of them he said: I don't know.” Someone who wants anything but God by his knowledge cannot bring himself to admit he does not know. So al-Shafi'i said: “When scholars are mentioned, Malik is the bright star. No one has done me more good than Malik.”" },
      { title: "Flogged for a report", body: "The caliph Abu Ja'far al-Mansur forbade Malik to teach the report about divorce under force. Then he sent someone to ask him about it secretly. Malik said before a crowd: “Divorce under force does not count.” Al-Mansur had him flogged, and he did not stop teaching the report. Malik said: “No man is truthful in his speech and never lies without keeping his mind, and no harm or senility strikes him in old age.”" },
      { title: "No house of his own", body: "On doing without, the caliph al-Mahdi asked Malik: “Do you have a house?” He said no, and quoted Rabi'a: “A man's lineage is his house.” Harun al-Rashid asked him the same, gave him three thousand dinars and said: “Buy a house with it.” He took it and did not spend it. When al-Rashid was leaving, he said: “You should come with us. I mean to make people follow the Muwatta, as Uthman made them follow the Quran.”" },
      { title: "Medina is better for them", body: "Malik said: “There is no way to make people follow the Muwatta. The Prophet's Companions spread through the cities after him and taught, so every city has knowledge. The Prophet said: The differences of my community are a mercy. As for coming with you, there is no way. The Prophet said: Medina is better for them, if only they knew. And: Medina drives out its dirt as the bellows drive out iron's dross. Here are your dinars as they were. Take them or leave them.” He meant: you ask me to leave Medina for what you gave me, and I will not prefer the world to the Prophet's city. When great wealth came to him from everywhere because his knowledge spread, he gave it away to good causes. Doing without is not having no money, but a heart empty of it. Solomon, in all his kingdom, was one who did without." },
      { title: "Horses he would not ride", body: "Al-Shafi'i said: “I saw at Malik's door a herd of horses from Khurasan, or it was said Egypt, finer than any I have seen. I said: How fine they are. He said: They are a gift from me to you. I said: Keep one to ride. He said: I would be ashamed before God to tread soil where God's Prophet lies under a horse's hoof.” Look at his generosity in giving them all at once, and his reverence for the soil of Medina." },
      { title: "Knowledge is come to", body: "Malik said: “I went in to Harun al-Rashid. He said: You should come to us so that our boys can hear the Muwatta from you. I said: May God honour our lord the prince. This knowledge came out from you. If you honour it, it will be honoured. If you humble it, it will be humbled. Knowledge is come to; it does not come.” He said: “You are right. Go out to the mosque and hear it with the people.”" },
      { title: "Abu Hanifa: ashamed to be praised", body: "Abu Hanifa too was a worshipper, did without, feared God, and wanted God by his knowledge. Ibn al-Mubarak said he had manliness and prayed a great deal. Hammad ibn Abi Sulayman reported he prayed the whole night. It is said he used to pray half the night. Once, as he walked, someone pointed to him and said: “That is the man who prays all night.” After that he always prayed all night. He said: “I am ashamed before God to be described with worship I do not do.”" },
      { title: "Flogged rather than hold office", body: "Al-Rabi' ibn Asim said: “Yazid ibn Umar ibn Hubayra sent me to bring Abu Hanifa. He wanted him to be in charge of the treasury. He refused, and Yazid had him flogged twenty lashes.” See how he fled office and bore the pain. Al-Hakam ibn Hisham said that in Syria he heard Abu Hanifa was one of the most trustworthy people alive. The ruler told him to take the keys of the treasury or be flogged. He chose their punishment over God's. When Abu Hanifa was mentioned, Ibn al-Mubarak said: “Are you talking about a man who was offered the whole world and ran from it?”" },
      { title: "The bag in the corner", body: "It is told that the caliph al-Mansur ordered ten thousand dirhams for Abu Hanifa, and he was not pleased. On the day the money was due, he prayed the dawn prayer, covered himself with his cloak and did not speak. The messenger of al-Hasan ibn Qahtaba brought the money. Abu Hanifa did not speak to him, only saying: “Put it in this bag in the corner of the room.” Later he made his will and told his son: “When I die, bury me. Then take this bag to al-Hasan ibn Qahtaba and say: take your deposit that you left with Abu Hanifa.” His son did. Al-Hasan said: “God have mercy on your father. He was miserly with his religion.”" },
      { title: "Unfit to judge", body: "He was called to be a judge and said: “I am not fit for it.” Asked why, he said: “If I am telling the truth, I am not fit. If I am lying, a liar is not fit to be a judge.” His knowledge of the road to the next life and of God shows in his great fear of God and his doing without. Ibn Jurayj said: “I have heard that your man of Kufa, al-Nu'man ibn Thabit, fears God greatly.” Sharik al-Nakha'i said: “Abu Hanifa was long silent, always thinking, and spoke little with people.” Ghazali says this is one of the clearest signs of inner knowledge. Whoever is given silence and doing without has been given all knowledge." },
      { title: "Ahmad and Sufyan", body: "Ahmad ibn Hanbal and Sufyan al-Thawri have fewer followers than the three, and Sufyan fewer than Ahmad. But they are even better known for caution and doing without. The whole Ihya is full of stories of their deeds and words, so there is no need for detail here. Now look at these imams, Ghazali says. Think of these states and words, this turning from the world and giving oneself to God. Do they come from knowing the branches of law, advance sales, hire, oaths of separation and mutual cursing? Or from another knowledge, higher and nobler? And look at those who claim to follow them. Is their claim true?" },
    ],
    closer: [
      { title: "The question at the end", body: "Ghazali ends the chapter with a question, not a verdict. The imams' lives are the evidence. The reader must decide whether the lawyers who claim them are telling the truth." },
      { title: "Miserly with his religion", body: "Al-Hasan's words about Abu Hanifa turn a fault into praise. He gave nothing away of his religion, not even to be polite to a caliph." },
    ],
    distinction: ["Two kinds of refusal", "Refusing office", "Abu Hanifa took twenty lashes rather than run the treasury or be a judge.", "Refusing to move knowledge", "Malik would not bring the Muwatta to the palace: knowledge is come to, it does not come."],
    misreading: "The refusals are not bad manners towards rulers. Malik answers al-Rashid with courtesy and reasons. What he refuses is to make knowledge serve the palace, or to prefer money to the Prophet's city.",
    reflection: "Malik said “I don't know” to thirty-two of forty-eight questions. When did you last say it?",
    audit: ["Can I say “I don't know” without shame?", "Would I take a beating rather than an office I was unfit for?", "Do I honour knowledge by making people come to it?", "Is my silence the silence of thought?"],
    nodes: ["aimma", "zuhd"],
    model: pair("Two imams, one pattern", "What each refused, and why.", [["Malik", "Refused the caliph's house, the move to Baghdad and to ride in Medina: the Prophet's city came first.", "support"], ["Abu Hanifa", "Refused the treasury, the judgeship and the caliph's money: his religion came first.", "support"]]),
  }),
  makeChapter({
    id: 16, shortTitle: "Why some knowledge is blamed", formalTitle: "Why blamed knowledge is blamed: magic, astrology, and the ant on the page",
    overview: "If knowledge is knowing a thing as it is, and is one of God's qualities, how can any knowledge be blamed? Ghazali answers that knowledge is never blamed in itself. It is blamed in people for one of three reasons, and he takes magic and astrology as his examples.",
    thesis: "Knowledge is blamed when it leads to harm, when it usually harms the one who has it, or when it gives its seeker no real benefit. Magic is the first kind. Astrology is the second: it turns weak hearts from God to the stars, it is guesswork, and it wastes a life.",
    moves: [
      { title: "Knowledge is not blamed in itself", body: "You may ask: knowledge is knowing a thing as it is, and it is one of God's qualities. How can something be knowledge and still be blamed? Ghazali says knowledge is never blamed for what it is. It is blamed in people for one of three reasons." },
      { title: "First: it leads to harm", body: "The first is that it leads to harm, to its owner or to others. Magic and talismans are blamed this way. Magic is real; the Quran bears witness to it, and it is a means of separating husband and wife. The Prophet himself had magic worked on him and fell ill from it. Then Gabriel told him and he took it out from under a stone at the bottom of a well." },
      { title: "How magic works", body: "Magic comes from knowing the special properties of substances and calculations about the rising of stars. A figure in the shape of the victim is made from those substances. A particular time of a star's rising is watched for. Words of unbelief and filth against the law are spoken with it, and through them the help of devils is sought. From all of this together, by the way God has made things usually happen, strange states appear in the victim. Knowing these causes, just as knowing, is not blamed. But it is good for nothing except harming people, and a means to evil is evil." },
      { title: "A true answer can be wrong", body: "Suppose a friend of God is hiding in a safe place from a tyrant who wants to kill him, and the tyrant asks where he is. You may not tell him. You must even lie. Telling the place would be guidance and giving knowledge of a thing as it is. It is still blamed, because it leads to harm." },
      { title: "Second: astrology", body: "The second reason is that it usually harms its owner, like astrology. Astrology is not blamed in itself. It has two parts. One is calculation. The Quran says the courses of the sun and moon are calculated: “The sun and moon run by calculation.” It also says: “We have set stages for the moon, until it returns like an old palm stalk.” The other is predictions: reading events from their causes. This is like a doctor reading a coming illness from the pulse. It is knowing the patterns God set in His creation. But the law has blamed it." },
      { title: "What the Prophet said", body: "The Prophet said: “When destiny is mentioned, hold back. When the stars are mentioned, hold back. When my Companions are mentioned, hold back.” He said: “I fear three things for my community after me: the injustice of rulers, belief in the stars, and denying destiny.” Umar said: “Learn from the stars what guides you on land and sea, then stop.” It was forbidden for three reasons." },
      { title: "The ant on the page", body: "First, it harms most people. Told that these events follow the stars' movements, they come to think the stars cause them, and are gods who run things, since they are noble heavenly bodies. The heart turns to them and hopes for good and fears evil from them, and God's remembrance is wiped from it. The weak look no further than the go-betweens. The firmly grounded scholar sees that the sun, moon and stars are made to serve by God's command. The weak person is like an ant with reason, on a sheet of paper, watching black writing appear. It thinks the pen did it. It does not climb to the fingers, then the hand, then the will that moves the hand. It does not reach the writer who is able and wills, and then the Creator of the hand, the power and the will. Most people's sight stops at the nearest, lowest causes." },
      { title: "Guesswork", body: "Second, astrological predictions are pure guesswork. For individual people they give neither certainty nor even likelihood. Judging by them is judging by ignorance, so it is blamed as ignorance, not as knowledge. It is said this knowledge was a miracle of the prophet Idris, and it has since been lost. When an astrologer happens to be right, it is chance. He may see some causes, but the effect follows only after many conditions no human can see. It is like guessing it will rain because clouds are gathering over the mountains. Then the sun heats the day and the clouds go. Or a sailor guessing his ship will be safe from the winds he is used to, when the winds have hidden causes." },
      { title: "A wasted life", body: "Third, it has no use. At best it is meddling in extras that do no good, and wasting life, a person's most precious possession, which is the worst loss. The Prophet passed a man with a crowd around him. He asked who he was. They said: “A very learned man.” In what? “In poetry and the Arabs' family trees.” He said: “Knowledge that does not help, and ignorance that does not harm.” He said: “Knowledge is only a clear verse, an established Sunna, or a just rule of inheritance.” What is decreed will happen, and guarding against it is impossible. Medicine is different: it is needed, and most of its evidence can be checked. Dream interpretation is different too. It is guesswork, but it is one of forty-six parts of prophecy, and it holds no danger." },
    ],
    closer: [
      { title: "Why the ant matters", body: "The ant is not a joke about stupid people. It is the danger of astrology for anyone: the eye stops at the nearest cause and never climbs to God." },
      { title: "True, and still blamed", body: "The hidden friend of God is the clearest case. Telling the tyrant would be perfectly true knowledge. It would still be forbidden. Knowledge is judged by where it leads." },
    ],
    distinction: ["Two parts of astrology", "Calculation", "The courses of sun and moon, which the Quran itself says are calculated. Useful for finding your way.", "Predictions", "Reading events from the stars. It turns weak hearts from God, is guesswork, and wastes life."],
    misreading: "Ghazali does not ban astronomy. Umar told people to learn from the stars what guides them on land and sea. What is blamed is reading people's fates in them.",
    reflection: "Where does your eye stop when something good or bad happens to you: at the pen, the hand, or the Writer?",
    audit: ["Do I seek knowledge that can only harm?", "Do I credit causes with what God does?", "How much of my life goes on knowledge that helps no one?", "Would I tell a true fact that leads to harm?"],
    nodes: ["madhmum", "tawhid"],
    model: chain("The ant's climb", "From the nearest cause to the Creator.", [["The pen", "Where the ant's eye stops: the writing appears.", "warning"], ["The fingers and hand", "One step further back.", "balance"], ["The will and the writer", "The one who is able and wills.", "balance"], ["The Creator", "Of the hand, the power and the will. Where sight should end.", "support"]]),
  }),
  makeChapter({
    id: 17, shortTitle: "Knowledge that harms its seeker", formalTitle: "The third cause: knowledge with no benefit for the one who digs into it, and why reason must follow the prophets",
    overview: "Some knowledge is blamed because it gives the person who digs into it no benefit, like fine points before basics, or divine secrets. Ghazali tells of a doctor who cured a woman by frightening her, and compares the prophets to doctors whose cures reason cannot guess.",
    thesis: "Knowledge can harm some people as rich food harms a baby, and some people are better off not knowing. The prophets are doctors of hearts. Reason's job is to lead you to the Prophet's truthfulness and understand his hints; after that it should step aside and follow.",
    moves: [
      { title: "Third: no benefit to the seeker", body: "The third reason is digging into a science that gives the digger no benefit. That is blamed for him. Examples are learning the fine points of sciences before the plain ones, the hidden before the clear, and searching into divine secrets. Philosophers and theologians reach for these and cannot manage them. Only prophets and friends of God can manage them, or even find the way to some of them. So people must be held back from searching into them and sent back to what the law says. That is enough for the one given success." },
      { title: "Like sweets to a baby", body: "Many people have dug into sciences and been harmed. Had they not, their religion would be in better shape. Do not deny that knowledge can harm some people, as bird meat and fine sweets harm a nursing baby. Some people even benefit from not knowing certain things." },
      { title: "The frightened wife", body: "It is told that a man complained to a doctor that his wife was barren. The doctor felt her pulse and said: “You don't need a medicine for childbirth. You will die within forty days. The pulse shows it.” She was terrified. Her life turned bitter. She gave away her money, made her will, and stopped eating and drinking until the time was up. She did not die. Her husband went to the doctor and said: “She didn't die.” The doctor said: “I knew. Now go to her; she will have a child.” How? “I saw she was fat, and fat had closed the mouth of her womb. I knew nothing would thin her except fear of death. So I frightened her until she grew thin, and the obstacle to childbirth was gone.”" },
      { title: "Knowledge that does not help", body: "This story shows how dangerous some knowledge can be. It explains the Prophet's words: “We seek refuge in God from knowledge that does not help.” Learn from it. Do not go searching into sciences the law has blamed and warned against. Keep to following the Companions and the Sunna. Safety is in following. Danger is in searching things out on your own. Do not argue much from your own opinion and proofs, saying: “I only want to know things as they are. What harm is there in thinking?” The harm to you is greater. Many things you look into harm you so badly they almost ruin you in the next life, unless God rescues you with His mercy." },
      { title: "The finger and the other shoulder", body: "A skilled doctor knows secrets of treatment that seem absurd to those who do not. In the same way, the prophets are doctors of hearts, and know the causes of life in the next world. Do not judge their ways by your reason, or you will be ruined. A person may have a problem in a finger, and his reason says to rub ointment on it. Then the skilled doctor tells him the cure is to rub the palm on the other side of the body. He finds that absurd, because he does not know how the nerves branch, where they start, and how they wind around the body." },
      { title: "The magnet", body: "It is the same on the road to the next life. In the fine points of the law's customs and manners, and in the beliefs people are commanded to hold, there are secrets beyond the reach of reason. There are wonders in the properties of stones that craftsmen do not know, so that no one can say why a magnet pulls iron. Beliefs and acts clean, purify and set right hearts, so they rise towards God and meet the breezes of His favour. The wonders in them are greater than those in medicines." },
      { title: "No one comes back to tell us", body: "Reason falls short of grasping the benefit of medicines, though experience can reach them. It falls shorter still of what helps in the next life, where experience cannot reach. Experience could reach it only if some of the dead came back to tell us. They would say which deeds were accepted and brought them near to God, which drove them away, and which beliefs were right. That will not happen. So it is enough that reason leads you to the Prophet's truthfulness and helps you understand his hints. Then take reason off the job and keep to following. Only that keeps you safe." },
      { title: "Some knowledge is ignorance", body: "That is why the Prophet said: “Some knowledge is ignorance, and some speech is helplessness.” Knowledge is not ignorance, but it can do the harm ignorance does. He said: “A little success from God is better than a lot of knowledge.” Jesus said: “How many trees there are, and not all bear fruit, and not all fruit is good. How many sciences there are, and not all are useful.”" },
    ],
    closer: [
      { title: "Reason's real job", body: "Ghazali gives reason an honoured job and then a limit. It proves the Prophet is truthful and understands what he meant. Where it cannot follow, because no one returns from death to report, it follows the one who knows." },
      { title: "A cure by fear", body: "The doctor lied, and saved a marriage. Ghazali does not tell the story to praise the lie. He tells it to show that knowing something can hurt, and not knowing can heal." },
    ],
    distinction: ["Two things reason does", "Leads you to the Prophet", "Shows that he is truthful and helps you grasp his hints.", "Then steps aside", "In what lies beyond experience, it follows, as the patient follows a doctor whose cure he cannot explain."],
    misreading: "Ghazali does not despise reason. The last chapter of this book praises it above everything. Here he limits it: it cannot test the next life by experience, so it must learn from those who were told.",
    reflection: "Think of a question you keep turning over that no one alive could settle. Is digging into it helping your religion?",
    audit: ["Do I study fine points before I have the basics?", "Do I judge the Sunna by what seems sensible to me?", "Is there knowledge I would be better off without?", "Do I ask for success from God, or only for more knowledge?"],
    nodes: ["madhmum", "aql", "ittiba"],
    model: pair("Two kinds of doctor", "Ghazali's comparison.", [["The body's doctor", "Rubs the opposite shoulder to cure the finger; his reasons are known by experience.", "balance"], ["The heart's doctor", "The prophet, whose cures for the next life no experience can test.", "support"]]),
  }),
  makeChapter({
    id: 18, shortTitle: "Two words narrowed", formalTitle: "The changed names of the sciences: understanding and knowledge",
    overview: "Blamed sciences get mixed up with religious ones because praised names have been bent to new meanings. Ghazali lists five: understanding, knowledge, God's oneness, reminding and wisdom. He starts with understanding (fiqh) and knowledge ('ilm), both narrowed.",
    thesis: "Understanding once meant the knowledge of the road to the next life: the self's hidden faults, the world's smallness, and fear of God. Knowledge once meant knowing God. Both were narrowed, to rare legal cases and to winning debates, while keeping the praise that belonged to the wider meaning.",
    moves: [
      { title: "Where the confusion starts", body: "The confusion between blamed sciences and religious ones starts with bending and swapping praised names. People with bad aims moved them to meanings the early Muslims never meant. There are five words: understanding, knowledge, God's oneness, reminding and wisdom. These are praised names, and those who hold them hold honoured positions in religion. Now they have been moved to blamed meanings. Because the names are still used of such people, hearts shrink from blaming them." },
      { title: "Understanding, narrowed", body: "The first word is understanding, fiqh. It was not moved but narrowed. They narrowed it to knowing strange legal cases, the fine points of their reasons, talking at length about them and memorising the views on them. Whoever digs deepest and is busiest with them is called the one with most understanding. In the first age, understanding meant the knowledge of the road to the next life. It meant knowing the fine harms of the self and what spoils deeds. It meant seeing clearly how small the world is, longing for the Garden's bliss, and fear taking hold of the heart." },
      { title: "The verse about warning", body: "God says: “to gain understanding of the religion, and to warn their people when they return to them.” The understanding that brings warning and fear is this kind. It is not the branches of divorce, freeing slaves, mutual cursing, advance sales and hire. Those bring no warning or fear. Giving oneself to them all the time hardens the heart and takes fear out of it, as we see in those who do." },
      { title: "Hearts that do not understand", body: "God says: “They have hearts they do not understand with.” He meant the meanings of faith, not legal rulings. In the language, understanding and grasping mean the same. God says of the hypocrites: “You strike more fear in their hearts than God does. That is because they are a people who do not understand.” He put their little fear of God and great fear of people down to lack of understanding. Was that because they had not memorised legal cases, or because they lacked the knowledge Ghazali has described?" },
      { title: "The one with full understanding", body: "The Prophet said of a group who came to him: “Scholars, people of understanding.” Sa'd ibn Ibrahim al-Zuhri was asked who in Medina had most understanding. He said: “The one most mindful of God.” He pointed to understanding's fruit, and mindfulness is the fruit of inner knowledge, not of rulings and verdicts. The Prophet said: “Shall I tell you who has full understanding? He does not make people despair of God's mercy, nor feel safe from God's plan. He does not make them lose hope of God's comfort, and he does not leave the Quran for something else.”" },
      { title: "Gatherings of remembrance", body: "Anas reported the Prophet saying: “Sitting with people remembering God from dawn to sunrise is dearer to me than freeing four slaves.” Then Anas turned to Yazid al-Raqashi and Ziyad al-Numayri. He said: “Gatherings of remembrance were not like yours, where one of you tells his sermon to his friends and reels off reports. We used to sit and speak of faith, reflect on the Quran, gain understanding in religion, and count God's blessings on us.” So reflecting on the Quran and counting blessings were called gaining understanding." },
      { title: "Al-Hasan's answer", body: "The Prophet said: “A person does not have full understanding until he detests people for God's sake, and sees many sides in the Quran.” It is also reported from Abu al-Darda, adding: “Then he turns to himself and detests it more.” Farqad al-Sabakhi asked al-Hasan something, and he answered. Farqad said: “The lawyers disagree with you.” Al-Hasan said: “May your mother lose you, little Farqad! Have you ever seen a lawyer with your own eyes? The man of understanding does without the world, longs for the next, and sees his religion clearly. He keeps worshipping his Lord and is careful. He keeps away from Muslims' honour and their money, and gives sincere advice to their community.” He did not once say: one who has memorised legal cases." },
      { title: "Not excluding law", body: "Ghazali does not say the word never covered rulings on outward matters. It did, but as part of a whole, or as something that followed along. It was used far more for the knowledge of the next life. This narrowing caused a confusion that sent people off to give themselves to law and turn from the next life and the rulings of the heart. Nature helped: inner knowledge is subtle and hard to act on, and it cannot be used to get office, judgeships, status and money. So Satan found room to make law look fine to hearts, by narrowing the name of understanding, a name the law praises." },
      { title: "Knowledge, narrowed", body: "The second word is knowledge, 'ilm. It was used of knowing God, His signs and His acts in His creatures. When Umar died, Ibn Mas'ud said: “Nine tenths of the knowledge has died.” He used the definite article, and then explained: knowledge of God. They narrowed this word too, until it mostly means those who debate opponents on legal and other questions. Such a man is called “the real scholar” and “a stallion of knowledge”. Whoever does not do this is counted weak, not one of the people of knowledge." },
      { title: "The praise was for the other", body: "This too is narrowing. Yet most of the praise of knowledge and scholars in the texts is for those who know God, His rulings, His acts and His qualities. Now the word is used for someone who knows nothing of the religious sciences except the forms of debate on disputed questions. He is counted a great scholar while ignorant of commentary, reports, his own school's law and more. This has ruined many students." },
    ],
    closer: [
      { title: "Narrowing, not stealing", body: "Ghazali's charge is subtle. Nothing false is said. A lawyer does have some understanding. But the praise that belonged to the whole is now spent on a part." },
      { title: "Al-Hasan's question", body: "“Have you ever seen a lawyer with your own eyes?” Al-Hasan's list of what a real one is like never mentions legal cases. That is Ghazali's evidence of what the word once meant." },
    ],
    distinction: ["Two meanings of understanding", "The first age's", "Knowledge of the road to the next life: the self's harms, the world's smallness, and fear of God.", "The narrowed one", "Knowing rare legal cases and their fine reasons: praised by the old name, but it can harden the heart."],
    misreading: "Ghazali is not saying law is not understanding at all. He says it was once a part of a wider meaning, and has been made the whole, taking the whole's honour with it.",
    reflection: "Al-Hasan's list: does without the world, sees his religion clearly, keeps worshipping, is careful, leaves people's honour and money alone, gives sincere advice. How many of these would someone see in you?",
    audit: ["What do I mean when I call someone learned?", "Does my learning bring me fear of God?", "Do I count God's blessings as part of understanding?", "Am I impressed by debaters who know little else?"],
    nodes: ["alfaz", "fiqh", "ilm"],
    model: pair("Understanding, then and now", "The first word Ghazali follows.", [["Then", "The self's hidden faults, the world's smallness, longing for the Garden, fear of God.", "support"], ["Now", "Strange legal cases, their reasons, and memorised views.", "warning"]]),
  }),
  makeChapter({
    id: 19, shortTitle: "God's oneness, emptied", formalTitle: "The changed names: God's oneness, its two shells and its kernel",
    overview: "The third word, tawhid, God's oneness, now names the craft of theology and debate. Ghazali says it once meant seeing everything as coming from God. He describes oneness as a kernel with two shells, and shows how the morning prayer can open with a lie.",
    thesis: "Oneness has three layers. Saying there is no god but God is the outer shell; even a hypocrite can say it. Believing it is the second shell, the oneness of ordinary people, which theologians guard. The kernel is seeing all things as from God, and worshipping Him alone, with no desire as a second god.",
    moves: [
      { title: "Oneness as a craft", body: "The third word is God's oneness. It is now used for the craft of theology. That means knowing how to argue and contradict opponents, and speaking grandly with many questions, raised doubts and forced conclusions. Some groups even called themselves the people of justice and oneness, and theologians were called scholars of oneness. Yet none of what is special to this craft was known in the first age. The early Muslims strongly condemned anyone who opened a door to argument and dispute." },
      { title: "What the early Muslims meant", body: "The clear proofs in the Quran, which minds accept on first hearing, were known to all. Knowledge of the Quran was all of knowledge. For them oneness meant something else, which most theologians do not understand, and if they do, they do not have it. It means seeing all things as from God, in a way that cuts your attention off from causes and go-betweens. You see all good and evil as coming only from Him. This is a noble level. One of its fruits is trust in God, as the Book of Trust will show." },
      { title: "Its fruits", body: "Other fruits are no longer complaining about people or being angry at them, and being content and accepting God's rule. When Abu Bakr was ill, someone asked: “Shall we call a doctor for you?” He said: “The Doctor made me ill.” Another man, asked when ill what the doctor had said, answered: “He told me: I do what I will.” The Books of Trust and Oneness will give more evidence." },
      { title: "Two shells and a kernel", body: "Oneness is a precious jewel with two shells, one further from the kernel than the other. People have given the name to the shell, and to the craft of guarding the shell, and left the kernel entirely. The first shell is saying with your tongue: there is no god but God. This is called oneness, against the Trinity the Christians declare. But a hypocrite, whose inside differs from his outside, can say it too." },
      { title: "The second shell", body: "The second shell is that there is nothing in the heart that rejects or denies what the words mean. The outer heart holds it as belief and accepts it. This is the oneness of ordinary people. The theologians, as said, are the guards of this shell against heretics' confusion." },
      { title: "The kernel", body: "The third is the kernel. It is seeing all things as from God, in a way that cuts your attention off from go-betweens. It is worshipping Him in a way that makes Him alone the one worshipped. Following desire takes a person out of this oneness. Whoever follows his desire has taken his desire as the one he worships. God says: “Have you seen the one who has taken his desire as his god?” The Prophet said: “The most hateful god worshipped on earth, in God's sight, is desire.”" },
      { title: "The idol-worshipper's real god", body: "Anyone who thinks about it knows that the idol-worshipper does not really worship the idol. He worships his desire, since his self leans to his fathers' religion and he follows that leaning. The self leaning to what it is used to is one of the meanings of desire. Being angry at people and paying attention to them also take a person out of this oneness. How can someone who sees everything as from God be angry at anyone else? Oneness meant this level, the level of the truthful. See what it has been turned into, and which shell people have settled for." },
      { title: "The first lie of the day", body: "They boast of a praised name while bankrupt of the meaning that earns real praise. It is like the man who gets up in the morning and faces the direction of prayer. He says: “I have turned my face to the One who created the heavens and the earth, as a true believer.” That is the first lie he tells God each day, unless his heart is turned to God alone. If he means his outer face, he has only turned it to the Kaaba and away from other directions. The Kaaba is not the direction of the One who created the heavens and the earth. God is far above being bounded by directions." },
      { title: "The tongue is an interpreter", body: "If he means the face of his heart, which is what worship asks for, how is he truthful? His heart is wandering among his worldly wants and needs, looking for ways to gather money and status and more means, turned wholly to them. When did he turn his face to the One who created the heavens and the earth? These words describe real oneness. The one who holds God one sees only the One and turns his face only to Him. That is obeying “Say: God. Then leave them to play in their chatter.” It does not mean saying it with the tongue. The tongue is an interpreter, true at times and lying at others. What God looks at is the heart it speaks for. The heart is the mine and spring of oneness." },
    ],
    closer: [
      { title: "Three ways to say it", body: "The tongue can say “There is no god but God” while the heart denies it. The heart can believe it while desire still rules. Only the kernel sees God behind everything and worships nothing else." },
      { title: "The morning test", body: "Ghazali's test is one sentence from the opening of the prayer. Every morning, the words “I have turned my face” are either the truth or the day's first lie." },
    ],
    distinction: ["Two ways to hold God one", "The shells", "Saying it, and believing it. A hypocrite can do the first; ordinary people do the second, and theologians guard it.", "The kernel", "Seeing everything as from God and worshipping Him alone, with no desire beside Him. The level of the truthful."],
    misreading: "Ghazali does not say the two shells are worthless. The first protects life and property; the second is the faith of ordinary Muslims. His point is that the name for the kernel has been given to the shell.",
    reflection: "Tomorrow, when you say “I have turned my face,” notice where your heart is facing.",
    audit: ["Which desire do I obey as if it were a god?", "Do I see the causes, or the One behind them?", "Do I get angry at people for what God decreed?", "Is my morning prayer's first sentence true?"],
    nodes: ["alfaz", "tawhid"],
    model: spectrum("The shells and the kernel", "Ghazali's three layers of oneness.", [["The outer shell", "Saying there is no god but God; a hypocrite can say it.", "warning"], ["The inner shell", "Believing it in the outer heart: ordinary people's oneness.", "balance"], ["The kernel", "Seeing all from God and worshipping Him alone.", "support"]]),
  }),
  makeChapter({
    id: 20, shortTitle: "Reminding, turned to stories", formalTitle: "The changed names: reminding, and the storytellers, love poems, wild claims and strange readings",
    overview: "The fourth word is reminding, the praised work of the gatherings of remembrance. It has been moved to what most preachers now do: stories, poetry, ecstatic sayings and strange interpretations. Ghazali takes each in turn.",
    thesis: "Praised reminding is talk of the next life, death, the self's faults and God's blessings. Stories are an innovation unless true and from the prophets. Love poetry stirs lust in a crowd. Wild claims of union with God harm ordinary people, and inner readings that throw out the plain sense of the Quran destroy trust in words.",
    moves: [
      { title: "The gardens of the Garden", body: "The fourth word is reminding. God says: “Remind, for reminding helps the believers.” Many reports praise gatherings of remembrance. The Prophet said: “When you pass the gardens of the Garden, graze in them.” They asked what these were. He said: “Gatherings of remembrance.” In another report, God has roaming angels besides those assigned to people. When they see gatherings of remembrance, they call each other: “Come to what you seek.” They come, surround the gathering and listen. So remember God, and remind yourselves." },
      { title: "Storytellers", body: "This has been moved to what most preachers now keep doing: stories, poems, ecstatic claims and strange readings. Stories are an innovation. The early Muslims forbade sitting with storytellers. They said it did not happen in the time of the Prophet, Abu Bakr or Umar, until trouble arose and storytellers appeared. Ibn Umar left the mosque and said: “Only the storyteller drove me out.” Damra asked Sufyan al-Thawri: “Should we face the storyteller?” He said: “Turn your backs on innovations.” Ibn Awn told Ibn Sirin that the governor had forbidden storytellers. He said: “He has been guided to what is right.”" },
      { title: "Al-A'mash and the liar", body: "Al-A'mash came into the great mosque of Basra and saw a storyteller saying: “Al-A'mash told us.” He went into the middle of the circle and started plucking his armpit hair. The storyteller said: “Old man, have you no shame?” He said: “Why? I am doing a Sunna, and you are lying. I am al-A'mash, and I never told you that.” Ahmad said: “The biggest liars are storytellers and beggars.” Ali put the storytellers out of the great mosque of Basra. When he heard al-Hasan al-Basri speak, he did not put him out." },
      { title: "What al-Hasan spoke of", body: "Al-Hasan spoke of the knowledge of the next life, thinking of death, the self's faults, the harms of deeds, Satan's whispers and how to guard against them. He reminded people of God's gifts and blessings and how people fall short in thanking Him. He taught how small the world is, its faults, how it passes and breaks its promises, and the danger and terrors of the next life. This is the reminding the law praises. Abu Dharr's report encourages it: attending a gathering of remembrance is better than praying a thousand units. Ata said one gathering of remembrance makes up for seventy of idle fun." },
      { title: "Stories that harm", body: "The decorators took these reports as proof of their own worth and moved the name of reminding to their myths. They forgot the praised way of remembrance and took up stories, which grow, shrink and change, and go beyond and add to the stories in the Quran. Some stories help to hear and some harm, even if true. Whoever opens that door mixes true and false, helpful and harmful. That is why it was forbidden. Ahmad ibn Hanbal said: “How much people need a truthful storyteller!” If the story is of the prophets, about their religion, and the teller is truthful and reports soundly, Ghazali sees no harm in it." },
      { title: "Two things to avoid", body: "He should avoid lies. He should also avoid stories of great people's slips and lapses. Ordinary people cannot understand them, or cannot see were rare slips followed by atonement and covered by good deeds. The ordinary person grabs hold of them for his own lapses. He says: “They tell such-and-such of some great shaykh. We all sin; no wonder I disobey God, when greater men than me did.” This makes him bold against God without knowing it. Beyond these two, stories are fine. Some people allow themselves to make up stories that encourage obedience, saying they mean to call people to the truth. This is Satan's whispering. Truth leaves no need for lies, and what God and His messenger said leaves no need to invent." },
      { title: "Rhymed prose", body: "Straining for rhymed prose is disliked as affectation. Sa'd ibn Abi Waqqas heard his son Umar speaking in rhyme when he came to ask for something. He said: “This is what makes you hateful to me. I will never grant your need until you repent.” The Prophet said to Abd Allah ibn Rawaha, over a rhyme of three phrases: “Beware of rhymed prose, Ibn Rawaha.” So the forbidden kind seems to be what goes beyond two phrases. When a man spoke in rhyme about the blood-money for an unborn child, the Prophet said: “Rhymed prose like the desert Arabs'?”" },
      { title: "Love poems in the sermon", body: "Filling sermons with poetry is blamed. God says: “As for the poets, the misguided follow them. Do you not see them wandering in every valley?” And: “We did not teach him poetry, nor would it suit him.” Most of the poetry preachers use describes love, the beloved's beauty, the joy of meeting and the pain of parting. The audience is rough ordinary people, full of desires, their hearts drawn to pretty faces. The poems only stir what is already there. The fire of lust flares, and they shout and act out ecstasy. Most or all of this is corruption. Only poetry with a lesson or wisdom should be used, as evidence or for comfort. The Prophet said: “Some poetry is wisdom.”" },
      { title: "Junayd's small circle", body: "Suppose the gathering were only the special few, whose hearts are known to be drowned in love of God. Then poetry that seems to be about people would not harm them. The listener applies what he hears to whatever rules his heart, as the Book of Listening will explain. That is why Junayd spoke to a dozen or so people, and if there were more he did not speak. His gathering never reached twenty. People gathered at Ibn Salim's door and he was told: “Speak, your companions have come.” He said: “No. These are not my companions. They are the gathering's companions. My companions are the special few.”" },
      { title: "Wild claims", body: "By ecstatic sayings Ghazali means two kinds of talk some Sufis started. The first is long, wide claims of love for God and union with Him, which they say makes outward acts unnecessary. Some go as far as claiming to be united with God, the veil lifted, seeing Him with their eyes and speaking with Him face to face. They say: “We were told this, and we said that.” They copy al-Hallaj, who was crucified for such words, and quote his “I am the Truth”, and what is told of Abu Yazid al-Bistami: “Glory be to me.” This kind of talk does great harm to ordinary people. Some farmers left their farming and made such claims. It pleases human nature, since it means idleness from work together with praise of oneself for reaching high states." },
      { title: "Why the harm is so great", body: "The dullest people are able to claim it and to pick up jumbled, fancy phrases. If anyone objects, they say: “This objection comes from knowledge and argument. Knowledge is a veil and argument is the self's work. This only shines from within, by the unveiling of the truth's light.” Such talk has spread its sparks across the lands and greatly harmed ordinary people. Ghazali judges that killing someone who says such things is better in God's religion than bringing ten people to life. As for Abu Yazid, what is told of him is not sound. If he was heard saying it, perhaps he was repeating God's words to himself. It would be like being heard saying “I am God; there is no god but Me, so worship Me.” That could only be understood as quoting." },
      { title: "Words no one understands", body: "The second kind is phrases that are not understood. They sound beautiful and frightening, with nothing behind them. Either the speaker himself does not understand them and says them from a muddled mind, having half heard something beyond him, which is most common. Or he understands but cannot explain, having little training in knowledge or in putting meanings into clear words. Such talk only confuses hearts, stuns minds and bewilders thoughts, or leads people to read in meanings never meant, each by his own desire. The Prophet said: “Whenever one of you tells people something they do not understand, it becomes a trial for them.” And: “Speak to people of what they know, and leave what they would reject. Do you want God and His messenger to be called liars?” If even what the speaker understands is not to be said beyond the hearer, how much less what he does not understand!" },
      { title: "Wisdom in its place", body: "Jesus said: “Do not put wisdom with those not fit for it, or you wrong it. Do not keep it from those fit for it, or you wrong them. Be like a gentle doctor who puts the medicine where the illness is.” In another wording: “Whoever puts wisdom with those not fit for it is ignorant, and whoever keeps it from those fit for it is unjust. Wisdom has a right and it has its people, so give each its due.”" },
      { title: "Strange readings", body: "Strange readings share the faults of wild claims, and add one of their own. They turn the words of the law from their plain meaning to inner things that give the mind nothing, as the Batinis do. This too is forbidden, and the harm is great. Suppose words are turned from their plain sense without support from the Prophet's teaching, and without a need from reason. Then trust in words is lost, and the Quran and Sunna stop being useful. What the mind grasps first cannot be trusted, and the inner meaning has no rule; thoughts clash and it can be read many ways. They do it to seem original, since people love the strange. By this road the Batinis set out to pull down the whole law, as Ghazali showed in his book against them." },
      { title: "Pharaoh is not the heart", body: "An example: some say “Go to Pharaoh, for he has rebelled” refers to the heart, which is the Pharaoh that rebels in everyone. They read “Throw down your staff” as throwing down whatever you lean on besides God. They read the Prophet's “Eat the pre-dawn meal, for there is blessing in it” as asking forgiveness before dawn. So they bend the Quran from beginning to end away from its plain meaning and the commentary reported from Ibn Abbas and the other scholars. Some such readings are certainly false. Pharaoh was a real person, whose existence and Moses' call to him have reached us by mass report, like Abu Jahl and Abu Lahab. He is not like angels and devils, which the senses do not reach. The Prophet used to eat and say: “Eat the pre-dawn meal,” and “Come to the blessed breakfast.”" },
      { title: "Opinion and deeper reading", body: "All this is forbidden and misleading, and it corrupts people's religion. Nothing like it is reported from the Companions, the next generation, or al-Hasan al-Basri, though he spent his life calling and preaching to people. This is what the Prophet meant: “Whoever explains the Quran by his own opinion, should take his seat in the Fire.” That is, a person who wants to prove a point and drags the Quran in as a witness, with no support from language or transmission. It does not mean the Quran may not be explained by reflection and drawing out. For some verses, five, six or seven meanings are reported from the Companions and commentators. We know they were not all heard from the Prophet, since some cannot all be true together. So they were drawn out by good understanding and long thought. That is why the Prophet prayed for Ibn Abbas: “O God, give him understanding of the religion and teach him interpretation.”" },
      { title: "Worse than a forged report", body: "Someone may allow such readings, knowing the words do not mean them, and say he does it to call people to the Creator. He is like someone who allows forging reports from the Prophet for things true in themselves. Like one who makes up a report for every question he thinks right. That is wrong and misguided, and falls under the warning: “Whoever lies about me on purpose, should take his seat in the Fire.” The evil of these readings is even greater, because they destroy trust in words and cut off the road to understanding the Quran altogether." },
    ],
    closer: [
      { title: "Why al-Hasan stayed", body: "Ali cleared the storytellers from the mosque and let al-Hasan stay. The difference was the content: death, the self's faults, God's blessings and the next life." },
      { title: "Words that lose their meaning", body: "Ghazali's objection to strange readings is not about deep meanings. The Companions drew out many. It is about throwing away the plain sense, which leaves the Quran with no meaning anyone can trust." },
    ],
    distinction: ["Two things called reminding", "The praised kind", "Death, the self's faults, Satan's whispers, God's blessings, the world's smallness, the next life's terrors.", "The moved kind", "Stories, love poems, wild claims and strange readings that please the crowd."],
    misreading: "Ghazali does not condemn every Sufi or every deep reading. He defends Abu Yazid, praises Junayd's small circle, and accepts meanings drawn out by thought. He condemns claims that excuse people from outward acts, and readings that erase the plain sense.",
    reflection: "Think of the last talk that moved you. Was it death and the next life, or a story and a feeling?",
    audit: ["Do I pass on stories I have not checked?", "Do great people's slips make me bolder in sin?", "Do I prefer the strange to the plain?", "Do I read my own opinion into the Quran?"],
    nodes: ["alfaz", "tadhkir"],
    model: spectrum("What passes for reminding", "From the praised to the most harmful.", [["Reminding", "Death, the self, God's blessings: praised by the law.", "support"], ["Stories and poems", "Allowed if true and useful; harmful as crowd-pleasers.", "balance"], ["Wild claims", "Union with God and no need for works: great harm to ordinary people.", "warning"], ["Strange readings", "Throwing out the plain sense: destroys trust in the Quran.", "warning"]]),
  }),
  makeChapter({
    id: 21, shortTitle: "Wisdom, and the strangers", formalTitle: "The changed names: wisdom, the bad scholars, and the strangers who keep the old knowledge",
    overview: "The fifth word is wisdom. Once praised by God, it is now used for doctors, poets, astrologers and even the man rolling dice in the street. Ghazali warns that bad scholars are worse than devils, and says the old sciences have become strangers.",
    thesis: "All five words show how Satan turned people from praised knowledge to blamed, by the trickery of bad scholars. If you follow a famous name without asking what it meant in the first age, you are like someone seeking wisdom from a street dice-roller. The early sciences have faded, and those who keep them are strangers.",
    moves: [
      { title: "Wisdom for a dice-roller", body: "The fifth word is wisdom. The title “wise man” is now used for a doctor, a poet and an astrologer. It is used even for the man who rolls dice on the palms of country people in the streets. Yet God praised wisdom: “He gives wisdom to whom He wills, and whoever is given wisdom has been given much good.” The Prophet said: “A word of wisdom a man learns is better for him than the world and all in it.” See what wisdom meant, and what it was moved to, and judge the other words by it." },
      { title: "Worse than devils", body: "Beware of being fooled by bad scholars' tricks. Their harm to religion is greater than the devils'. Through them Satan works his way to pulling religion out of people's hearts. That is why, when the Prophet was asked who were the worst of creation, he refused, saying, “O God, forgive,” until they asked again. Then he said: “They are the bad scholars.” Suppose you follow such people because of a famous name, without regard to what was known in the first age. Then you are like someone seeking the honour of wisdom by following whoever is called wise." },
      { title: "Your choice", body: "Now you know praised and blamed knowledge, and where the confusion comes from. The choice is yours. You can look to yourself and follow the early Muslims, or hang from the rope of deception and imitate those who came later. The sciences the early Muslims approved have faded. What most people give themselves to is mostly new and invented." },
      { title: "The strangers", body: "The Prophet said truly: “Islam began as a stranger and will return to being a stranger as it began. Good news for the strangers!” Who are they? “Those who set right what people have spoiled of my Sunna, and those who bring to life what they have killed of my Sunna.” In another report: “They are those who hold to what you are on today.” In another: “The strangers are a few righteous people among many people; those who hate them are more than those who love them.”" },
      { title: "Too many friends", body: "Those sciences have become so strange that anyone who speaks of them is hated. That is why al-Thawri said: “If you see a scholar with many friends, know he is mixing truth with falsehood. If he spoke the truth, they would hate him.”" },
    ],
    closer: [
      { title: "A test for your own field", body: "Ghazali asks the reader to measure the other words by wisdom. Take any praised title in your own field and ask what it meant in the first age, and whom it is used for now." },
      { title: "The scholar with many friends", body: "Al-Thawri's line is a hard test. It does not say a good scholar has no friends. It says the truth costs friends, and a scholar who has lost none may not be telling it." },
    ],
    distinction: ["Two ways to choose whom to follow", "By the famous name", "Following whoever holds the title: like seeking wisdom from a street dice-roller.", "By the first age's meaning", "Asking what the word meant to the early Muslims, and following those who have that."],
    misreading: "Calling bad scholars worse than devils does not mean scholars in general are suspect. It is because they are trusted that their harm is greater; people guard against the devil, but follow the scholar.",
    reflection: "Think of a word of praise you use for someone: wise, learned, pious. What did it mean in the first age?",
    audit: ["Do I follow names or meanings?", "Would I be one of the strangers, or one of the crowd?", "Do I stay silent about the truth to keep friends?", "Which of the five words have I used carelessly?"],
    nodes: ["alfaz", "hikma", "ghuraba"],
    model: chain("The five changed names", "Ghazali's list, with what each became.", [["Understanding", "Narrowed to rare legal cases.", "warning"], ["Knowledge", "Narrowed to winning debates.", "warning"], ["God's oneness", "Moved to the craft of theology.", "warning"], ["Reminding and wisdom", "Moved to storytelling, and to anyone at all.", "warning"]]),
  }),
  makeChapter({
    id: 22, shortTitle: "How much is praised", formalTitle: "The praised amount of the praised sciences: three kinds, the order of study, and the three levels of each science",
    overview: "Some knowledge is blamed however little, some is praised however much, and some is praised only up to what is enough. Ghazali tells you to heal yourself first, then take the communal sciences in order, at one of three levels, and warns against partisanship and disputed questions.",
    thesis: "Knowledge of God has no limit; the more the better. The communal sciences are good up to a point, like giving money or courage. Work on your own heart first; do not chase flies off others while snakes are under your own clothes. Then study in order, never spending your life on one tool.",
    moves: [
      { title: "Three kinds", body: "In this respect knowledge is of three kinds. Some is blamed, a little or a lot. Some is praised, a little or a lot, and the more the better. Some is praised only up to what is enough, and going beyond is not praised. It is like the body. Some things are praised in any amount, like health and beauty. Some are blamed in any amount, like ugliness and bad character. Some are praised in moderation. Giving money is one: wastefulness is not praised, though it is a kind of giving. Courage is another, since recklessness is not praised though it is a kind of courage." },
      { title: "Blamed in any amount", body: "Knowledge blamed a little or a lot is what has no use for religion or the world, because its harm outweighs its benefit, like magic, talismans and astrology. Some of it has no use at all, and spending life on it is waste; wasting the precious is blamed. Some of it does more harm than whatever worldly aim it seems to meet." },
      { title: "The ocean with no floor", body: "The knowledge praised to the furthest limit is knowledge of God, His qualities and His acts. It is knowing His ways in creation and His wisdom in setting the next life after this one. It is sought for itself and for the happiness of the next life. Giving all you can to it still falls short of what it deserves. It is the ocean whose depth cannot be reached. People circle its shores as far as they are able. Only prophets, friends of God and those firm in knowledge have waded in, each by his strength and what God decreed. This is the hidden knowledge not written in books. Learning helps at the start, and seeing the scholars of the next life. Later, striving, training, cleansing the heart and emptying it of the world help. It opens to each seeker by what he is given, not by his effort. But effort is still needed. Striving is the key to guidance; it has no other key." },
      { title: "Good up to a point", body: "The sciences praised only up to a point are the communal duties listed earlier. Each has a minimum, which is the least; a middle, which is moderate; and a thorough level beyond that, which has no end until life ends. Be one of two men. Either be busy with yourself, or free for others after you have finished with yourself. Beware of working to set others right before you have set yourself right." },
      { title: "Rubbing ointment on boils", body: "If you are busy with yourself, study only what is your duty given your state. For outward acts, that is prayer, purification and fasting. What matters most, and what everyone has neglected, is knowledge of the heart's qualities, praised and blamed. No human is free of blamed traits like greed, envy, showing off, pride and self-admiration, and all of them destroy. Busying yourself with outward acts alone is like rubbing ointment on the skin for scabies and boils, while neglecting to draw out the cause by bleeding and purging. The shallow scholars advise outward acts, as quack doctors advise ointment. The scholars of the next life advise only cleansing the inside and cutting evil off at its roots." },
      { title: "Why people choose the ointment", body: "Most people run to outward acts rather than cleansing hearts because the acts of the limbs are easy and the acts of the heart are hard. It is like someone who hates bitter medicine running to ointments. He keeps toiling with the ointment, the cause keeps growing, and his illnesses multiply. If you want the next life and safety from lasting ruin, study the inner illnesses and their cure as set out in the Quarter of Things that Destroy. That will lead you on to the praised levels in the Quarter of Things that Save. When the heart is emptied of the blamed, it fills with the praised. When ground is cleared of weeds, crops and sweet herbs grow." },
      { title: "Snakes under your clothes", body: "So do not busy yourself with communal duties, especially when others are already doing them. Whoever ruins himself over what helps others is a fool. Picture a man with snakes and scorpions under his clothes, about to kill him. He looks for a fly-whisk to keep the flies off someone else. How foolish he is! The whisk will not save him from the snakes when they strike." },
      { title: "Then study in order", body: "Suppose you have finished with yourself and cleansed it. You are able to leave sin outward and inward, and it has become your easy habit. How far that is from you! Then turn to the communal duties, in order. Start with God's Book, then the Sunna of His messenger. Then commentary and the other Quran sciences: abrogating and abrogated, separated and joined, clear and ambiguous; and the same for the Sunna. Then the branches of law, the law of your school, not the disputed questions. Then the principles of law, and so on through the other sciences as your life and time allow." },
      { title: "Tools, not ends", body: "Do not spend your life on one of them trying to exhaust it. Knowledge is much and life is short. These sciences are tools and preliminaries, sought for something else. Whatever is sought for something else should not make you forget the goal, nor be piled up. From language, take what lets you understand and speak Arabic, and from its rare words, the rare words of the Quran and reports; leave going deep. From grammar, take what relates to the Book and the Sunna. Every science has a minimum, a middle and a thorough level." },
      { title: "Commentary and reports", body: "Ghazali gives the levels for four sciences so you can measure others. In Quran commentary, the minimum is twice the length of the Quran, like al-Wahidi's Concise Commentary. The middle is three times, like his Middle Commentary. Beyond that is thoroughness that is not needed and never ends. In reports, the minimum is having what is in the two Sahih collections, from a copy checked with a man expert in the texts. You are spared memorising narrators' names by those before you who carried it for you; you may rely on their books. You need not memorise the texts of the two Sahihs, but know them well enough to find what you need. The middle adds what is in the sound collections outside them. Thoroughness is everything beyond, gathering all that was transmitted, weak and strong, with the many chains and the narrators' names and states." },
      { title: "Law and theology", body: "In law, the minimum is what is in al-Muzani's Abridgement, which Ghazali arranged in his Summary of the Abridgement. The middle is three times that, as in his Middle book on the school. Thoroughness is his Long book and beyond. In theology, the aim is only to protect the beliefs the Sunni community received from the early Muslims. Anything beyond is seeking the reality of things by the wrong road. The minimum is a short creed, as in the Book of the Foundations of Belief in the Ihya. The middle is about a hundred pages, as in his Moderation in Belief. It is needed to debate a heretic and answer his heresy so as to pull it out of an ordinary person's heart." },
      { title: "Before the partisanship hardens", body: "This only helps with ordinary people before their partisanship hardens. Once a heretic has learned even a little debate, theology rarely helps. If you silence him, he will not leave his school. He will blame himself for failing, and assume someone else has an answer. He will think you only confused him by skill in arguing. An ordinary person led astray by some argument can be brought back by another, before partisanship hardens. Once it hardens, there is no hope, since partisanship fixes beliefs in the soul." },
      { title: "The bad scholars' partisanship", body: "This is one of the harms of bad scholars. They go too far in partisanship for the truth, and look at opponents with scorn. That makes the other side answer in kind, and strengthens their drive to defend falsehood and cling to what they are called by. If the scholars came with gentleness, mercy and private advice, not partisanship and contempt, they would succeed. But status depends on having followers, and nothing wins followers like partisanship, cursing and insulting opponents. So they made it their habit and tool, and called it defending religion and fighting for Muslims. In truth it ruins people and fixes heresy in their souls." },
      { title: "Keep away from disputed questions", body: "As for the disputed questions invented in recent times, with more writings and debates than the early Muslims ever knew, do not go near them. Avoid them like deadly poison. They are the chronic disease that turned all the lawyers towards rivalry and showing off. Someone may say: “People are enemies of what they do not know.” Do not think so. You have come to the one who knows. Take this advice from someone who spent a long time on it, and added to the early writers in writing, research, debate and explanation. Then God inspired him to his right course and showed him its fault, and he left it and turned to himself." },
      { title: "Safe from jinn devils", body: "Do not be fooled by the claim that rulings are the pillar of the law and their reasons are only known through disputed questions. The reasons of the school are in the school's books. What goes beyond is debate the early Muslims and Companions never knew, and they knew the reasons of rulings better than anyone. It does not help with the school's law, and it harms and spoils the feel for law. What a lawyer's sound instinct supports usually cannot be pushed through the rules of debate. Someone whose nature has got used to debate's forms gives in to debate and grows timid about his feel for law. Those who busy themselves with it do so for fame and status. Be safe from the devils among the jinn, and beware the devils among people. They have spared the jinn the trouble of leading people astray." },
      { title: "Alone with God", body: "In short, sensible people approve of this. Picture yourself alone in the world with God, with death before you, and the reckoning, the account, the Garden and the Fire. Think about what concerns you of what lies ahead, and leave the rest. One of the shaykhs saw a certain scholar in a dream and asked him: “What became of those sciences you used to argue and debate over?” He spread his hand, blew on it and said: “They all blew away like scattered dust. Nothing helped me except two units of prayer that were sincerely mine, in the middle of the night.”" },
      { title: "What the reports say about argument", body: "A report says: “No people went astray after guidance except that they were given argument.” Then he recited: “They only gave it to you as argument; they are a quarrelsome people.” A report on the verse “As for those in whose hearts is a swerving” says: “These are the people of argument whom God meant: beware of them.” One of the early Muslims said: “At the end of time there will be people for whom the door of action is closed. The door of argument will be opened for them.” Some reports say: “You are in a time when you are inspired to act, and people will come who are inspired to argue.” A well-known report: “The most hateful of creation to God is the fiercest in argument.” And: “No people were given logic but they were kept from action.”" },
    ],
    closer: [
      { title: "A confession", body: "“You have come to the one who knows.” Ghazali is describing his own past. He wrote more on disputed questions than the early writers, and then left them. That gives the warning its weight." },
      { title: "The two units at night", body: "The dream is the whole chapter in one picture. The debates blew away like dust. What remained was two units of prayer no one saw." },
    ],
    distinction: ["Two kinds of praised knowledge", "Praised without limit", "Knowledge of God, His qualities and acts: an ocean no one reaches the floor of.", "Praised up to a point", "The communal sciences, which are tools: take the minimum or the middle, and do not spend a life on one."],
    misreading: "Ghazali is not telling people to stop studying law or theology. He sets out an exact order and three levels for each, and names his own books at each level. What he forbids is putting others before yourself, and spending a life on disputed questions.",
    reflection: "Picture yourself alone with God, with death, the reckoning, the Garden and the Fire ahead. What would you stop studying? What would you start?",
    audit: ["Am I chasing flies off others with snakes under my own clothes?", "Am I rubbing ointment on outward acts while the cause inside grows?", "Have I stopped at the level of a science I need?", "Do I win arguments or win hearts?"],
    nodes: ["measure", "qalb", "tartib"],
    model: spectrum("Three levels of every science", "Ghazali's measure, with law as the example.", [["The minimum", "Al-Muzani's Abridgement: enough for most.", "support"], ["The middle", "Three times as much: Ghazali's Middle book.", "balance"], ["Thoroughness", "His Long book and beyond: no end until life ends.", "warning"]]),
  }),
  makeChapter({
    id: 23, shortTitle: "How debate took over", formalTitle: "Why people turned to disputed questions: the history from the rightly guided caliphs to Ghazali's day",
    overview: "Ghazali gives a history. The first caliphs were scholars, so the scholars were free for the next life and fled office. Later rulers needed lawyers, and people saw the honour scholars had. They turned to law to win it, then to theology, then to debates between the Shafii and Hanafi schools, each time following what the powerful wanted to hear.",
    thesis: "The move to legal verdicts, then theology, then disputed questions, was driven by what rulers and great men liked. Scholars who had been sought became seekers, and honoured by turning from rulers became humbled by turning to them. If the powerful had liked another subject, the debaters would have followed, still calling it religion.",
    moves: [
      { title: "Caliphs who were scholars", body: "After the Prophet, the caliphate was held by the rightly guided caliphs. They were leaders who knew God and understood His rulings, and gave their own verdicts in cases. They asked the lawyers for help only rarely, in cases that needed consultation. So the scholars were free for the knowledge of the next life and gave themselves to it. They pushed verdicts and worldly rulings away from each other and turned to God with all their effort, as their lives show." },
      { title: "Scholars who were chased", body: "Then the caliphate passed to people who held it without deserving it and without enough knowledge of verdicts and rulings. They had to seek help from lawyers and keep them close in every matter, to ask for verdicts. Some of the scholars of the next generation were still on the first pattern, holding to pure religion and the manner of the early scholars. When sought, they ran and turned away. So the caliphs had to press them hard to take posts as judges and officials." },
      { title: "Seekers instead of sought", body: "People of those times saw the honour the scholars had, and how rulers and governors turned to them while they turned away. So they reached for knowledge as a way to win honour and status from the rulers. They threw themselves into the science of verdicts, offered themselves to the rulers, made themselves known to them, and asked for posts and gifts. Some were refused and some succeeded. Even the successful were not free of the humiliation of asking. So the lawyers, once sought, became seekers. Once honoured by turning from rulers, they were humbled by turning to them, except those God guided in each age." },
      { title: "Then theology", body: "In those times most attention went to verdicts and judgments, since rulers needed them badly. Then came great men and princes who listened to people's views on the foundations of belief and liked hearing the arguments. When people saw this, they threw themselves into theology. They wrote much, set out methods of debate, and worked out ways to refute opinions. They claimed their aim was to defend God's religion, fight for the Sunna and put down heretics. In the same way, those before them had claimed their aim in giving verdicts was religion and care for God's creatures." },
      { title: "Then Shafii against Hanafi", body: "Then came great men who did not approve of going into theology and opening its door to debate. They disliked it because of the ugly partisanship and widespread quarrels it had caused, ending in bloodshed and ruined towns. They liked debate on law instead, especially over which was better, the school of al-Shafi'i or of Abu Hanifa. So people left theology and the other sciences, and poured into the disputed questions between those two. They were easier about the disagreements with Malik, Sufyan, Ahmad and others." },
      { title: "They would have followed anything", body: "They claimed their aim was to draw out the fine points of the law, settle the reasons behind the school, and lay the foundations of verdicts. They wrote much and set out every kind of debate, and they are still at it. Ghazali says he does not know what God will bring about after his time. This, and nothing else, is what drove people to disputed questions and debates. If the worldly men had liked disagreement with another imam, or another science, they would have followed. They would still have said that what they were busy with was religious knowledge, and that they sought only nearness to the Lord of the worlds." },
    ],
    closer: [
      { title: "A question of history first", body: "Ghazali explains the rise of debate by who was paying attention, not by people growing less religious. Each shift follows what rulers wanted to hear." },
      { title: "Sought, then seeking", body: "The whole story is in one reversal. The scholars who fled office were chased by caliphs. Their successors chased the caliphs." },
    ],
    distinction: ["Two kinds of scholar in the history", "The sought", "The early scholars who fled office and gave themselves to the next life. Rulers had to press them to serve.", "The seekers", "Those who saw that honour and offered themselves to rulers, and were humbled by it."],
    misreading: "Ghazali does not say law or theology began from bad motives. He says their popularity in his day, and the move to disputed questions, followed the tastes of the powerful.",
    reflection: "Think about why you study what you study. If the people you want to impress liked something else, would you switch?",
    audit: ["Do I study what matters, or what is rewarded?", "Would I change subjects if fashion changed?", "Do I seek people in power, or does my work draw them?", "Do I call my ambition religion?"],
    nodes: ["munazara", "jah"],
    model: chain("How debate took over", "Ghazali's history, step by step.", [["Scholar-caliphs", "Gave their own verdicts; scholars free for the next life.", "support"], ["Rulers needing lawyers", "Scholars fled and were chased; others saw the honour.", "balance"], ["Verdicts, then theology", "Each followed what great men liked to hear.", "warning"], ["Shafii against Hanafi", "Disputed questions, still claimed as religion.", "warning"]]),
  }),
  makeChapter({
    id: 24, shortTitle: "Not like the Companions", formalTitle: "The false comparison with the Companions' consultations, and the eight conditions of honest discussion",
    overview: "Debaters say they are only searching for the truth together, as the Companions did in their consultations. Ghazali agrees that working together to find the truth is part of religion, but lists eight conditions and signs. The debaters of his day break every one.",
    thesis: "Honest discussion is only for someone free of his personal duties, who sees no more urgent communal duty, and who can judge for himself. It is on real questions, preferably in private. He looks for the truth like a lost camel, lets the other move between proofs, and chooses partners he can learn from. Measured by these, most debate is for show.",
    moves: [
      { title: "The claim", body: "Debaters draw people in by saying: “Our aim is to search out the truth so it becomes clear. Truth is sought, and helping each other think and sharing ideas is useful. That was the Companions' way in their consultations.” They mean the Companions' discussions over the grandfather and the brothers in inheritance, and the penalty for drinking. They mean the question of whether the ruler must pay if he errs, as when a woman miscarried from fear of Umar, and questions of inheritance. They also point to al-Shafi'i, Ahmad, Muhammad ibn al-Hasan, Malik, Abu Yusuf and other scholars. Ghazali grants that helping each other seek the truth is part of religion. But it has eight conditions and signs." },
      { title: "First: personal duties first", body: "The first is that someone who has not yet done his personal duties should not busy himself with it, since it is a communal duty. Whoever owes a personal duty and busies himself with a communal one, claiming he wants the truth, is a liar. It is like someone who does not pray himself, and gives his time to making and weaving clothes. He says: “I want to cover someone who has to pray naked because he has no clothes.” That might happen, just as the lawyer says the rare cases debated in disputed questions might happen. Those who debate neglect things that everyone agrees are personal duties. Someone who must return a deposit right now and instead starts a prayer, the best of acts, is sinning. An act is not obedience just because it is the kind of thing that is obedience. The time, the conditions and the order must be kept." },
      { title: "Second: no more urgent duty", body: "The second is that he sees no communal duty more important than debate. If he sees one and does something else, he sins. It is like someone who sees a group of thirsty people about to die, neglected by everyone. He could save them by giving them water, but he busies himself learning cupping. He says it is a communal duty and the town would perish without it. Told that the town has plenty of cuppers, he says that does not stop it being a communal duty. The debater is like that, while the town has communal duties no one is doing. Verdicts are already being given by many. The nearest neglected duty is medicine. Most towns have no Muslim doctor whose testimony can be relied on where the law depends on a doctor's word, and no lawyer wants to take it up." },
      { title: "Silk on the debater's seat", body: "Commanding good and forbidding wrong is also a communal duty. The debater may sit in his debate and see silk being worn and spread about, and say nothing. He debates a question that will never happen, and if it did, many lawyers would deal with it. Then he claims he is seeking nearness to God through communal duties. Anas said someone asked the Prophet: “When will commanding good and forbidding wrong be abandoned?” He said: “When flattery appears in your best, indecency in your worst, rule passes to your youngest, and law to your lowest.”" },
      { title: "Third: able to judge for himself", body: "The third is that the debater is able to reason for himself and gives verdicts by his own view, not by the school of al-Shafi'i or Abu Hanifa. Then the truth may appear to him in Abu Hanifa's school. If so, he leaves what agrees with al-Shafi'i and gives the verdict he now sees, as the Companions and the imams did. Someone who lacks that level, which is everyone of Ghazali's time, gives verdicts by quoting his own imam's school. If he saw its weakness, he could not leave it. So what use is debate to him? His school is known, and he may not give verdicts by another. When something troubles him, he must say: “Perhaps my imam had an answer, since I cannot reason independently from the sources.” If he debated questions where his imam had two views, it would make more sense, since he might lean to one. But debaters never debate those. They even skip them for questions where the disagreement is settled." },
      { title: "Fourth: real questions", body: "The fourth is to debate only a question that has happened or is likely to. The Companions consulted only about new events or likely ones, like inheritance. The debaters do not care to examine the questions ordinary people most need answers on. They want the “drum” questions that make a noise and give room for debate, however it goes. They may leave what happens often, saying: “This is a question settled by reports,” or “This is a side question, not a drum question.” The aim is supposed to be the truth. How strange, then, to drop a question because it is settled by reports, or because it gives them no room to talk at length! In seeking truth, the aim is to be brief and reach the goal quickly, not to talk long." },
      { title: "Fifth: private rather than public", body: "The fifth is that he prefers debating in private to debating in gatherings, before great men and rulers. Privacy is better for understanding, for a clear mind, and for finding the truth. A crowd stirs up showing off and makes each person eager to defend himself, right or wrong. You know their eagerness for gatherings is not for God. One of them may sit alone with another for a long time and not speak to him, and if the other suggests a question, not answer. When a great man appears or a gathering forms, he leaves no trick untried to be the one who does the talking." },
      { title: "Sixth: like looking for a lost camel", body: "The sixth is that he seeks the truth like someone looking for a lost camel. He does not mind whether it turns up in his hands or in the hands of someone helping him. He sees his partner as a helper, not an opponent. He thanks him when he shows him his mistake and makes the truth clear. It is just as he would thank someone who told him his camel was on another road. That is how the Companions consulted. A woman corrected Umar while he was giving a sermon before a crowd. He said: “A woman is right and a man is wrong.” A man asked Ali something, and Ali answered. The man said: “It is not so, Commander of the Faithful, but so.” Ali said: “You are right and I am wrong. Above everyone with knowledge is One who knows.”" },
      { title: "Abu Musa and Ibn Mas'ud", body: "Abu Musa al-Ash'ari, the governor of Kufa, was asked about a man who fought in God's cause and was killed. He said: “He is in the Garden.” Ibn Mas'ud stood up and said: “Repeat it to the governor; perhaps he did not understand.” They repeated it, and he gave the same answer. Ibn Mas'ud said: “I say: if he was killed and was on the truth, he is in the Garden.” Abu Musa said: “The truth is what he said. Do not ask me anything while this great scholar is among you.” That is fairness in seeking truth. Say such a thing today to the least lawyer, and he would reject it, saying it goes without saying. Look at today's debaters: a man's face darkens when the truth appears on his opponent's tongue. He is ashamed, fights it with all his might, and blames the one who silenced him for the rest of his life. Then he is not ashamed to compare himself to the Companions." },
      { title: "Seventh: let him change proofs", body: "The seventh is that he does not stop his partner moving from one proof to another, or one difficulty to another. That is how the early Muslims debated. He should drop all the invented tricks of debate. Examples are “I do not have to mention this,” or “This contradicts what you said first, so it is not accepted.” Returning to the truth contradicts falsehood, and must be accepted. Whole sessions are spent in such fencing. The one arguing compares a case to a root case for a reason he thinks is behind it. He is asked: “What proves the ruling in the root case is for this reason?” He says: “This is what I see. If you see something clearer, tell me so I can look at it.”" },
      { title: "“I know, but need not say”", body: "The objector insists: “There are other reasons besides yours. I know them, but I will not say them, since I do not have to.” The arguer says: “You must bring what you claim.” The objector insists he need not, and seeks out debates with such questions. The poor man does not realise that saying “I know it, but need not say it” is a lie against the law. If he does not know the reason and only claims it to defeat his opponent, he is a sinful liar who has earned God's anger. If he is telling the truth, he sins by hiding what he knows of the law. His Muslim brother asked him in order to understand. If the reason is strong, he would accept it; if weak, it could be shown and the brother brought from ignorance to knowledge. Everyone agrees that telling what you know of religion, when asked, is a duty. “I need not” means only: by the rules of debate we invented out of our own tastes. By the law he must. So by refusing he is either lying or sinning. Search the Companions' consultations: did anyone ever forbid moving from one proof to another, from analogy to a report, from a report to a verse?" },
      { title: "Eighth: someone you can learn from", body: "The eighth is to debate someone you expect to learn from, who is busy with knowledge. Most of them avoid debating the great and the strong, for fear the truth will appear on their tongues. They prefer those below them, hoping to pass off falsehood on them. There are many finer conditions, but these eight show who debates for God and who debates for some other reason." },
      { title: "The devil's joke", body: "In short, Satan has taken over such a man's heart. Satan is his worst enemy and keeps calling him to ruin, yet he does not debate Satan. Instead he debates others over questions where the one who reasons is either right or shares the reward of the one who is right. He is a laughing-stock for Satan and a lesson for the sincere. Satan gloats over him for the darkness of harms he has plunged him into. The next section counts them." },
    ],
    closer: [
      { title: "The lost camel", body: "Ghazali's test is simple. Someone looking for his lost camel thanks whoever points to it. Someone looking to win resents whoever proves him wrong. The face shows which one he is." },
      { title: "A rule you can keep alone", body: "The seventh condition needs no one else's help. You can always let the other person change his proof, and you can always refuse to say “I need not answer.”" },
    ],
    distinction: ["Two kinds of discussion", "The Companions' consultation", "About real events, often in private, thanking whoever found the truth: “A woman is right and a man is wrong.”", "The debate of Ghazali's day", "About noisy rare questions, before great men, with tricks to avoid being corrected, and a darkened face when the truth comes from the other side."],
    misreading: "Ghazali does not forbid discussion or disagreement. He grants that working together for the truth is part of religion. He gives conditions, and they are conditions the reader can check in himself.",
    reflection: "Think of your last argument. When the other person made a good point, did you feel glad, like someone told where his lost camel is?",
    audit: ["Have I done my personal duties before debating?", "Is there a more urgent duty going undone around me?", "Do I prefer to argue in front of people?", "Do I thank the person who corrects me?"],
    nodes: ["munazara", "shurut"],
    model: chain("The eight conditions", "Ghazali's signs of honest discussion.", [["Duties first", "Personal duties done; no more urgent communal duty neglected.", "support"], ["Able and relevant", "Can judge for himself; debates questions that really arise.", "balance"], ["Private and humble", "Prefers privacy; seeks truth like a lost camel.", "support"], ["Fair and teachable", "Lets the other change proofs; debates those he can learn from.", "support"]]),
  }),
  makeChapter({
    id: 25, shortTitle: "What debating grows", formalTitle: "The harms of debate: the ten vices it breeds, like wine for the sins of the heart",
    overview: "Debate for winning, silencing and showing off is the spring of every trait God hates. Ghazali compares it to wine: it opens the door to the heart's great sins as drink opens the door to the body's. He counts ten vices it breeds, then the branches that grow from them.",
    thesis: "The debater cannot escape envy, pride, spite, backbiting, self-praise, spying, joy at others' harm, hypocrisy, refusing the truth and showing off. The best of them only hide these and struggle with them. The same harms fall on preachers and lawyers who seek status. Knowledge does not leave its owner alone: it either ruins him forever or gives him life forever.",
    moves: [
      { title: "Like wine", body: "Some debate is made for winning, silencing others and showing off one's excellence. It is made for speaking grandly before people, boasting, quarrelling and winning attention. Such debate is the spring of every trait blamed by God and praised by His enemy Iblis. It relates to the inner sins, like pride, self-admiration, envy, rivalry, self-praise and love of status. It relates to them as drinking wine relates to the outer sins, like adultery, slander, murder and theft. Someone given the choice between drinking and the other sins thinks drinking is small and does it. Then, drunk, he is led to the rest. So too, someone ruled by love of winning and silencing, and of status and show, is led to hide every foulness in himself. The evidence against each of these comes in the Quarter of Things that Destroy. Here Ghazali points to the main ones." },
      { title: "Envy", body: "One is envy. The Prophet said: “Envy eats good deeds as fire eats firewood.” The debater cannot escape it. Sometimes he wins and sometimes he loses; sometimes his words are praised and sometimes another's. Someone in the world may be mentioned for strength in knowledge, or thought better at speaking and reasoning. As long as there is such a man, the debater must envy him, and wish his blessings gone and people's hearts turned from him to himself. Envy is a burning fire. Whoever suffers it is in torment in this world, and the next life's torment is worse. That is why Ibn Abbas said: “Take knowledge wherever you find it, but do not accept what lawyers say about each other. They are jealous of each other like billy goats in a pen.”" },
      { title: "Pride", body: "Another is pride and looking down on people. The Prophet said: “Whoever is proud, God lowers him, and whoever is humble, God raises him.” He told that God says: “Greatness is My garment and pride is My cloak. Whoever contests Me for either, I break him.” The debater cannot help being proud towards his equals and reaching above his level. They almost fight over a seat, competing over who sits higher or lower, nearer the head cushion or further, and who goes first through a narrow street. The dull and the cunning among them say they are guarding the honour of knowledge, since a believer is forbidden to humble himself. So they call the humility God and His prophets praised “humiliation”, and the pride God hates “the honour of religion”. They bend the name as was done with wisdom and knowledge." },
      { title: "Spite", body: "Another is spite. The debater is hardly ever free of it. The Prophet said: “The believer does not bear spite.” No debater can help bearing spite against someone who nods at his opponent's words and hesitates at his own, instead of listening well. The most he can do is hide it with hypocrisy, and it usually leaks out. How could he avoid it? All the listeners will never agree in preferring his words and admiring all he says. If his opponent shows the least disregard for his words, a spite takes root in him that he will not pull out for the rest of his life." },
      { title: "Backbiting", body: "Another is backbiting, which God compares to eating a dead body. The debater keeps eating the dead. He cannot help repeating and blaming his opponent's words. At most he takes care to report them truly and not lie. So he reports whatever shows the weakness and failure of his opponent's words and the lack of his merit. That is backbiting; lying about him is slander. He also cannot keep his tongue off the honour of anyone who turns from his words and listens to his opponent. He calls him ignorant, foolish, slow and dull." },
      { title: "Self-praise", body: "Another is praising oneself. God says: “Do not claim purity for yourselves. He knows best who is mindful of Him.” A wise man was asked what ugly truth is. He said: “A man praising himself.” The debater cannot avoid praising his own strength, his victories and his lead over his equals. During debate he keeps saying: “I am not someone who misses such things. I have mastered the sciences, I know the principles, I have memorised the reports,” and so on. Sometimes it is vanity and sometimes to sell his argument. Vanity and self-praise are blamed by law and reason." },
      { title: "Spying", body: "Another is spying and hunting out people's faults. God says: “Do not spy.” The debater is always looking for his equals' slips and his opponents' faults. When he hears a debater is coming to his town, he looks for someone who knows the man's private life. He draws out his faults by questions, storing them up to shame him when needed. He even asks about his childhood and his bodily defects, hoping to find a slip, or a flaw like baldness. If he feels the other gaining the least advantage, he hints at it if he is restrained, and this is admired as clever. If he is shameless, he says it outright, as is told of some great debaters counted among the best." },
      { title: "Joy at others' harm", body: "Another is being glad when others are hurt and sad when they are happy. Whoever does not love for his Muslim brother what he loves for himself is far from the character of believers. Anyone who seeks to show off his excellence is glad at what hurts his equals, and they hate each other like rival wives. When one wife sees another from afar, she shakes and goes pale. So too a debater who sees another debater: his colour changes and his thoughts are thrown, as if he saw a rebel devil or a savage beast. Where is the friendliness and comfort the scholars of religion used to feel when they met, and the brotherhood and help in good times and bad? Al-Shafi'i said: “Among people of merit and reason, knowledge is a bond of kinship.” How can people who have made knowledge a bitter enmity claim to follow his school? Can there be friendship between them while they seek to win and show off? The evil is enough that it gives you the character of hypocrites and strips you of the character of believers." },
      { title: "Hypocrisy", body: "Another is hypocrisy, which needs no proof that it is blamed. They are forced into it. They meet their opponents and their friends and followers, and must show friendship with their tongues, longing for them, and respect for their position. Speaker, hearer and everyone listening knows it is lies, falsehood, hypocrisy and wickedness. They are friends in their tongues and enemies in their hearts. The Prophet said: “People will learn knowledge and leave action. They will love each other with their tongues, hate each other with their hearts and cut family ties. When they do, God curses them, makes them deaf and blinds their eyes.” Al-Hasan reported it, and Ghazali says the sight of this state has proved it true." },
      { title: "Refusing the truth", body: "Another is being too proud to accept the truth, hating it and loving to argue against it. The most hateful thing to the debater is the truth appearing on his opponent's tongue. When it does, he sets out to deny it with all his effort, using every trick and deceit to push it away, until arguing becomes his second nature. He cannot hear anything without the urge to object. It takes over his heart even with the proofs of the Quran and the words of the law, and he sets some against others. Even arguing against falsehood is to be avoided, since the Prophet encouraged dropping arguments even when right. He said: “Whoever drops an argument when he is wrong, God builds him a house on the edge of the Garden. Whoever drops an argument when he is right, God builds him a house in the highest part of the Garden.” God has put the one who invents a lie against Him beside the one who denies the truth. He says: “Who does more wrong than one who invents a lie against God, or denies the truth when it comes to him?”" },
      { title: "Showing off", body: "Another is showing off, watching people and working to win their hearts and turn their faces. Showing off is the chronic disease that calls to the greatest sins, as the Book of Showing Off will explain. The debater's only aim is to shine before people and set their tongues praising him. These are ten traits, the mothers of the inner sins. That is not counting what happens among the unrestrained: quarrels ending in hitting, punching, slapping, tearing clothes, pulling beards, cursing parents and teachers, and open slander. Those are not counted among respectable people." },
      { title: "Even the best of them", body: "The great and sensible among them are the ones who cannot escape these ten. Some may be free of some of them with someone far below or above them, or far from their town and livelihood. None is free of them with his equals of the same level. From each of the ten branch out ten more. Ghazali names some without detail. There are disdain, anger, hatred and greed, and love of money and status to win and show off. There are wild celebration, honouring the rich and rulers, visiting them and taking their forbidden money. There is showing off with horses, mounts and forbidden clothes, and looking down on people with boasting and vanity. There are meddling, talking too much, and losing fear and mercy from the heart. There is heedlessness, so that one of them praying does not know what he prayed, what he recited, or to whom he spoke. He feels no humility. All while he spends his life on skills that help in debate and not in the next life: polished phrasing, rhymes, and memorising rare cases. Debaters differ in these by their level. Even the most religious and most sensible of them are never free of the stuff of these traits. The most they can do is hide them and struggle with them." },
      { title: "Not only debaters", body: "These vices also follow anyone who preaches and gives reminders, if his aim is acceptance, status, wealth and honour. They follow anyone busy with the law of his school and verdicts, if his aim is a judgeship, control of endowments, and getting ahead of his equals. In short, they follow anyone who seeks by knowledge anything other than God's reward in the next life. Knowledge does not leave the scholar alone. It ruins him forever or gives him life forever. That is why the Prophet said: “The person most severely punished on the Day of Resurrection is a scholar whom God did not let benefit from his knowledge.” It harmed him as well as failing to help him. Would that he had come out even! How far that is. The danger of knowledge is great. Its seeker seeks a lasting kingdom and endless bliss, so he gets either the kingdom or ruin." },
      { title: "The ball and the bat", body: "You may say: allowing debate has one use: it makes people want to seek knowledge, since without love of leadership the sciences would fade. You are right in one way, but it proves nothing. Without the promise of a ball, a bat and playing with sparrows, boys would not want to go to school. That does not show that the wanting is praised. Without love of leadership knowledge would fade, but that does not show the seeker of leadership is saved. He is among those the Prophet meant: “God supports this religion by people who have no share in the next life.” He also said: “God supports this religion by a wicked man.”" },
      { title: "Three kinds of scholar", body: "The seeker of leadership is himself ruined, though others may be set right through him, if he calls people to leave the world. That is someone who looks outwardly like the early scholars but secretly wants status. He is like a candle that burns itself up while others take light from it; their good lies in his ruin. If he calls people to seek the world, he is like a burning fire that eats itself and others. So there are three kinds of scholar. One ruins himself and others: those who openly seek the world and turn to it. One brings happiness to himself and others: those who call people to God outwardly and inwardly. One ruins himself and brings happiness to others: he calls to the next life and has outwardly rejected the world, but inwardly wants people's approval and status. See which kind you are, and whom you are preparing for. Do not think God accepts any knowledge or deed not purely for Him." },
    ],
    closer: [
      { title: "The candle", body: "The candle is Ghazali's hardest image for a scholar. Others really do see by its light. The candle is still burning away." },
      { title: "Knowledge does not leave you alone", body: "“It ruins him forever or gives him life forever.” There is no neutral way to carry knowledge. That is why the next chapter begins with the student's purity." },
    ],
    distinction: ["Two sins compared", "Wine", "Seems small, and opens the door to the body's great sins: adultery, slander, murder, theft.", "Debate for winning", "Seems small, and opens the door to the heart's great sins: envy, pride, spite, showing off."],
    misreading: "Ghazali does not say anyone who disagrees or asks a hard question is sinning. The target is debate aimed at winning, silencing and being seen. He also admits the best debaters struggle against these traits.",
    reflection: "Pick one of the ten traits. When did you last feel it while arguing?",
    audit: ["Am I glad or sorry when a rival succeeds?", "Do I repeat people's weak arguments to shame them?", "Can I drop an argument when I am right?", "Which of the three kinds of scholar am I becoming?"],
    nodes: ["munazara", "jah", "riya"],
    model: spectrum("Three kinds of scholar", "Ghazali's closing division.", [["Ruins himself and others", "Openly seeks the world and calls others to it.", "warning"], ["Ruins himself, saves others", "The candle: calls to the next life, secretly wants status.", "warning"], ["Saves himself and others", "Calls to God outwardly and inwardly.", "support"]]),
  }),
  makeChapter({
    id: 26, shortTitle: "A clean heart first", formalTitle: "The student's first duty: purifying the self before seeking knowledge",
    overview: "The student's first duty is to clean himself of bad traits. Knowledge is the worship of the heart, and it is not valid in a dirty heart, as prayer is not valid in a dirty body. Ghazali reads the report about angels and dogs as a hint about the heart.",
    thesis: "The heart is a house where angels stay, and bad traits are barking dogs. The light of knowledge comes only through angels, so a heart full of dogs does not receive it. People who learn much with bad character have the words of knowledge, not its reality.",
    moves: [
      { title: "Like purity for prayer", body: "The student's outward manners and duties are many, but they come together in ten. The first is to put cleaning the self of low traits and blamed qualities first. Knowledge is the worship of the heart, the prayer of the inner self, and the inner way of drawing near to God. Prayer, the duty of the outer limbs, is only valid if the outside is cleaned of impurity and filth. In the same way, the inner worship of filling the heart with knowledge is only valid once the heart is cleaned of foul traits and dirty qualities." },
      { title: "Unclean inside", body: "The Prophet said: “The religion is built on cleanliness.” That is true inside and out. God says: “The idolaters are unclean.” This alerts minds that cleanness and uncleanness are not only what the senses see outside. An idolater may have clean clothes and a washed body, but be unclean in his substance, meaning his inside is smeared with filth. Uncleanness means what is to be avoided and kept far away. The foul qualities inside matter more to avoid, since they are foul now and ruinous later." },
      { title: "Dogs in the house", body: "That is why the Prophet said: “Angels do not enter a house with a dog in it.” The heart is a house. It is where angels stay, where their influence comes down and where they settle. Bad qualities, like anger, lust, spite, envy, pride and self-admiration, are barking dogs. How will angels come in when it is full of dogs? God puts the light of knowledge in the heart only through angels. He says: “It is not for any human that God should speak to him except by revelation, from behind a veil, or by sending a messenger.” So too the mercy of knowledge sent to hearts is carried by the angels in charge of it. They are holy and clean, free of blamed qualities. They look only at what is good, and fill only what is good and clean from the treasuries of God's mercy." },
      { title: "A hint, not a replacement", body: "Ghazali does not say the word “house” means the heart, and “dog” means anger and blamed qualities. He says it is a hint towards them. There is a difference between turning outward words into inner meanings, and being alerted to inner meanings by the outward words while keeping the outward. That fine point separates him from the Batinis. This is the way of taking a lesson, the path of scholars and the righteous. Taking a lesson means crossing from what is mentioned to something else, not stopping at it. A sensible person sees someone else's disaster and crosses from it to noticing that he too is open to disasters, and that the world is always turning over. So cross, Ghazali says, from the house people build to the heart, a house God built. Cross from the dog, blamed for its nature and not its shape, to the dog-like spirit, which is savagery." },
      { title: "Raised in the shape of the meaning", body: "Picture a heart full of anger and greed for the world, snapping after it and eager to tear at people's honour. It is a dog in meaning and a heart only in form. The light of insight looks at meanings, not forms. In this world forms rule over meanings, and meanings lie hidden inside them. In the next life forms follow meanings, and meanings rule. So each person is raised in the shape of his meaning. Whoever tore at people's honour is raised as a savage dog. Whoever was greedy for their money, as a prowling wolf. Whoever was proud over them, in the shape of a leopard. Whoever sought leadership, in the shape of a lion. Reports say so, and people of insight see it." },
      { title: "Poison you know is poison", body: "You may say: how many students with bad character have gained the sciences! Ghazali answers: how far they are from the real knowledge that helps in the next life and brings happiness. One of the first things that knowledge shows is that sins are deadly poisons. Have you ever seen someone take poison knowing it is deadly? What you hear from such people is talk they string together with their tongues and repeat in their hearts. That is not knowledge at all. Ibn Mas'ud said: “Knowledge is not a lot of reporting. Knowledge is a light thrown into the heart.” Someone said: “Knowledge is only fear of God,” because of the verse “Only those of His servants who know truly fear God.” He pointed to knowledge's most special fruit." },
      { title: "Knowledge refused them", body: "One of the careful scholars explained the saying “We learned knowledge for other than God, and knowledge refused to be except for God.” He said it means knowledge refused itself to us. Its reality was not opened to us; we only got its words and phrases. You may say: some leading lawyers stood out in law and its principles and were counted great, yet their character was blamed. Ghazali answers: first learn the levels of the sciences and the knowledge of the next life. Then you will see that what they were busy with is of little worth as knowledge. Its worth is only as an act done for God, if they meant it to bring them near to Him." },
    ],
    closer: [
      { title: "Not a warm-up", body: "Ghazali's comparison is exact. Cleaning the heart is not like stretching before exercise, which merely helps. It is like purity for prayer: without it there is no valid worship at all." },
      { title: "Keeping the outward", body: "The house and the dog are real. Ghazali insists on it. The report is about real houses and dogs, and it also points to the heart. That is the line between taking a lesson and throwing away the plain meaning." },
    ],
    distinction: ["Two ways to read the report about dogs", "Taking a lesson", "Keeping the plain meaning, and crossing from it to the heart: the scholars' way.", "Replacing the meaning", "Saying the house simply means the heart: the Batinis' way, which Ghazali rejects."],
    misreading: "Ghazali does not say a sinner cannot learn facts. He says the facts will stay on the tongue. The light that makes knowledge real, and brings fear of God, needs a clean house.",
    reflection: "If the angels looked into your heart today, which barking dog would they hear first?",
    audit: ["Which foul trait would keep the angels out of my heart?", "Do I know sins are poison, or only say so?", "Would I be raised as a dog, a wolf, a leopard or a lion?", "Does my learning make me fear God more?"],
    nodes: ["adab", "taharat", "qalb"],
    model: pair("The house and its guests", "The student's first duty.", [["Angels", "Carry the light of knowledge; enter only a clean heart.", "support"], ["Barking dogs", "Anger, lust, spite, envy, pride: they keep the angels out.", "warning"]]),
  }),
  makeChapter({
    id: 27, shortTitle: "Few ties, and a teacher trusted", formalTitle: "The student's second to fourth duties: fewer attachments, humility before the teacher, and staying out of disagreements at first",
    overview: "The student should cut down his attachments, since a divided mind is like a stream that dries up before it reaches the field. He should hand the reins to his teacher as a patient to a doctor, as Moses was told by al-Khidr. And a beginner should keep out of the disagreements until he has mastered one way.",
    thesis: "Knowledge gives you part of itself only when you give it all of yourself. The student follows his teacher's plan even over his own view, because his guide's mistake helps him more than his own right answer. A beginner should not copy the strong in what looks like laxness, as a jug cannot take what the sea can.",
    moves: [
      { title: "A stream divided", body: "The second duty is to lessen his ties to worldly business and to go far from family and home. Ties distract and turn aside: “God has not put two hearts inside any man.” When thought is divided, it fails to grasp the truth. It has been said: “Knowledge will not give you part of itself until you give it all of yourself. Even when you give it all of yourself, it is a risk whether it will give you part.” A mind spread over scattered things is like a stream whose water is divided. The ground soaks up some and the air takes some, so nothing is left to gather and reach the field." },
      { title: "Hand over the reins", body: "The third duty is not to be proud towards knowledge or to order his teacher around. He should hand the reins to him completely, in every detail, and yield to his advice as an ignorant patient yields to a kind, skilled doctor. He should be humble to his teacher and seek reward and honour by serving him. Al-Sha'bi said: “Zayd ibn Thabit prayed at a funeral and his mule was brought for him to ride. Ibn Abbas came and held his stirrup. Zayd said: Let go, cousin of God's messenger. Ibn Abbas said: This is how we were told to treat scholars and elders. Zayd kissed his hand and said: This is how we were told to treat the family of our Prophet.” The Prophet said: “Flattery is not part of a believer's character, except in seeking knowledge.”" },
      { title: "Only from famous teachers", body: "Part of a student's pride towards the teacher is refusing to learn except from famous, admired people. That is foolishness itself. Knowledge is the means to salvation and happiness. Someone running from a savage beast does not care whether a famous man or an unknown one shows him the way out. The beasts of the Fire are fiercer to those ignorant of God than any beast. Wisdom is the believer's lost property; he takes it wherever he finds it and is grateful to whoever brings it. As the verse says: “Knowledge is at war with the lofty young man, as a flood is at war with high ground.”" },
      { title: "Like soft earth in rain", body: "Knowledge is only gained by humility and lending an ear. God says: “In that is a reminder for whoever has a heart, or lends an ear while present.” Having a heart means being able to take in knowledge. Then that ability does not help him until he lends an ear, present in heart, taking in everything given with good listening, humility, gratitude, joy and thanks. The student should be to his teacher like soft earth that gets heavy rain: every part of it drinks, and it yields wholly to take it in." },
      { title: "Al-Khidr's condition", body: "When the teacher points him to a way of learning, he should follow it and leave his own view. His guide's mistake helps him more than his own right answer, since experience shows fine points that sound strange but help greatly. A doctor may treat a fevered patient with heat for a while, to build his strength to bear the shock of the cure. Someone without experience is amazed. God pointed to this in the story of al-Khidr and Moses. Al-Khidr said: “You will not be able to bear with me. How can you bear what you have no knowledge of?” He set the condition of silence and acceptance: “If you follow me, do not ask me about anything until I mention it to you.” Moses did not bear it, and kept questioning him, until it became the cause of their parting. Any student who keeps his own view and choice over his teacher's will fail and lose." },
      { title: "When to ask", body: "You may say: God said “Ask the people of remembrance if you do not know,” so asking is commanded. It is, Ghazali answers, but in what the teacher allows. Asking about what your level cannot yet understand is blamed. That is why al-Khidr kept Moses from asking: do not ask before the time. The teacher knows best what you are fit for, and when to uncover it. Until the time of uncovering comes at each step of the climb, the time to ask about it has not come." },
      { title: "Ali's rights of the scholar", body: "Ali said: “Part of the scholar's right is that you do not ask him too much, or press him in his answer. Do not insist when he is tired, or hold his clothes when he gets up. Do not spread his secret or backbite anyone in his presence. Do not look for his slip, and if he slips, accept his excuse. You must respect and honour him for God, as long as he keeps God's command. Do not sit in front of him. If he needs something, be the first to serve him.”" },
      { title: "Fourth: not the disagreements yet", body: "The fourth duty is that a beginner should guard against listening to people's disagreements, whether in worldly or next-life sciences. That stuns his mind, confuses his thinking, weakens his judgment and makes him despair of understanding. He should first master the one praised way his teacher approves, and then listen to the other schools and doubts. If his teacher does not choose one view but only reports schools and what was said, he should beware of him. He misleads more than he guides. The blind are not fit to lead the blind." },
      { title: "The coward and the brave", body: "Keeping a beginner from doubts is like keeping a new Muslim from mixing with unbelievers. Encouraging the strong to look into disagreements is like encouraging the strong to mix with them. So the coward is kept back from charging the enemy lines, and the brave man is sent. Some weak people, missing this fine point, think they may copy the strong in the easy things reported of them. They do not realise that the duties of the strong differ from those of the weak." },
      { title: "A heretic at the end", body: "Someone said: “Whoever saw me at the start became a truthful saint. Whoever saw me at the end became a heretic.” At the end, deeds turn inward and the limbs grow still except for the fixed obligatory duties. To onlookers it looks like idleness, laziness and neglect. It is not. It is the heart standing guard in presence and witnessing, and keeping up remembrance, the best of deeds, without a break." },
      { title: "The sea and the jug", body: "Sometimes the weak copy the strong in what looks outwardly like a slip. That is like someone who drops a little filth in a jug of water. He says: “Many times this much falls in the sea, and the sea is bigger than the jug. What is allowed for the sea is even more allowed for the jug.” The poor man does not realise that the sea by its strength turns the filth to water, so the filth itself changes to its nature. A little filth overpowers the jug and turns it to its own nature. For this reason the Prophet was allowed what others were not, even nine wives. He had the strength for justice to reach all his wives, however many. Others cannot manage even some justice; the harm between wives reaches them instead, until they disobey God to please them. Whoever measures angels against blacksmiths does not succeed." },
    ],
    closer: [
      { title: "Your guide's mistake", body: "“His guide's mistake helps him more than his own right answer.” This is the hardest line in the chapter. It is about learning a path, not about truth and falsehood in general. On the road, a guide who knows the terrain beats a traveller who guesses right once." },
      { title: "Why the strong get more room", body: "The sea and the jug are Ghazali's answer to anyone who copies a great man's ease. What is safe for the strong can overwhelm the weak." },
    ],
    distinction: ["Two things a student could want", "Ask now", "Question everything as it comes, as Moses did with al-Khidr.", "Ask in time", "Follow the teacher's plan and ask when your level can take the answer."],
    misreading: "Ghazali does not tell students to obey a teacher in sin. Ali's list ends with “as long as he keeps God's command.” The surrender is about the method of learning, not about the law.",
    reflection: "How many things are pulling your attention this week? Picture your mind as a stream split into that many channels.",
    audit: ["Am I giving knowledge all of myself?", "Do I refuse to learn from unknown people?", "Do I ask questions before I am ready for the answers?", "Do I copy great people's ease without their strength?"],
    nodes: ["adab", "muta", "ilaiq"],
    model: chain("Duties two to four", "What the student brings to the teacher.", [["Few ties", "A mind undivided, like a stream kept in one channel.", "support"], ["Humility", "Soft earth in heavy rain; the teacher's plan over one's own view.", "support"], ["Timing", "Ask when your level is ready, as al-Khidr told Moses.", "balance"], ["One way first", "Master one approved way before the disagreements.", "balance"]]),
  }),
  makeChapter({
    id: 28, shortTitle: "A taste of each, in order", formalTitle: "The student's fifth to eighth duties: look into every praised science, go in order, finish each step, and know how sciences are ranked",
    overview: "The student should look into every praised science enough to see its aim, then go deep in the most important. He takes them in order, not all at once, and the noblest is knowledge of God. He does not judge a science by its practitioners' mistakes, and he weighs sciences by their fruit and the strength of their proof.",
    thesis: "All sciences serve the road to God, like guards at the frontier posts. Life is too short for all of them. So take a taste of each and give your strength to the knowledge of the next life, whose goal is knowing God. Know the truth first, then its people; and weigh sciences by what they give and how firmly they are proven.",
    moves: [
      { title: "Fifth: a look at every science", body: "The fifth duty is not to leave any praised science, or any branch of one, without looking into it enough to see its aim and goal. Then, if life allows, he goes deep into it. If not, he takes up the most important, completes it, and takes a little of the rest. The sciences help each other and are tied together. And he gains at once freedom from being hostile to a science because he does not know it. People are enemies of what they do not know. God says: “Since they are not guided by it, they will say: this is an old lie.” A poet said: “Whoever has a bitter, sick mouth finds even sweet water bitter.”" },
      { title: "Guards at the frontiers", body: "The sciences, at their levels, either take a person on the road to God or help with the journey in some way. They have levels nearer to and further from the goal. Those who keep them are like guards of the frontier posts and forts. Each has his level, and a reward in the next life by his degree, if he aims at God." },
      { title: "Sixth: in order, a taste of each", body: "The sixth duty is not to plunge into a science all at once, but to keep the order and start with the most important. Life usually does not stretch to all the sciences. So it is wise to take the best of each and be content with a taste. Then spend the rest of his strength on completing the noblest science, the knowledge of the next life. That means both its parts, practice and unveiling. The goal of practice is unveiling, and the goal of unveiling is knowing God." },
      { title: "Not the ordinary person's belief", body: "By knowing God Ghazali does not mean the belief an ordinary person picks up by inheritance. Nor does he mean the theologian's way of setting out arguments and guarding his words from opponents' tricks. He means a kind of certainty, the fruit of a light God throws into the heart of someone whose inside has been cleaned of filth by striving. It can reach the level of Abu Bakr's faith, which, as the Prophet said, would outweigh the faith of all the worlds if weighed against it. What the ordinary person believes, and the theologian arranges, is not that. Umar, Uthman, Ali and the other Companions were not short of it, yet Abu Bakr surpassed them by the secret settled in his heart." },
      { title: "Where the capital is lost", body: "It is strange that someone hears such words from the Prophet and then scorns what he hears that agrees with them, calling it Sufi nonsense and beyond reason. Take care here, Ghazali says, for here the capital is lost. Be eager to learn that secret, which is outside the lawyers' and theologians' stock. Only your own eagerness in seeking will guide you to it. The noblest science and its goal is knowing God. It is an ocean whose depth is never reached. The highest human level in it is that of the prophets, then the friends of God, then those who follow them." },
      { title: "Two sages' notes", body: "It is said that pictures of two ancient sages were seen in a mosque. One held a note: “You may do everything well. Do not think you have done anything well until you know God, and understand that He is the Cause of causes and the Maker of things.” The other held a note: “Before I knew God I drank and was thirsty. When I knew Him, I was quenched without drinking.”" },
      { title: "Seventh: finish each step", body: "The seventh duty is not to plunge into a science until he has completed the one before. The sciences are in a necessary order; some are the road to others. The one given success keeps that order and those steps. God says: “Those We gave the Book recite it as it should be recited.” That is, they do not pass a science until they have mastered it in knowledge and action. In each science, his aim should be to climb to what lies above it." },
      { title: "Do not judge a science by its people", body: "He should not judge a science false because its practitioners disagree, or because one or a few of them erred, or because they do not act on it. Some people left the study of rational and legal sciences, saying: “If they had any basis, their masters would have grasped it.” Ghazali answered this in his Standard of Knowledge. Some think medicine false because they saw a doctor's mistake. Some think astrology true because one astrologer happened to be right, and others think it false because another was wrong. All are mistaken. A thing must be known in itself, and not every science can be mastered by every person. That is why Ali said: “Do not know the truth by men. Know the truth, and you will know its people.”" },
      { title: "Eighth: two measures of nobility", body: "The eighth duty is to know how the nobility of sciences is judged. It means two things: the nobility of the fruit, and the strength and firmness of the proof. Take the science of religion and medicine: the fruit of one is lasting life, and of the other passing life, so religion is nobler. Take arithmetic and astrology: arithmetic is nobler because its proofs are firm and strong. Compare arithmetic with medicine: medicine is nobler by its fruit, arithmetic by its proofs. The fruit counts for more, so medicine is nobler, though much of it is guesswork. So the noblest science is knowledge of God, His angels, His Books and His messengers, and of the road that leads to these. Want nothing else, and be eager for nothing else." },
    ],
    closer: [
      { title: "Freedom from hostility", body: "A taste of every science has a benefit Ghazali names at once: you stop being an enemy of what you do not know. The sick mouth that finds sweet water bitter is the cure's target." },
      { title: "Quenched without drinking", body: "The second sage's note is the chapter's goal in one line. Knowing God is not more to carry. It ends the thirst." },
    ],
    distinction: ["Two measures of a science", "Its fruit", "What it gives: lasting life or passing life. This counts for more.", "Its proof", "How firm its evidence is: arithmetic beats astrology, and even medicine, here."],
    misreading: "“A taste of each” is not permission to stay shallow in everything. Ghazali pairs it with going deep in the most important, and with finishing each step before the next.",
    reflection: "Name a science you look down on. Have you ever looked into it enough to see what it is for?",
    audit: ["Which science am I hostile to only because I do not know it?", "Have I finished the step before the one I am on?", "Do I judge a subject by its worst practitioners?", "Is my deepest effort going to the noblest knowledge?"],
    nodes: ["adab", "tartib", "marifa"],
    model: pair("Two measures, one ranking", "The eighth duty.", [["Fruit", "Religion over medicine; medicine over arithmetic. This weighs more.", "support"], ["Proof", "Arithmetic over astrology, and over medicine too.", "balance"]]),
  }),
  makeChapter({
    id: 29, shortTitle: "What study is for", formalTitle: "The student's ninth and tenth duties: the right aim, and the three kinds of knowledge on the road to God",
    overview: "The student's aim should be to adorn his inner self now and to come near God later, not leadership or money. That does not mean looking down on law or grammar. Ghazali then maps all knowledge onto a pilgrim road: getting the camel ready, crossing the desert, and the pilgrimage itself.",
    thesis: "All who serve knowledge for God are like the fighters and helpers at the frontier; each has a reward. What matters most is what lasts forever. Medicine and law prepare the mount, which is the body. Cleaning the heart crosses the desert. Knowing God is the pilgrimage itself, where the real winning is.",
    moves: [
      { title: "Ninth: the aim", body: "The ninth duty is that the student's aim now should be to adorn his inside and make it beautiful with virtue. Later his aim is to come near God and rise to the company of the highest assembly of angels and those brought near. He should not aim at leadership, money, status, arguing with fools or showing off to equals. If this is his aim, he will surely seek what is nearest to it, which is the knowledge of the next life." },
      { title: "Do not scorn the other sciences", body: "Even so, he should not look down on the other sciences. These include verdicts, grammar and language tied to the Book and the Sunna, and the other preliminaries and completions that are communal duties. Do not take Ghazali's high praise of the knowledge of the next life as running these down. Those who take charge of sciences are like those who hold the frontier posts, and the fighters in God's cause. Some fight, some back them up, some bring them water, some guard and tend their animals. None is without reward, if his aim is to raise God's word and not to take spoils. So with scholars: “God will raise those of you who believe and those given knowledge by degrees.” “They are of different degrees with God.”" },
      { title: "Money-changers and sweepers", body: "Merit is relative. Looking down on money-changers compared with kings does not mean they are low compared with street sweepers. Do not think that whatever is below the highest level is worthless. The highest level is the prophets', then the friends of God, then the scholars firm in knowledge, then the righteous, at their different degrees. In short: “Whoever does an atom's weight of good will see it, and whoever does an atom's weight of evil will see it.” Whoever aims at God by any knowledge, it will help him and raise him." },
      { title: "Tenth: what matters to you", body: "The tenth duty is to know how each science relates to the goal. Then he prefers the high and near to the far, and the important to the rest. What is important is what concerns you, and nothing concerns you except your state in this world and the next. You cannot have both the world's pleasures and the next life's bliss, as the Quran says and the light of insight shows as clearly as sight. So the most important is what lasts forever. Then the world becomes a stopping place, the body a mount, and deeds a journey towards the goal. There is no goal but meeting God. All bliss is in it, though few in this world know its worth." },
      { title: "The slave and the pilgrimage", body: "Compared with the happiness of meeting God and looking at His noble face, the sciences have three levels. Ghazali means the looking the prophets asked for and understood, not what ordinary people or theologians first imagine. He gives an example. A slave is told his freedom and a kingdom depend on the pilgrimage. If he goes and completes it, he gets both freedom and the kingdom. Suppose he starts on the road and prepares, and something he cannot help stops him on the way. Then he gets freedom and release from slavery only, without the kingdom. He has three kinds of work. First, preparing: buying the camel, stitching the water-skin, getting provisions and a mount. Second, travelling: leaving home and heading for the Kaaba, stage by stage. Third, doing the rites of pilgrimage one by one. After finishing, leaving the pilgrim's state and making the farewell circuit, he has earned the kingdom." },
      { title: "Three kinds of knowledge", body: "Someone who has begun the rites is not as far from happiness as someone still preparing, or someone who has begun the journey; he is nearer. So knowledge is also of three kinds. One is like preparing provisions and buying the camel: medicine, law and what concerns the body's good in this world. One is like crossing the deserts and climbing the passes. That is cleaning the inside of dark qualities and climbing those high passes that defeated earlier and later people, except the ones given success. Learning about it is like learning the directions and stages of the road. Knowing the stages is no use without travelling them, and knowing how to refine character is no use without doing it. But doing it without knowing is impossible. The third is like the pilgrimage itself: knowing God, His qualities, His angels, His acts, and all that was listed under unveiling." },
      { title: "Saved, or winning", body: "Here are salvation and winning. Salvation comes to every traveller on the road whose aim is the true goal: safety. Winning happiness comes only to those who know God, those brought near, who enjoy in God's neighbourhood rest, fragrance and a garden of bliss. Those held back from the peak of perfection have salvation and safety. God says: “If he is one of those brought near, then rest, fragrance and a garden of bliss. If he is one of the people of the right, then peace to you from the people of the right.” Some did not turn to the goal or set out for it. Some set out towards it, not to obey and serve, but for some quick gain. They are of the people of the left and the lost: “a welcome of boiling water and burning in Hell.”" },
      { title: "Seen, not only heard", body: "This is the certain truth for the scholars firm in knowledge. They grasped it by an inner witnessing stronger and clearer than seeing with the eyes. They rose above simply accepting what they heard. Their state is that of someone told who believed, then saw and made sure. Others' state is that of someone who accepted with good faith and belief but was not given the seeing. So happiness lies beyond the knowledge of unveiling. Unveiling lies beyond the knowledge of practice, which is travelling the road to the next life and crossing the passes of bad qualities. Travelling the road of wiping out blamed qualities lies beyond knowing those qualities and the way to cure them. And that lies beyond knowing the body's health and the means to it." },
      { title: "The body is the camel", body: "The body's health depends on people coming together and helping each other to get clothing, food and shelter. That depends on the ruler and his law, which keeps people on the path of justice; and governing is in the lawyer's hands. The means of health are in the doctor's hands. Someone said: “There are two sciences, the science of bodies and the science of religions.” If he meant law by the second, he meant the common outward sciences, not the rare inner ones. Why liken medicine and law to preparing provisions? Because what travels to God to reach His nearness is the heart, not the body. By heart Ghazali does not mean the lump of flesh. It is one of God's secrets, which the senses do not grasp, a subtle thing sometimes called the spirit or the soul at peace. The law calls it the heart because the heart is the first mount of that secret. Through it the whole body became a mount and tool for it." },
      { title: "From God's command", body: "Uncovering that secret belongs to the knowledge of unveiling, which is guarded; there is no permission to speak of it. The most allowed is to say it is a precious jewel, rarer and nobler than the visible bodies. It is a matter from God, as He said: “They ask you about the spirit. Say: the spirit is from my Lord's command.” All creatures are related to God, but its relation is nobler than that of the body's other parts. To God belong creation and command, and command is higher than creation. This precious jewel carries God's trust, which the heavens, the earth and the mountains refused to carry and feared. That puts it above them, and it is from the world of command. Do not take this as a hint that it is eternal. Whoever says spirits are eternal is deceived and ignorant, and does not know what he is saying. Ghazali holds back here, since it is beyond his present aim." },
      { title: "Medicine and law serve the mount", body: "The point is that this subtle thing is what travels to its Lord's nearness, since it is from its Lord's command. From Him it came and to Him it returns. The body is its mount, which it rides and through which it travels. On God's road the body is to it what the camel is to the body on the pilgrim road. It is also like the water-skin is that holds the body's water. So every science aimed at the body's good serves the mount. Medicine clearly does; a person would need it even if he lived alone. Law differs: alone, a person might do without it. But he was created unable to live alone. He cannot on his own farm, sow, bake and cook for food, and get clothing, shelter and all their tools. So he has to mix with others and seek their help." },
      { title: "Balance inside and out", body: "When people mix and their desires are stirred, they pull at the means of their desires, quarrel and fight. Their fighting ruins them from outside, as the clash of the body's humours ruins them from inside. Medicine keeps the balance of the clashing humours inside. Governing and justice keep the balance of rivalry outside. Knowing how to balance the humours is medicine. Knowing how to balance people's dealings and acts is law. Both preserve the body, which is the mount. Someone may give himself to law or medicine without striving against himself or setting his heart right. He is like someone who gives himself to buying the camel, feeding it, buying the water-skin and stitching it, and never crosses the pilgrim's desert." },
      { title: "The stitching of the water-skin", body: "Someone may spend his life on the fine points of wording in legal debates. He is like someone who spends his life on the fine points of how to make the threads stitching the pilgrim's water-skin strong. Compare such people with those travelling the road of setting the heart right, which leads to unveiling. They stand to them as those others compare with the pilgrims on the road or at the rites. Think about this first, Ghazali says, and take this advice free. It cost him dearly. He reached it only after great effort and full courage to break from both ordinary and elite people and stop copying them out of mere desire. That is enough on the student's duties." },
    ],
    closer: [
      { title: "The water-skin's thread", body: "The image of a life spent on the thread for the water-skin is Ghazali's sharpest picture of the specialist. The thread matters. The pilgrim who never sets out still never reaches the Kaaba." },
      { title: "Advice that cost him", body: "Ghazali ends the student's duties with a personal note. He learned this against the grain of everyone around him, and offers it for nothing." },
    ],
    distinction: ["Two things a traveller can reach", "Salvation", "Safety, for everyone on the road with the right aim, even if held back from the peak: the people of the right.", "Winning", "Nearness and bliss in God's neighbourhood, for those who reach knowing Him: those brought near."],
    misreading: "Ghazali does not call medicine and law worthless. The camel and the water-skin are needed for the pilgrimage. He warns only against mistaking the preparations for the journey.",
    reflection: "Where are you on the pilgrim road: still buying the camel, crossing the desert, or at the rites?",
    audit: ["What is the aim of my studying, honestly?", "Do I look down on any science that serves the road?", "Am I stitching water-skins for a journey I never start?", "What concerns me that will last forever?"],
    nodes: ["niyya", "marifa", "ruh"],
    model: chain("The pilgrim road of knowledge", "Ghazali's three kinds of knowledge.", [["Preparing the camel", "Medicine and law: care of the body, the mount.", "balance"], ["Crossing the desert", "Cleaning the heart of bad traits: the road itself.", "support"], ["The pilgrimage", "Knowing God, His qualities and acts: where the winning is.", "support"], ["The reward", "Salvation for every true traveller; nearness for those who arrive.", "support"]]),
  }),
  makeChapter({
    id: 30, shortTitle: "The teacher: a father who asks nothing", formalTitle: "The teacher's duties: the four states of knowledge, and duties one to four",
    overview: "Knowledge, like wealth, has four states: gaining, keeping, using and giving. Giving is the noblest. Then Ghazali gives the teacher's duties: kindness like a father's, teaching for no pay, holding nothing back in advice, and correcting by hint rather than scolding.",
    thesis: "The teacher is a father of the lasting life, so his right is greater than a parent's. He should seek no pay or thanks, since the student lends him the field he farms for his own reward. He should warn the student off seeking status, and correct him gently and indirectly.",
    moves: [
      { title: "Four states", body: "A person's knowledge has four states, like his wealth. A rich man has a state of gaining, when he earns. A state of saving, when he has enough not to ask. A state of spending on himself, when he benefits. And a state of giving to others, when he is generous, which is the noblest. Knowledge too is gained like wealth. It has a state of seeking and gaining, and a state of having that frees from asking. It has a state of insight, which is reflecting on and enjoying what one has, and a state of giving insight to others, which is the noblest." },
      { title: "The sun and the wick", body: "Whoever learns, acts and teaches is called great in the kingdom of heaven. He is like the sun, which gives light to others and shines itself, and like musk, which scents others and is fragrant itself. Someone who knows and does not act is like a notebook that benefits others and holds no knowledge itself. He is like a whetstone that sharpens others and does not cut, or a needle that clothes others and is naked itself. He is a lamp's wick that lights others while it burns up. As the verse says: “He is only a wick that was lit; it gives people light while it burns.” Whoever takes up teaching has taken on a great matter and a heavy danger, so he must keep its manners and duties." },
      { title: "First: like a father", body: "The first duty is kindness to students, treating them like his sons. The Prophet said: “I am to you like a father to his child.” The teacher's aim is to save them from the fire of the next life, which matters more than parents saving their child from the fire of this world. So the teacher's right is greater than the parents'. The father is the cause of present existence and this passing life. The teacher is the cause of the lasting life. Without the teacher, what came from the father would drift to lasting ruin. By teacher Ghazali means the teacher of the sciences of the next life, or of worldly sciences with the next life as the aim. Teaching for the world's sake is ruin and ruining others." },
      { title: "Brothers on a journey", body: "The sons of one man should love each other and help each other in all their aims. So should the students of one teacher. They will, if their aim is the next life. If their aim is the world, there will be only envy and hatred. Scholars and the people of the next life are travellers to God, taking the road from this world, its years and months being the stages. Companionship on the road between travellers to cities breeds love. How much more the journey to the highest Garden! The happiness of the next life has no narrowness, so its people do not quarrel. The happiness of this world has no room, so it cannot be free of crowding. Those who turn knowledge into a way to leadership leave “The believers are brothers.” They enter “Friends on that day will be enemies to each other, except the mindful.”" },
      { title: "Second: no pay", body: "The second duty is to follow the Prophet: seek no pay for teaching, no reward or thanks. Teach for God and to come near Him. Do not think you have done the students a favour, though they owe you. Rather, the favour is theirs, since they prepared their hearts to come near God by your planting knowledge in them. It is like someone lending you land to farm for yourself. Your benefit is more than the owner's; how can you count it a favour to him? Your reward for teaching is greater with God than the student's, and without the student you would not get it. So seek pay only from God. As Noah said: “My people, I ask you no money for it. My reward is only with God.”" },
      { title: "Wiping the face with the shoe", body: "Money and what is in the world serve the body. The body is the soul's mount. What is served is knowledge, since by it the soul is honoured. Whoever seeks money by knowledge is like someone who wipes the underside of his shoe with his face to clean it. He has turned the master into the slave and the slave into the master. That is being turned upside down on one's head. Such a person will stand at the great presentation with the guilty, “hanging their heads before their Lord.”" },
      { title: "Teachers who expect service", body: "In short, the favour belongs to the teacher. Yet see what religion has come to: people claiming their aim is nearness to God by law, theology and teaching them. They spend money and status and bear every humiliation serving rulers to get stipends. If they left that, they would be left alone and no one would come to them. Then the teacher expects the student to stand by him in every trouble, and support his friends and oppose his enemies. He expects him to run his errands openly and be at his service in his wants. If the student falls short, he turns on him and becomes his worst enemy. How low is a scholar who accepts this place and is happy with it! He is not ashamed to say: “My aim in teaching is to spread knowledge to come near God and help His religion.” Look at the signs and you will see the kinds of self-deception." },
      { title: "Third: hold back no advice", body: "The third duty is to hold back no advice from the student. Stop him reaching for a level before he deserves it, and from busying himself with hidden knowledge before finishing the clear. Then alert him that the aim of seeking knowledge is nearness to God, not leadership, show or rivalry. Show him how ugly that is as strongly as possible. What a wicked scholar sets right is not more than what he spoils." },
      { title: "The grain round the trap", body: "If the teacher knows the student seeks knowledge only for the world, he should look at what he seeks. If it is disputed questions in law, debate in theology, and verdicts on quarrels and judgments, he should stop him. Those are not sciences of the next life. Nor are they the ones of which it was said: “We learned knowledge for other than God, and knowledge refused to be except for God.” That saying is about Quran commentary, reports, and what the early Muslims studied of the next life and the self's character and its training. If a student learns these seeking the world, it is fine to allow it. It gives him hope of preaching and followers, but he may wake up along the way or at the end. These sciences hold what makes one fear God, look down on the world and honour the next life. He may end up right in the next life, taking the advice he gives others." },
      { title: "Love of status as bait", body: "Love of acceptance and status works like grain scattered around a trap to catch birds. God did this with His servants: He made desire so that people would continue their line. He also created love of status to be a cause of reviving the sciences. That can be hoped for in these sciences. But take pure disputed questions, theological debates, and knowing strange legal branches, given oneself to while neglecting the rest. They add only hardness of heart, heedlessness of God, going further astray and seeking status. That is, unless God rescues him with His mercy, or he mixes other religious sciences with it. There is no proof of this like experience and observation. Look and see it in people and lands. Sufyan al-Thawri was seen sad and asked why. He said: “We have become a trading post for worldly people. One of them sticks to us until he has learned, then he is made a judge, a governor or a steward.”" },
      { title: "Fourth: correct by hint", body: "The fourth duty is one of the fine points of teaching. It is to warn the student off bad character by hinting as far as possible, not openly, and with mercy, not scolding. Open rebuke tears the veil of respect, makes him bold to disobey, and stirs him to persist. The Prophet, the guide of every teacher, said: “If people were forbidden to crumble dung, they would crumble it. They would say: we were only forbidden because there is something in it.” The story of Adam and Eve and what they were forbidden alerts you to this. It was not told to you as an evening tale, but to take a lesson. A hint also draws fine souls and sharp minds to work out its meaning. The joy of catching the meaning makes them want to learn it, to show it did not escape them." },
    ],
    closer: [
      { title: "The sun and the wick", body: "Every picture Ghazali uses admits that others really are helped. The notebook informs, the whetstone sharpens, the wick lights the room. That is why it is a warning and not a dismissal: the teacher who does not act is useful, and burning." },
      { title: "Whose favour it is", body: "The land-lender image flips the usual feeling. The student is not in the teacher's debt; the teacher farms the student's heart for his own reward." },
    ],
    distinction: ["Two things a teacher can be", "The sun", "Lights others and shines itself: learns, acts and teaches.", "The wick", "Lights others while it burns away: teaches without acting."],
    misreading: "Letting a worldly student study commentary and reports is not approval of his motive. Ghazali allows it because those sciences carry their own cure, the fear of God, and may wake him. He forbids the disputes that only harden the heart.",
    reflection: "Think of someone who taught you something that lasted. Have you thanked them, or did you think they owed you?",
    audit: ["Do I teach for thanks or for God?", "Do I expect those I help to serve me?", "Do I correct people openly when a hint would do?", "Am I the sun or the wick?"],
    nodes: ["muallim", "adab", "shafaqa"],
    model: spectrum("Four states of knowledge", "Like wealth, from gaining to giving.", [["Gaining", "Seeking and earning it.", "balance"], ["Keeping", "Having enough not to ask.", "balance"], ["Insight", "Reflecting on it and enjoying it.", "support"], ["Giving insight", "Teaching: the noblest state.", "support"]]),
  }),
  makeChapter({
    id: 31, shortTitle: "The teacher's last four duties", formalTitle: "The teacher's duties five to eight: not belittling other sciences, teaching to each one's level, plain truths for the weak, and acting first",
    overview: "A teacher of one science should not run down the others. He speaks to each student at his level, keeping deep things from those not fit for them. He gives the weak the plain truths and does not unsettle ordinary believers. And he must act on what he teaches, since people see deeds more than they grasp knowledge.",
    thesis: "Pearls are not hung on swine, and wisdom is not given to those who will spoil it; but keeping it from those fit for it is also wrong. Ordinary people should be taught worship, honesty in their trades, and hope and fear of the Garden and the Fire, not doubts. The teacher is the seal and the student the clay: a seal with no engraving leaves no mark.",
    moves: [
      { title: "Fifth: do not run down other sciences", body: "Someone in charge of one science should not make the sciences beyond it look ugly to the student. The language teacher tends to run down law. The law teacher tends to run down reports and commentary, calling them mere transmission and hearing, old women's work, with no role for reason. The theology teacher turns students off law, saying: “That is branches; it is talk about women's periods. What is that beside talk of the Merciful's qualities?” These are blamed habits in teachers, to be avoided. Someone in charge of one science should widen the student's way to learn others. If he teaches several, he should lead the student up step by step." },
      { title: "Sixth: to each his level", body: "The sixth duty is to keep to the student's level of understanding. He should not give him what his mind cannot reach, which would drive him away or muddle his mind. He follows the Prophet, who said: “We prophets were commanded to put people in their places, and speak to them by the measure of their minds.” He should share the truth when he knows the student can grasp it. The Prophet said: “No one tells people something their minds cannot reach without it becoming a trial for some of them.” Ali pointed to his chest and said: “Here are many sciences, if only I found people to carry them.” He was right. The hearts of the righteous are the graves of secrets." },
      { title: "Pearls and swine", body: "A scholar should not spread everything he knows to everyone. That is so even when the student understands it but is not fit to benefit from it; how much more when he does not understand it. Jesus said: “Do not hang jewels on the necks of swine. Wisdom is better than jewels, and whoever hates it is worse than swine.” So it was said: “Measure for each person by the measure of his mind, and weigh for him on the scale of his understanding. Then you are safe from him and he benefits from you. Otherwise he will reject it, because the measures differ.”" },
      { title: "The scholar who took off the bridle", body: "A scholar was asked something and did not answer. The questioner said: “Did you not hear the Prophet say: whoever hides useful knowledge will come on the Day of Resurrection bridled with a bridle of fire?” He said: “Leave the bridle and go. If someone who understands comes and I hide it from him, let him bridle me.” God said: “Do not give the foolish your wealth.” This alerts us that keeping knowledge from someone who would spoil it and be harmed by it is even more fitting. Wronging by giving to the undeserving is no less than wronging by keeping from the deserving. A poet said: shall I scatter pearls among grazing cattle? They do not know their worth. If God is kind and I find people fit for knowledge and wisdom, I will share what helps and gain their friendship. If not, it stays stored with me. Whoever gives knowledge to the ignorant wastes it, and whoever keeps it from the deserving does wrong." },
      { title: "Seventh: the plain truth for the weak", body: "The seventh duty is that a student of limited ability should be given the clear things that suit him. The teacher should not mention that there are fine points beyond this that he is keeping back. That weakens his desire for the clear, unsettles his heart, and makes him think the teacher is being stingy. Everyone thinks he is fit for every fine science. There is no one who is not pleased with God about how complete his own mind is. The most foolish and weakest-minded are the most pleased with their minds." },
      { title: "Leave the ordinary believer be", body: "Take an ordinary person who keeps to the law and firmly holds the beliefs handed down from the early Muslims. He does not liken God to creatures or reinterpret, his inner life is good, and his mind can take no more. His belief should not be unsettled. He should be left to his trade. Suppose the reinterpretations of the plain texts were told to him. The ordinary person's restraint would come loose from him, and the restraint of learned inquiry would not hold him. The barrier between him and sins would lift, and he would turn into a rebel devil ruining himself and others." },
      { title: "What to teach ordinary people", body: "The fine truths of the sciences should not be gone into with ordinary people. Teach them worship, and honesty in the trades they work at. Fill their hearts with longing for the Garden and fear of the Fire, as the Quran does. Do not stir up doubts in them. A doubt may catch in his heart that he cannot untie, and he will be wretched and ruined. In short, the door of searching should not be opened to ordinary people. It stops the trades that keep people going and let the elite live." },
      { title: "Eighth: act on it", body: "The eighth duty is that the teacher acts on what he knows, so his deeds do not give his words the lie. Knowledge is grasped by insight and action by eyesight, and people with eyesight are more. When action goes against knowledge, it blocks right guidance. Anyone who eats something and tells people “Do not eat it, it is deadly poison” is mocked and suspected. Their eagerness for what they were forbidden grows. They say: “If it were not the best and sweetest thing, he would not keep it for himself.”" },
      { title: "The seal and the clay", body: "The guiding teacher to those he guides is like an engraving to clay, and a stick to its shadow. How can clay take a mark from a seal with no engraving? When is a shadow straight if the stick is crooked? As the verse says: “Do not forbid a trait and do the same; great shame on you if you do.” God says: “Do you command people to do good and forget yourselves?” So a scholar's sin in his sins is heavier than an ignorant man's. When he slips, many slip with him and follow him. “Whoever starts a bad practice bears its burden and the burden of all who do it.” That is why Ali said: “Two men broke my back: a scholar who shamelessly sins, and an ignorant man who makes a show of worship. The ignorant one fools people by his worship, and the scholar fools them by his sinning.”" },
    ],
    closer: [
      { title: "A shadow and a stick", body: "The eighth duty needs no argument. A crooked stick never casts a straight shadow. Students copy what they see." },
      { title: "Why ordinary people are left alone", body: "Ghazali's reason is not contempt. It is protection. A sound, simple faith is a barrier against sin; loosening it without replacing it leaves a person with neither." },
    ],
    distinction: ["Two ways to wrong wisdom", "Giving it to those not fit for it", "Pearls on swine: it is wasted, and it harms them.", "Keeping it from those fit for it", "Also a wrong: “Whoever keeps it from its people does wrong.”"],
    misreading: "Keeping deep matters from ordinary people is not hiding the religion. The duties of worship, honesty, and the Garden and the Fire are all to be taught openly. What is held back is doubt and fine argument that would unsettle them.",
    reflection: "Think of a habit you tell others to drop. Do they see you doing it?",
    audit: ["Do I run down subjects I do not teach?", "Do I speak to people at their level?", "Have I unsettled someone's simple faith by showing off?", "Is my stick crooked?"],
    nodes: ["muallim", "adab", "amal"],
    model: chain("The teacher's last four duties", "From other sciences to his own deeds.", [["Respect other sciences", "Widen the student's way; do not scorn what you do not teach.", "support"], ["Measure by the mind", "Speak to each at his level; no pearls on swine.", "balance"], ["Protect the simple", "Plain truths for the weak; worship, honesty, hope and fear for ordinary people.", "balance"], ["Act first", "The seal must be engraved; the stick must be straight.", "support"]]),
  }),
  makeChapter({
    id: 32, shortTitle: "The danger of knowing", formalTitle: "The harms of knowledge: the warnings about bad scholars",
    overview: "Having praised knowledge, Ghazali turns to the scholars of this world, whose aim is comfort and status. The reports warn that they face the harshest punishment, and that knowledge without guidance only takes a person further from God. He gathers the reports, the sayings, and the images of the rock, the sewer and the grave.",
    thesis: "A scholar is always heading for lasting ruin or lasting happiness; once he goes into knowledge he has lost the option of simply being safe. The worldly scholar is worse off and punished more than an ignorant man, because he disobeys knowingly. He is like Balaam, who was given God's signs and clung to the earth.",
    moves: [
      { title: "Why the signs matter", body: "Ghazali has given the praise of knowledge and scholars. Severe warnings also came about bad scholars, showing they will be punished most harshly on the Day of Resurrection. So it is one of the most important things to know the signs that separate the scholars of this world from the scholars of the next. By scholars of this world he means the bad scholars, whose aim in knowledge is to enjoy the world and reach status and position among its people." },
      { title: "The reports", body: "The Prophet said: “The person most severely punished on the Day of Resurrection is a scholar whom God did not let benefit from his knowledge.” He said: “A person is not a scholar until he acts on his knowledge.” He said: “Knowledge is of two kinds. Knowledge on the tongue is God's proof against His creatures. Knowledge in the heart is the knowledge that helps.” He said: “At the end of time there will be ignorant worshippers and wicked scholars.” He said: “Do not learn knowledge to show off to scholars, argue with fools, or turn people's faces to you. Whoever does that is in the Fire.”" },
      { title: "Worse than the Antichrist", body: "The Prophet said: “I fear for you something other than the Antichrist more than the Antichrist.” Asked what, he said: “Misleading leaders.” He said: “Whoever grows in knowledge and does not grow in guidance only grows further from God.” Jesus said: “How long will you describe the road to night travellers while you stay with the lost?” These show how dangerous knowledge is. The scholar is facing either lasting ruin or lasting happiness. By going into knowledge he has lost plain safety, if he does not reach happiness." },
      { title: "The knowing hypocrite", body: "Umar said: “What I fear most for this community is the knowing hypocrite.” They asked how a hypocrite could be knowing. He said: “Knowing in the tongue, ignorant in heart and deed.” Al-Hasan said: “Do not be one who gathers scholars' knowledge and wise men's gems, and acts like a fool.” A man told Abu Hurayra: “I want to learn, but I fear I will waste it.” He said: “Leaving knowledge is enough of a waste.” Ibrahim ibn Uyayna was asked who has the longest regret. He said: “In this world, someone who does good to the ungrateful. At death, a scholar who neglected.”" },
      { title: "Four kinds of men", body: "Al-Khalil ibn Ahmad said: “Men are four. One knows and knows that he knows: he is a scholar, so follow him. One knows and does not know that he knows: he is asleep, so wake him. One does not know and knows that he does not know: he is seeking guidance, so guide him. One does not know and does not know that he does not know: he is ignorant, so leave him.” Sufyan al-Thawri said: “Knowledge calls out to action. If it answers, good; if not, knowledge leaves.” Ibn al-Mubarak said: “A person stays a scholar as long as he seeks knowledge. When he thinks he knows, he has become ignorant.”" },
      { title: "A dead heart", body: "Al-Fudayl said: “I pity three. One is the honoured man of a people who is humbled, and one the rich man of a people who becomes poor. The third is a scholar the world plays with.” Al-Hasan said: “The scholars' punishment is the death of the heart, and the heart's death is seeking the world by the deeds of the next life.” A poet said: I wonder at one who buys error with guidance, and more at one who buys his world with his religion. I wonder more still at one who sells his religion for someone else's world." },
      { title: "Circled in the Fire", body: "The Prophet said: “The scholar will be punished so severely that the people of the Fire will circle round him, amazed at his torment.” He meant the wicked scholar. Usama ibn Zayd heard him say: “A scholar will be brought on the Day of Resurrection and thrown into the Fire. His insides will spill out and he will go round with them as a donkey goes round a millstone. The people of the Fire will gather and ask: what happened to you? He will say: I used to command good and not do it, and forbid evil and do it.”" },
      { title: "Why his punishment is doubled", body: "The scholar's punishment for sin is doubled because he disobeys knowingly. God put the hypocrites “in the lowest depth of the Fire” because they denied after knowing. He made the Jews worse than the Christians, though they did not give God a son or call Him third of three. That was because they denied after knowing: “They know him as they know their own sons,” and “When what they recognised came to them, they denied it.”" },
      { title: "Balaam and the dog", body: "God tells the story of Balaam son of Beor. He says: “Tell them of the one We gave Our signs, and he cast them off, so Satan followed him and he was among the lost.” Then: “He is like a dog: if you drive it off it pants, and if you leave it, it pants.” So is the wicked scholar. Balaam was given God's Book and clung to his desires, so he was likened to a dog. Whether given wisdom or not, he pants after desires." },
      { title: "The rock in the river's mouth", body: "Jesus said: “Bad scholars are like a rock fallen in the mouth of a river. It neither drinks the water nor lets the water through to the crops. Bad scholars are like a sewer channel, plastered outside and stinking inside, and like graves, well kept outside with dead men's bones inside.” These reports show that the scholar who is a child of the world is lower and punished more than the ignorant. They show that the winners, those brought near, are the scholars of the next life. They have signs, and Ghazali now gives them." },
    ],
    closer: [
      { title: "No safe middle", body: "Once you go into knowledge, plain safety is gone. It will be either proof for you or proof against you. That is the whole reason for the signs that follow." },
      { title: "The rock", body: "Jesus's rock does two harms at once. It drinks nothing and it blocks the water from everyone else. A bad scholar fails himself, and stands in the way of others." },
    ],
    distinction: ["Two kinds of knowledge in the report", "On the tongue", "God's proof against His creatures: it testifies against its owner.", "In the heart", "The knowledge that helps."],
    misreading: "These warnings are not a reason to avoid learning. Abu Hurayra says leaving knowledge is itself a waste of it. The warnings are about learning without acting, and learning for the world.",
    reflection: "Which of al-Khalil's four men are you in the subject you care most about?",
    audit: ["Does my knowledge grow my guidance?", "Do I command what I do not do?", "Is my knowledge on my tongue or in my heart?", "Am I a rock in the river's mouth for anyone?"],
    nodes: ["ulama-akhira", "amal"],
    model: spectrum("Al-Khalil's four men", "What to do with each.", [["Knows, and knows it", "A scholar: follow him.", "support"], ["Knows, and does not know it", "Asleep: wake him.", "balance"], ["Does not know, and knows it", "Seeking guidance: guide him.", "balance"], ["Does not know, and does not know it", "Ignorant: leave him.", "warning"]]),
  }),
  makeChapter({
    id: 33, shortTitle: "Sign 1: not selling for the world", formalTitle: "The first sign: not seeking the world by knowledge, and why status is worse than money",
    overview: "The first sign of a scholar of the next life is that he does not seek the world by his knowledge. The least a scholar knows is how small the world is and how great the next life, and that the two are rivals. Giving up money is not enough, since status harms more than money.",
    thesis: "This world and the next are like two co-wives, two pans of a scale, east and west, and two cups. Whoever does not know this lacks reason, or faith, or knowledge of the prophets' laws; whoever knows it and still prefers the world is Satan's prisoner. The pleasure of teaching and guiding is the greatest worldly pleasure, and whoever gives in to it is a child of the world.",
    moves: [
      { title: "Four pictures of two worlds", body: "The least level of a scholar is to grasp how small, dirty and short-lived the world is. He grasps how great, lasting and pure the next life is, with its majestic kingdom. He knows they are opposites. They are like two co-wives: please one and you anger the other. They are like two pans of a scale: when one goes down the other goes up. They are like east and west: the nearer you get to one, the further you are from the other. They are like two cups, one full and one empty: as much as you pour into the empty one, the full one empties." },
      { title: "No reason, no faith, or no knowledge", body: "Some do not know the world's smallness, how its pleasures are mixed with pain and how its pure moments end. They have corrupt minds; seeing and experience teach it. How can someone without reason be a scholar? Whoever does not know the greatness and lastingness of the next life is an unbeliever, stripped of faith. How can he be a scholar? Some do not know the world opposes the next, and that joining them is a hopeless wish. They do not know the laws of any prophet, and denies the whole Quran. Whoever knows all this and still does not prefer the next life is Satan's prisoner, ruined by desire and overcome by misery. How can he be counted a scholar?" },
      { title: "Do not ask a drunk scholar", body: "In the reports about David, God says: “A scholar may prefer his desire to My love. The least I do to him is to deny him the sweetness of speaking to Me in prayer. David, do not ask about Me a scholar whom the world has made drunk; he will block you from the road of My love. They are highway robbers on My servants' road. David, when you see someone seeking Me, be his servant. Whoever brings back to Me one who ran away, I write him down as an expert, and whoever I write as an expert, I will never punish.” Al-Hasan said: “The scholars' punishment is the heart's death, which is seeking the world by the deeds of the next.”" },
      { title: "Thief and suspect", body: "Yahya ibn Mu'adh said: “The splendour of knowledge and wisdom goes when the world is sought by them.” Sa'id ibn al-Musayyib said: “When you see a scholar calling on rulers, he is a thief.” Umar said: “When you see a scholar who loves the world, suspect him about your religion. Every lover dives into what he loves.” Malik ibn Dinar said he read in an old book that God says: “A scholar may love the world. The least I do to him is to take the sweetness of speaking to Me out of his heart.” A man wrote to his brother: “You have been given knowledge. Do not put out its light with the darkness of sins. Otherwise you will be left in darkness on the day the people of knowledge walk by their light.”" },
      { title: "Palaces of Caesar", body: "Yahya ibn Mu'adh used to say to the scholars of the world: “People of knowledge! Your palaces are like Caesar's, your houses like Chosroes', your clothes fashionable. Your shoes are like Goliath's, your mounts like Korah's, your dishes like Pharaoh's, your sins like those before Islam, and your schools like Satan's. Where is the law of Muhammad?” A poet said: the shepherd guards the sheep from the wolf; what then if the shepherds are wolves? Another said: O reciters, salt of the town, what will salt the food if the salt goes bad? One of the knowers was asked whether someone whose delight is in sin does not know God. He said: “There is no doubt that someone who prefers the world to the next life does not know God.” That is far less than delighting in sin." },
      { title: "Status is worse than money", body: "Do not think leaving money is enough to join the scholars of the next life. Status harms more than money. So Bishr said: “‘He told us’ is one of the doors of this world. When you hear a man say ‘he told us’, he is saying: make room for me.” Bishr buried a dozen or so boxes and baskets of books. He said: “I want to teach reports. If the wish left me, I would teach.” He and others said: “If you want to teach, keep quiet. When you do not want to, teach.” The pleasure of the status of teaching and the post of guide is greater than any worldly comfort. Whoever answers his desire for it is a child of the world." },
      { title: "The test of reports", body: "Al-Thawri said: “The trial of teaching reports is harder than the trial of family, money and children.” How could its trial not be feared, when even the Prophet was told: “Had We not made you firm, you would nearly have leaned to them a little”? Sahl said: “All knowledge is the world. The next life in it is acting on it. All action is dust, except sincerity.” He said: “People are all dead except the scholars. The scholars are all drunk except those who act. Those who act are all deceived except the sincere. And the sincere is afraid until he knows how his life will end.”" },
      { title: "Leaning on the world", body: "Abu Sulayman al-Darani said: “When a man seeks reports, marries, or travels to earn a living, he has leaned on the world.” He meant seeking high chains of narration, or reports not needed for the next life. Jesus said: “How can someone be a person of knowledge whose road leads to his next life while he faces the road of his world? How can someone be a person of knowledge who seeks words to tell them, not to act on them?” Salih ibn Kaysan said: “I met the elders, and they sought refuge in God from the wicked man who knows the Sunna.”" },
      { title: "Selling God's signs", body: "Abu Hurayra reported: “Some knowledge should be sought for God's face. Whoever learns it to get some worldly gain will not find the scent of the Garden on the Day of Resurrection.” God described bad scholars as eating the world by knowledge. He said: “God took a covenant from those given the Book: you must make it clear to people and not hide it. But they threw it behind their backs and sold it for a small price.” He described scholars of the next life with humility and doing without. He said: “Among the people of the Book are some who believe in God, humble before Him, not selling God's signs for a small price. They have their reward with their Lord.” One of the early Muslims said: “Scholars are raised with the prophets, and judges with the rulers.” Every lawyer who seeks the world by his knowledge counts as a judge here." },
    ],
    closer: [
      { title: "Two cups", body: "The last of the four pictures is the most exact. There is only so much in the jug of a heart. Pour into one cup and the other empties." },
      { title: "If you want to teach, keep quiet", body: "Bishr's rule turns on desire. The wish to be the one who speaks is the danger. When it goes, teaching becomes safe." },
    ],
    distinction: ["Two worldly things a scholar may want", "Money", "Easier to see and to give up.", "Status", "The pleasure of being the guide and teacher: greater than any comfort, and harder to give up."],
    misreading: "Bishr burying his books is not a rule for everyone. It shows how seriously the early scholars took the pull of status. Ghazali's own rule is Bishr's: teach when the wish to be seen is gone.",
    reflection: "Bishr said “he told us” can mean “make room for me.” When you share what you know, what are you asking for?",
    audit: ["Do I prefer this world, knowing the next is better?", "Would I give up status as easily as money?", "Do I want to teach because I want to be heard?", "Would the Prophet recognise his law in my house?"],
    nodes: ["ulama-akhira", "jah", "zuhd"],
    model: pair("Two worlds, one heart", "Ghazali's four pictures, in two.", [["This world", "One co-wife, one pan, the east, one cup: fill it and the other empties.", "warning"], ["The next life", "Great, lasting and pure: the scholar's first knowledge is that it is better.", "support"]]),
  }),
  makeChapter({
    id: 34, shortTitle: "Sign 1: the pig and the seven levels", formalTitle: "The first sign continued: sheepskins on wolves, the man who became a pig, and seven levels of the Fire",
    overview: "Ghazali adds harder reports. Scholars who seek the world wear sheepskins over wolves' hearts. A man who lived off his closeness to Moses was turned into a pig. Mu'adh names seven kinds of scholar in seven levels of the Fire, and al-Hasan refuses a rich gift.",
    thesis: "The scholar of the next life speaks less than he listens, shares his knowledge with the poor as with the rich, and takes nothing for it. He calls people from doubt to certainty, from showing off to sincerity, from desire to doing without, from pride to humility, and from enmity to good advice.",
    moves: [
      { title: "Sheepskins", body: "Abu al-Darda reported a revelation from God to one of the prophets: “Some study law for other than religion and learn for other than action. They seek the world by the deeds of the next. Tell them: they wear sheepskins before people, with hearts like wolves. Their tongues are sweeter than honey, their hearts more bitter than aloes. Is it Me they deceive? Is it Me they mock? I will open a trial for them that will leave the patient bewildered.”" },
      { title: "Two kinds of scholar", body: "Ibn Abbas reported: “The scholars of this community are two men. One was given knowledge by God, gave it freely to people, took nothing for it and did not sell it. The birds of the sky, the fish of the water, the beasts of the earth and the noble recording angels bless him. He comes to God on the Day of Resurrection as a noble master, until he joins the messengers. The other was given knowledge and was stingy with it to God's servants, took gain for it and sold it. He comes on the Day of Resurrection bridled with fire. A caller cries over all creatures: this is so-and-so, God gave him knowledge and he was stingy with it, took gain and sold it. He is punished until people's reckoning is finished.”" },
      { title: "The man who became a pig", body: "Harder still: a man used to serve Moses. He kept saying: “Moses, God's chosen, told me; Moses, God's confidant, told me; Moses who spoke with God told me,” until he grew rich. Then Moses lost track of him and kept asking, with no news. One day a man came with a pig on a black rope. Moses asked: “Do you know so-and-so?” He said: “Yes. He is this pig.” Moses said: “Lord, I ask You to return him to his state so I can ask him how this happened.” God revealed: “If you called Me by what Adam and those after him called Me, I would not answer you in this. But I will tell you why I did it: he used to seek the world by religion.”" },
      { title: "Loving to talk more than listen", body: "Mu'adh ibn Jabal said, and in one version the Prophet: “Part of a scholar's trial is loving to speak more than to listen. Speech has polish and excess, and its speaker is not safe from error. In silence there is safety and knowledge.” Then Mu'adh named seven kinds of scholar and their places in the Fire." },
      { title: "The seven levels", body: "Some scholars store up knowledge and hate it to be found with others: they are in the first level of the Fire. Some are like a ruler in their knowledge: if something of it is answered back, or a right of theirs is slighted, they grow angry. They are in the second. Some keep their knowledge and rare reports for the noble and rich, and do not think the needy fit for it. They are in the third. Some set themselves up to give verdicts and give wrong ones, and God hates those who pretend. They are in the fourth. Some speak the words of Jews and Christians to make their knowledge seem abundant. They are in the fifth. Some take their knowledge as manliness, nobility and fame among people. They are in the sixth. Some are carried away by vanity and self-admiration: when they preach they are harsh, and when preached to they are too proud. They are in the seventh." },
      { title: "Keep silent", body: "Mu'adh went on: “So hold to silence, brother. By it you will beat Satan. Beware of laughing without wonder, or walking without purpose.” Another report says: “A person's praise may be spread to fill everything between east and west, and weigh with God no more than a gnat's wing.”" },
      { title: "Al-Hasan's refusal", body: "A man from Khurasan brought al-Hasan a bag after his gathering, with five thousand dirhams and ten garments of fine cloth. He said: “Abu Sa'id, this is for your expenses, and this is clothing.” Al-Hasan said: “God keep you well. Take back your money and clothing; we have no need of them. Whoever sits in a gathering like mine and accepts such things from people will meet God on the Day of Resurrection with no share.”" },
      { title: "From five to five", body: "Jabir reported, and in one version the Prophet: “Do not sit with every scholar. Sit only with a scholar who calls you from five to five. He calls you from doubt to certainty, and from showing off to sincerity. He calls you from desire to doing without, from pride to humility, and from enmity to good advice.” God tells of Korah coming out to his people in his finery. “Those who wanted this world's life said: if only we had what Korah was given.” “Those given knowledge said: woe to you! God's reward is better for whoever believes and does good.” So the people of knowledge were known by preferring the next life to this one." },
    ],
    closer: [
      { title: "What the pig means", body: "The man lived off repeating Moses' titles. The report is about selling nearness to someone holy. The name of the teacher had become a trade." },
      { title: "Five to five", body: "Jabir's test is one you can use tomorrow. After sitting with a scholar, ask whether you are nearer to certainty, sincerity, doing without, humility and good will, or further." },
    ],
    distinction: ["Two scholars in Ibn Abbas's report", "The generous", "Gives knowledge freely and takes nothing; everything blesses him, and he joins the messengers.", "The seller", "Is stingy with it and sells it; he comes bridled with fire and is named before all creation."],
    misreading: "Mu'adh's seven levels are not only about corrupt officials. They include things any teacher can slip into: keeping the best material for the rich, getting angry when corrected, loving to talk.",
    reflection: "Think of the last time someone corrected something you taught. Did you feel like a ruler whose right was slighted?",
    audit: ["Do I keep my best knowledge for important people?", "Do I get angry when answered back?", "Do I love to speak more than to listen?", "Does the scholar I sit with take me from five to five?"],
    nodes: ["ulama-akhira", "jah"],
    model: chain("From five to five", "What a true scholar moves you towards.", [["Doubt to certainty", "Knowledge that settles the heart.", "support"], ["Showing off to sincerity", "Deeds for God alone.", "support"], ["Desire to doing without", "The world made small.", "support"], ["Pride and enmity to humility and good advice", "Character changed, not only mind.", "support"]]),
  }),
  makeChapter({
    id: 35, shortTitle: "Sign 2: doing what he says", formalTitle: "The second sign: his deeds do not contradict his words",
    overview: "The second sign is that the scholar of the next life does not command anything until he is the first to do it. Ghazali gathers the verses, reports and sayings against saying and not doing. He adds the images of lips cut with scissors of fire, rain sliding off a rock, and the patient who describes the cure.",
    thesis: "God hates people saying what they do not do. The scholar's slip is followed by many, so he carries their burden too. Knowledge that is not acted on is no knowledge; the reward comes only with action, and Satan delays action by the excuse of learning first.",
    moves: [
      { title: "The verses", body: "The second sign is that his deeds do not contradict his words. He does not command something without being the first to do it. God says: “Do you command people to do good and forget yourselves?” And: “It is most hateful to God that you say what you do not do.” Shu'ayb said: “I do not want to do, behind your backs, what I forbid you.” God says: “Be mindful of God, and God will teach you.” And to Jesus: “Son of Mary, preach to yourself. If you take the lesson, preach to people. If not, be ashamed before Me.”" },
      { title: "Lips cut with fire", body: "The Prophet said: “On the night I was taken up, I passed people whose lips were being cut with scissors of fire. I asked: who are you? They said: we used to command good and not do it, and forbid evil and do it.” He said: “My community's ruin is a wicked scholar and an ignorant worshipper. The worst of the worst are the worst scholars, and the best of the best are the best scholars.” Al-Awza'i said the graves complained of the stench of unbelievers' bodies, and God revealed to them: “The bellies of bad scholars stink worse than what is in you.”" },
      { title: "Before the idol-worshippers", body: "Al-Fudayl said: “I have heard that wicked scholars will be dealt with on the Day of Resurrection before the idol-worshippers.” Abu al-Darda said: “Woe once to the one who does not know, and woe seven times to the one who knows and does not act.” Al-Sha'bi said: “Some people of the Garden will look down on some people of the Fire. They will say: what brought you into the Fire, when God brought us into the Garden by your teaching and training? They will say: we used to command good and not do it, and forbid evil and do it.” Hatim al-Asamm said: “No one on the Day of Resurrection has greater regret than a man who taught people knowledge. They acted on it and won, while he did not act and was ruined.”" },
      { title: "Rain on a rock", body: "Malik ibn Dinar said: “When a scholar does not act on his knowledge, his preaching slides off hearts as rain slides off a smooth rock.” A poet said: you who preach to people, you are under suspicion. You fault them for things you do yourself. You advise them hard, yet you commit the worst sins. You blame the world and those who want it, and you want it more than they do. Another said: “Do not forbid a trait and do the same; great shame on you if you do.”" },
      { title: "Turn me over", body: "Ibrahim ibn Adham said: “I passed a stone in Mecca with writing: Turn me over and take a lesson. I turned it over, and on it was written: You do not act on what you know, so why seek to know what you do not?” Ibn al-Sammak said: “How many remind of God while forgetting God, and frighten with God while bold against God! How many bring near to God while far from God, call to God while fleeing from God, and recite God's Book while shedding God's signs!” Ibrahim ibn Adham said: “We speak our words without a slip in grammar, and slip in our deeds without correcting them.” Al-Awza'i said: “When fine grammar comes, humility goes.”" },
      { title: "No reward until you act", body: "Ten Companions said they were studying in the mosque of Quba. The Prophet came out and said: “Learn what you like; God will not reward you until you act.” Jesus said: “Someone who learns and does not act is like a woman who committed adultery in secret and became pregnant. Her pregnancy showed and she was shamed. So God will shame the one who does not act on his knowledge, before all witnesses on the Day of Resurrection.”" },
      { title: "The scholar's slip", body: "Mu'adh said: “Beware the scholar's slip, because his standing with people is great and they follow him in it.” Umar said: “When the scholar slips, a whole world of people slips with him.” He said three things bring down the age, one being the scholar's slip. Ibn Mas'ud said: “A time will come when the sweetness of hearts turns salty. Neither scholar nor student will benefit from knowledge. Scholars' hearts will be like salt flats: rain falls on them and no sweetness is found. That will be when scholars' hearts lean to love of the world. Then God takes the springs of wisdom from them and puts out the lamps of guidance in their hearts. Their scholar tells you with his tongue that he fears God, while sin shows in his deeds. How fertile tongues will be then, and how barren hearts! By God, it will only be because teachers taught for other than God and students learned for other than God.”" },
      { title: "A tenth of what you know", body: "The Torah and the Gospel say: “Do not seek to know what you do not know until you act on what you know.” Hudhayfa said: “You are in a time when whoever leaves a tenth of what he knows is ruined. A time will come when whoever acts on a tenth of what he knows is saved,” because idle people will be so many. The scholar is like a judge, and the Prophet said: “Judges are three. One judges rightly, knowing: he is in the Garden. One judges unjustly, knowing or not: he is in the Fire. One judges by other than what God commanded: he is in the Fire.”" },
      { title: "Jealous like women", body: "Ka'b said: “At the end of time there will be scholars who tell people to do without the world and do not do without it. They frighten people and do not fear, and forbid visiting rulers and visit them. They prefer the world to the next life and eat by their tongues. They bring the rich near and not the poor. They are jealous over knowledge as women are jealous over men, and grow angry if their pupil sits with someone else. They are tyrants, enemies of the Merciful.”" },
      { title: "Satan's delay", body: "The Prophet said: “Satan may put you off with knowledge.” How? “He says: seek knowledge, and do not act until you know. So he keeps talking of knowledge and putting off action until he dies without acting.” Sari al-Saqati told of a man eager for outward knowledge who withdrew to worship. The man said: “I saw in a dream someone say: how long will you waste knowledge? May God waste you. I said: I am preserving it. He said: preserving knowledge is acting on it. So I stopped seeking and turned to action.”" },
      { title: "Care, not reporting", body: "Ibn Mas'ud said: “Knowledge is not much reporting. Knowledge is fear of God.” Al-Hasan said: “Learn what you like. By God, He will not reward you until you act. Fools care about reporting, scholars care about keeping.” Malik said: “Seeking knowledge is good and spreading it is good, if the intention is right. But look at what binds you from morning to evening, and prefer nothing to it.” Ibn Mas'ud said: “The Quran was sent down to be acted on, and you have made studying it your deed. People will come who straighten it like a spear shaft; they are not the best of you.” A scholar who does not act is like a sick man describing the medicine, or a hungry man describing fine food he does not have. God says: “Woe to you for what you describe.” A report says: “I only fear for my community a scholar's slip.”" },
    ],
    closer: [
      { title: "The shameful pregnancy", body: "Jesus's image is blunt on purpose. Hidden things show in time. Knowledge not acted on will be made public on the Day of Resurrection." },
      { title: "Satan's clever delay", body: "The most subtle trick here is not laziness. It is the good-sounding plan to learn everything first. The man in Sari's story broke it by turning to action." },
    ],
    distinction: ["Two ways to keep knowledge", "Memorising it", "The fool's care: reporting much, acting little.", "Acting on it", "The scholar's care: “preserving knowledge is acting on it.”"],
    misreading: "This sign does not say only perfect people may teach. Ghazali ends the signs by saying you may either have them or admit you fall short. The danger is the one who does the opposite of what he teaches and hides it.",
    reflection: "Pick one thing you told someone to do this month. Did you do it first?",
    audit: ["Do I do what I tell others to do?", "Do I use more learning as an excuse to delay action?", "Would my preaching slide off hearts like rain off a rock?", "Do I act on even a tenth of what I know?"],
    nodes: ["ulama-akhira", "amal"],
    model: pair("The patient and the medicine", "The scholar who does not act.", [["Describing the cure", "The sick man who knows the medicine and does not take it.", "warning"], ["Taking it", "The scholar who acts first, then preaches.", "support"]]),
  }),
  makeChapter({
    id: 36, shortTitle: "Sign 3: eight lessons in thirty-three years", formalTitle: "The third sign: caring for knowledge that helps in the next life, and Hatim's eight lessons",
    overview: "The third sign is caring for knowledge that helps in the next life and moves you to obey, and avoiding sciences with little use and much argument. Ghazali tells of a man asking the Prophet for rare knowledge, and of Hatim al-Asamm, who learned eight things from his teacher in thirty-three years.",
    thesis: "Asking for rare knowledge before you have dealt with the head of knowledge is like a sick man who finds a doctor briefly and asks about strange medicines. Hatim's eight lessons, drawn from eight verses, contain the good of all four revealed books.",
    moves: [
      { title: "The sick man and the doctor", body: "The third sign is that his care goes to gaining knowledge useful for the next life, which moves him to obey. He avoids sciences with little use and much argument and gossip. Someone who turns from the knowledge of deeds to argument is like a sick man with many illnesses. He meets a skilled doctor for a short time he fears to lose. He spends it asking about the properties of drugs and the strange corners of medicine, and leaves the thing he urgently needs. That is pure foolishness." },
      { title: "The head of knowledge", body: "A man came to the Prophet and said: “Teach me the rare parts of knowledge.” He said: “What have you done about the head of knowledge?” The man asked what that was. He said: “Have you known the Lord?” He said yes. “What have you done about His right?” He said: “What God willed.” “Have you known death?” He said yes. “What have you prepared for it?” He said: “What God willed.” The Prophet said: “Go and master what is there, then come and we will teach you the rare parts of knowledge.”" },
      { title: "Only eight questions", body: "A student should rather be like Hatim al-Asamm, the student of Shaqiq al-Balkhi. Shaqiq asked him: “How long have you been with me?” Hatim said: “Thirty-three years.” “What have you learned from me in that time?” “Eight questions.” Shaqiq said: “To God we belong and to Him we return! My life has gone with you, and you have learned only eight questions?” He said: “Teacher, I have learned nothing else, and I do not like to lie.” Shaqiq said: “Tell me these eight, so I can hear them.”" },
      { title: "First and second", body: "Hatim said: “I looked at people and saw that each loves something and is with it until the grave. When he reaches the grave, it leaves him. So I made good deeds my beloved. When I enter the grave, my beloved enters with me.” Shaqiq said: “Well done. The second?” He said: “I looked at God's words: As for him who feared standing before his Lord and kept his soul from desire, the Garden is his home. I knew God's words are true, so I struggled with my self to push away desire until it settled in obeying God.”" },
      { title: "Third and fourth", body: "“Third, I looked at people and saw that anyone who has something of value raises it up and guards it. Then I looked at God's words: What you have runs out, and what is with God lasts. So whenever something of value came to me, I sent it on to God so it would stay kept with Him. Fourth, I saw that everyone falls back on money, family standing, honour and lineage. I looked at these and they were nothing. Then I looked at God's words: The noblest of you with God is the most mindful of you. So I worked at being mindful, to be noble with God.”" },
      { title: "Fifth and sixth", body: "“Fifth, I saw people attacking and cursing each other, and the root of it all is envy. Then I looked at God's words: We have divided their livelihood among them in this world's life. So I left envy and kept away from people, knowing the share comes from God, and I dropped enmity towards people. Sixth, I saw people wronging and fighting each other. I went back to God's words: Satan is your enemy, so treat him as an enemy. So I made him alone my enemy and tried hard to guard against him, since God has testified he is my enemy. I left enmity towards everyone else.”" },
      { title: "Seventh and eighth", body: "“Seventh, I saw everyone seeking this crust of bread, humbling himself for it and going into what is not lawful for him. Then I looked at God's words: There is no creature on earth whose provision is not God's to give. I knew I am one of those creatures whose provision is God's to give. So I busied myself with what God has on me, and left what I have with Him. Eighth, I saw everyone relying on something created: one on his farm, one on his trade, one on his craft, one on his health. Every creature relies on a creature like itself. I went back to God's words: Whoever relies on God, He is enough for him. So I relied on God, and He is enough for me.”" },
      { title: "The four books in eight", body: "Shaqiq said: “Hatim, may God give you success. I looked into the knowledge of the Torah, the Gospel, the Psalms and the great Quran. I found that all kinds of good and religion turn on these eight questions. Whoever uses them has used the four books.” Ghazali says only the scholars of the next life care to grasp this kind of knowledge. The scholars of the world busy themselves with what makes it easy to earn money and status. They neglect sciences like these, with which God sent all the prophets. Al-Dahhak ibn Muzahim said: “I met them when they learned nothing from each other but caution. Today they learn nothing but talk.”" },
    ],
    closer: [
      { title: "Slow on purpose", body: "Thirty-three years for eight lessons sounds like failure. Shaqiq's reaction is the reader's. His conclusion, that the eight hold all four books, is Ghazali's." },
      { title: "The head of knowledge", body: "Know your Lord and do His right; know death and prepare for it. Everything rare comes after these." },
    ],
    distinction: ["Two things to ask a doctor in a short visit", "The rare corners of medicine", "Interesting, and useless for your illness.", "The cure you need now", "Knowing your Lord and preparing for death: the head of knowledge."],
    misreading: "Hatim's lessons are not a call to leave all other study. They are what must be settled first. The Prophet told the man to master the head of knowledge “then come and we will teach you the rare parts.”",
    reflection: "Take one of Hatim's eight. Which verse would you have to live by for it to become yours?",
    audit: ["What have I done about God's right?", "What have I prepared for death?", "Which of Hatim's eight have I learned in all my years?", "Do I ask for rare knowledge while my illness waits?"],
    nodes: ["ulama-akhira", "tawakkul"],
    model: chain("Hatim's eight lessons", "Each drawn from a verse.", [["Deeds as the beloved", "The one friend who enters the grave with you.", "support"], ["Desire resisted; treasure sent ahead", "Settled in obedience; kept with God.", "support"], ["Mindfulness over lineage; no envy", "Noble with God; the shares are His.", "support"], ["One enemy; provision and reliance on God", "Only Satan is the enemy; God is enough.", "support"]]),
  }),
  makeChapter({
    id: 37, shortTitle: "Sign 4: a simple life", formalTitle: "The fourth sign: not leaning to luxury, with Hatim's visits and Malik's letter",
    overview: "The fourth sign is not leaning to luxury in food, drink, clothing, furniture and house. Ghazali tells how Hatim al-Asamm visited a rich judge in Rayy, washed his arms four times before another in Qazwin, and called Medina Pharaoh's city. Then Malik answers a letter of advice with fairness.",
    thesis: "Adornment with permitted things is not forbidden. But plunging into it makes a person attached to it, and keeping it up usually needs flattery and showing off. So caution is to avoid it. Malik could admit that leaving it is better and still rule it permitted; others cannot hold to the limit.",
    moves: [
      { title: "The nearer to little, the nearer to God", body: "The fourth sign is that he does not lean to luxury in food and drink, comfort in clothing, or finery in furniture and house. He prefers moderation in all of it and follows the early Muslims. He leans to making do with the least in all of it. The more he leans towards little, the nearer he is to God, and the higher his group among the scholars of the next life." },
      { title: "The judge's palace", body: "Abu Abd Allah al-Khawwas, a companion of Hatim al-Asamm, said: “I went with Hatim into Rayy. With us were three hundred and twenty men going on pilgrimage, in wool cloaks, with no bag and no food. A poor-living merchant who loved the poor took us in that night. The next day he said to Hatim: I am going to visit a lawyer of ours who is ill. Hatim said: visiting the sick has merit, and looking at a lawyer is worship; I will come too.” The sick man was Muhammad ibn Muqatil, the judge of Rayy. At the door was a high, fine palace. Hatim stood thinking: “A scholar's door like this?” Inside was a wide, pleasant house, with fine things and curtains. Hatim stood thinking again. The judge lay on soft bedding, with a servant boy at his head holding a fly-whisk." },
      { title: "Who taught you this?", body: "The merchant sat and asked after his health. Hatim stayed standing. The judge signed to him to sit. He said: “I will not sit.” “Perhaps you need something?” “Yes, a question.” “Ask.” “Sit up straight so I can ask.” He sat up. Hatim said: “Your knowledge: where did you take it from?” “From trustworthy men who told it to me.” “From whom?” “From the Companions of the messenger of God.” “And they?” “From the messenger of God.” “And he?” “From Gabriel, from God.”" },
      { title: "Pharaoh built with brick", body: "Hatim said: “Gabriel brought it from God to the messenger, and he to his Companions, and they to trustworthy men, and they to you. In all that, did you hear that whoever has a high house, and the bigger it is, has a greater level with God?” He said no. “Then what did you hear?” “That whoever does without the world, longs for the next, loves the poor, and sends good ahead for his next life has a level with God.” Hatim said: “Then whom have you followed: the Prophet, his Companions and the righteous, or Pharaoh and Nimrod, the first to build with plaster and baked brick? Bad scholars! An ignorant man greedy for the world sees you and says: the scholar lives like this; shall I not be worse than him?” He left, and the judge grew sicker." },
      { title: "Washing four times", body: "The people of Rayy heard, and told Hatim: “Al-Tanafisi in Qazwin lives even more lavishly.” Hatim went there on purpose and said: “God have mercy on you. I am a foreigner. Teach me the start of my religion and the key of my prayer: how to do ablution.” He said: “Gladly. Boy, bring water.” Al-Tanafisi washed each part three times and said: “Like this.” Hatim said: “Stay there while I do it in front of you, to be sure.” He washed his forearms four times. Al-Tanafisi said: “You have been wasteful.” Hatim said: “Glory be to God! I am wasteful with a handful of water, and you with all this are not?” Al-Tanafisi knew he had come for that, not to learn. He went into his house and did not come out to people for forty days." },
      { title: "Three traits that win", body: "When Hatim came to Baghdad, people gathered and said: “You are a foreigner, yet no one talks with you without your silencing him.” He said: “I have three traits by which I beat my opponent. I am glad when he is right, sad when he is wrong, and I keep myself from being foolish towards him.” Ahmad ibn Hanbal heard and said: “Glory be to God, how wise he is! Let us go to him.” Ahmad asked: “What is safety from the world?” Hatim said: “You will not be safe from the world until you have four traits. Forgive people their foolishness, keep your foolishness from them, give them what is yours, and give up hope of what is theirs. Then you will be safe.”" },
      { title: "Pharaoh's city", body: "Then he went to Medina. People met him and he asked: “What city is this?” “The city of the messenger of God.” “Where is his palace, so I can pray in it?” “He had no palace, only a low house.” “Where are his Companions' palaces?” “They had none, only low houses.” He said: “Then this is Pharaoh's city.” They took him to the governor. Hatim said: “Do not be hasty. I am a foreign stranger,” and told the story. He added: “God said: In the messenger of God you have a fine example. So whom have you followed: the messenger of God, or Pharaoh, the first to build with plaster and brick?” They released him." },
      { title: "Why caution", body: "The lives of the early Muslims, in plain clothing and leaving finery, will be told in their places. The truth is this: adorning oneself with permitted things is not forbidden. But plunging into it makes a person attached, until leaving it is hard. Keeping up finery usually needs means that bring sins with them: flattery, pleasing people, showing off and other forbidden things. Caution avoids it, because whoever plunges into the world is never safe from it. If safety came with plunging in, the Prophet would not have gone so far in leaving the world. He took off an embroidered shirt, and took off a gold ring in the middle of a sermon." },
      { title: "Malik's letter", body: "Yahya ibn Yazid al-Nawfali wrote to Malik: “I have heard that you wear fine cloth, eat fine bread, sit on soft cushions and have a doorkeeper. You sit in the seat of knowledge. People ride to you from afar and have taken you as their imam. So fear God, Malik, and be humble. I write this advice in a letter no one has seen but God.” Malik wrote back: “Your letter reached me as advice, kindness and good manners. May God let you enjoy mindfulness of Him and reward you for your advice. As for fine bread, fine cloth, the doorkeeper and the cushions: we do that, and we ask God's forgiveness. God said: Say, who has forbidden the adornment God brought out for His servants, and the good things of provision? I know leaving it is better than going into it. Do not stop writing to us, and we will not stop writing to you.”" },
      { title: "Fairness and its limit", body: "See Malik's fairness. He admitted that leaving it is better, and ruled that it is permitted, and he was right on both. Malik's self allowed him to be fair and admit this to such advice. Someone of his standing also had the strength to stop at the limits of the permitted. So it did not lead him into showing off, flattery and the disliked. Others cannot do that. Leaning towards enjoying the permitted is a great danger and far from fear of God. The special mark of God's scholars is fear, and the mark of fear is keeping away from danger." },
    ],
    closer: [
      { title: "Hatim's method", body: "Hatim never lectured. He asked a question, washed his arms once too often, or asked where the Prophet's palace was. Each time the lesson came from the other person's own answer." },
      { title: "Both true", body: "Malik's letter shows how to answer advice. He does not deny the facts, does not defend them as best, and does not forbid what God permitted. He thanks the man and asks him to keep writing." },
    ],
    distinction: ["Two true statements in Malik's letter", "It is permitted", "God asks who has forbidden the adornment He brought out: fine things are not sinful.", "Leaving it is better", "Plunging in makes a person attached, and keeping it up needs flattery and show."],
    misreading: "Ghazali does not say the rich judge was an unbeliever or that fine things are forbidden. He agrees with Malik that they are permitted. The sign is about which way a scholar leans, and what finery costs the heart.",
    reflection: "What would Hatim ask if he walked into your room?",
    audit: ["Am I attached to comforts I could leave?", "Does keeping up my standard of living make me flatter anyone?", "Can I take advice as Malik did?", "Am I glad when my opponent is right?"],
    nodes: ["ulama-akhira", "zuhd"],
    model: spectrum("From little to luxury", "Where the scholar leans.", [["Making do with the least", "The nearer to little, the nearer to God.", "support"], ["Permitted comfort", "Not forbidden; Malik held it and admitted leaving it is better.", "balance"], ["Luxury kept up", "Needs flattery and show, and breeds attachment.", "warning"]]),
  }),
  makeChapter({
    id: 38, shortTitle: "Sign 5: keeping away from rulers", formalTitle: "The fifth sign: keeping away from rulers",
    overview: "The fifth sign is keeping away from rulers, and not visiting them at all while there is a way to avoid it. It means being careful even when they come to him. The world's reins are in rulers' hands, and a scholar who visits them either envies their finery, flatters them, praises them falsely, or hopes for their money.",
    thesis: "Mixing with rulers is a key to evils. The scholars are the messengers' trustees as long as they do not mix with rulers; when they do, they have betrayed the messengers. Satan whispers that visiting them is religion, since the visitor can preach to them; then the visitor soon softens his speech and flatters.",
    moves: [
      { title: "Four ways to fall", body: "The fifth sign is keeping far from rulers. He does not go in to them at all while he can find a way to escape. He is careful about mixing with them even if they come to him. The world is sweet and green, and its reins are in rulers' hands. Whoever mixes with them cannot avoid working to please them and win their hearts, though they are unjust. Every religious person must object to them and make them uneasy by showing their wrong and its ugliness. So whoever goes in to them falls one of four ways. He notices their finery and looks down on God's blessing to himself. Or he stays silent and so flatters them. Or he strains to say things to please them and make their state look good, which is plain falsehood. Or he hopes to get some of their world, which is unlawful gain. The Book of the Lawful and Unlawful will explain what may be taken from rulers." },
      { title: "The Prophet's warnings", body: "The Prophet said: “Whoever lives in the desert grows rough, whoever follows the hunt grows heedless, and whoever goes to the ruler is tried.” He said: “There will be rulers over you, some of whose acts you approve and some you reject. Whoever rejects is free of blame; whoever dislikes is safe; but whoever approves and follows, God puts him far away.” They asked: “Shall we not fight them?” He said: “No, as long as they pray.” Sufyan said: “In Hell is a valley where only reciters who visit kings live.” Hudhayfa said: “Beware the places of trial.” What are they? “The rulers' doors. One of you goes in to a ruler, tells him his lie is true, and says of him what is not in him.”" },
      { title: "Trustees who betray", body: "The Prophet said: “The scholars are the messengers' trustees over God's servants, as long as they do not mix with rulers. When they do, they have betrayed the messengers. So beware of them and keep away from them.” Anas reported it. Someone told al-A'mash: “You have revived knowledge, so many take it from you.” He said: “Do not be hasty. A third die before they mature. A third stick to rulers' doors; they are the worst of creation. Of the last third, only a few succeed.” Sa'id ibn al-Musayyib said: “When you see a scholar calling on rulers, beware of him; he is a thief.” Al-Awza'i said: “Nothing is more hateful to God than a scholar who visits an official.”" },
      { title: "Best and worst", body: "The Prophet said: “The worst scholars are those who go to rulers, and the best rulers are those who go to scholars.” Makhul said: “Someone may learn the Quran and law, then keep company with the ruler to flatter him and hope for what he has. He wades in a sea of Hell's fire, one step for each of his steps.” Samnun said: “How ugly for a scholar when people come to his gathering and he is not there! They ask and are told: he is with the prince.”" },
      { title: "Checking himself after each visit", body: "Samnun said: “I used to hear it said: when you see a scholar love the world, suspect him about your religion. I tested it. I never went in to this ruler without checking myself when I came out, and I found I had lost. You see how harsh and rough I am with him, and how much I go against his wishes. I wish I could come out of going to him even, though I take nothing from him and do not drink a drop of his water.” He said: “The scholars of our time are worse than the scholars of the Israelites. They tell the ruler the easy rulings and what suits his wishes. If they told him what he owes and what would save him, he would find them heavy and dislike their coming. That would be their salvation with their Lord.”" },
      { title: "A thin believer", body: "Al-Hasan told of an early Companion, who Ibn al-Mubarak said was Sa'd ibn Abi Waqqas. He never visited rulers and shunned them. His sons said: “People not your equals in companionship with the Prophet or in Islam go to them. If only you went.” He said: “My sons, shall I go to a carcass that people have surrounded? By God, if I can help it I will not share in it.” They said: “Father, then we will die thin.” He said: “My sons, I would rather die a thin believer than a fat hypocrite.” Al-Hasan said: “By God, he beat them, for he knew the earth eats flesh and fat, but not faith.” This hints that whoever visits the ruler is never safe from hypocrisy, which is the opposite of faith." },
      { title: "Satan's argument", body: "Abu Dharr told Salama: “Salama, do not go to rulers' doors. You will get nothing of their world without their getting something better of your religion.” This is a great trial for scholars, and a strong opening for Satan, especially with someone well spoken. Satan keeps suggesting that by preaching to them and visiting them he will stop their injustice and uphold the law, until he imagines visiting them is religion. Then once he goes in, it is not long before he softens his words, flatters, and pours out praise. In that is the ruin of religion." },
      { title: "When sought, they fled", body: "It used to be said: “When scholars know, they act. When they act, they are busy. When busy, they are missed. When missed, they are sought. When sought, they flee.” Umar ibn Abd al-Aziz wrote to al-Hasan: “Point me to people I can use to help with God's affairs.” He wrote back: “The people of religion do not want you, and the people of the world you will not want. But take the noble families; they guard their honour from being stained by betrayal.” That was Umar ibn Abd al-Aziz, the most ascetic man of his time. If the people of religion had to flee even him, how can seeking and mixing with others be right? Think of the early scholars, like al-Hasan, al-Thawri, Ibn al-Mubarak, al-Fudayl, Ibrahim ibn Adham and Yusuf ibn Asbat. They kept speaking against the worldly scholars of Mecca, Syria and elsewhere, for their love of the world or their mixing with rulers." },
    ],
    closer: [
      { title: "The thin believer", body: "Sa'd's answer to his sons is the whole sign in one sentence. The earth eats flesh and fat; it does not eat faith." },
      { title: "The best argument for going", body: "Satan's strongest case is a good one: go, and preach to them. Ghazali does not deny it could help. He says the visitor soon softens and flatters, and that is where religion is lost." },
    ],
    distinction: ["Two directions of visiting", "Rulers going to scholars", "The best rulers: the Prophet names them.", "Scholars going to rulers", "The worst scholars: they betray the messengers' trust."],
    misreading: "This sign does not forbid obeying rulers or call for rebellion. The Prophet forbids fighting them as long as they pray. What it forbids is scholars seeking them out and flattering them.",
    reflection: "Think of someone powerful whose approval you want. What would you stop saying to keep it?",
    audit: ["Do I seek out powerful people?", "Do I soften the truth for those who can reward me?", "Do I check myself after being with them?", "Would I rather be a thin believer or a fat hypocrite?"],
    nodes: ["ulama-akhira", "salatin"],
    model: chain("How the visit goes wrong", "Satan's route, in Ghazali's order.", [["The good reason", "“If I visit, I can preach and stop injustice.”", "balance"], ["The visit", "Their finery, their power, their favour.", "warning"], ["The softening", "Words grow gentle; silence where objection is due.", "warning"], ["The ruin", "Flattery and praise; religion traded for their world.", "warning"]]),
  }),
  makeChapter({
    id: 39, shortTitle: "Sign 6: slow to give rulings", formalTitle: "The sixth sign: not rushing to give rulings, and the virtue of “I don't know”",
    overview: "The sixth sign is being slow to give rulings, holding back while there is a way out. The scholar answers clearly what is certain and says “I don't know” to what he doubts. He passes on what rests on his own guess if someone else can answer. The Companions passed questions round until they came back to the first.",
    thesis: "“I don't know” is half of knowledge and the scholar's shield. The quickest to give rulings had the least knowledge, and the most careful pushed them away. Silence, except when needed, was the habit of the people of knowledge; now what they fled is sought, and what they sought is fled.",
    moves: [
      { title: "Three kinds of question", body: "The sixth sign is that he does not rush to give rulings. He holds back and takes care while he can find a way out. If asked what he knows for sure, from a clear text of God's Book, a clear report, agreement or clear analogy, he answers. If asked what he doubts, he says: “I don't know.” If asked what he thinks by his own reasoning and guess, he is cautious and defends himself. He passes it to someone else if there is someone who can answer. This is wisdom, because taking on the danger of reasoning for others is great. A report says: “Knowledge is three: a speaking Book, an established Sunna, and I don't know.” Al-Sha'bi said: “I don't know is half of knowledge.”" },
      { title: "Silence rewarded", body: "Whoever keeps silent for God where he does not know earns no less than one who speaks, because admitting ignorance is harder on the self. That was the way of the Companions and the early Muslims. When Ibn Umar was asked for a ruling, he said: “Go to this governor who took charge of people's affairs, and put it on his neck.” Ibn Mas'ud said: “Whoever gives people rulings on everything they ask is mad.” He said: “The scholar's shield is I don't know. If he misses it, he is struck in a deadly place.”" },
      { title: "Silence that frightens Satan", body: "Ibrahim ibn Adham said: “Nothing is harder on Satan than a scholar who speaks with knowledge and keeps silent with knowledge. Satan says: look at him; his silence is harder on me than his speech.” Someone described the saints called the Abdal: “Their eating is need, their sleep is when overcome, and their speech is when necessary.” That is, they do not speak until asked. When asked and they find someone to do it for them, they keep quiet. If forced, they answer. They counted speaking before being asked as a hidden desire to talk." },
      { title: "Like pulling a tooth", body: "Ali and Abd Allah passed a man speaking to people and said: “This one is saying: know me.” Someone said: “The real scholar is one who, when asked a question, looks as if a tooth is being pulled.” Ibn Umar used to say: “Do you want to make us a bridge you cross over into Hell?” Abu Hafs al-Naysaburi said: “The scholar is one who fears, when asked, that he will be told on the Day of Resurrection: where did you get that answer?” Ibrahim al-Taymi, when asked a question, wept and said: “Could you find no one but me, that you needed me?” Abu al-Aliya, Ibrahim ibn Adham and al-Thawri spoke to two, three or a few people, and left when more came." },
      { title: "The Prophet said “I don't know”", body: "The Prophet said: “I do not know whether Uzayr was a prophet or not. I do not know whether Tubba' is cursed or not. I do not know whether Dhu al-Qarnayn was a prophet or not.” When asked the best and worst places on earth, he said: “I don't know,” until Gabriel came. He asked him, and Gabriel said: “I don't know,” until God told him the best places are mosques and the worst are markets. Ibn Umar would be asked ten questions, answer one and keep silent on nine. Ibn Abbas would answer nine and keep silent on one. Among the lawyers some said “I don't know” more than “I know”: Sufyan al-Thawri, Malik, Ahmad ibn Hanbal, al-Fudayl and Bishr ibn al-Harith." },
      { title: "The roasted head", body: "Abd al-Rahman ibn Abi Layla said: “I met a hundred and twenty of the Prophet's Companions in this mosque. Not one was asked about a report or a ruling without wishing his brother would do it for him.” In another version, a question was put to one, who passed it to another, who passed it on, until it came back to the first. It is told that one of the People of the Bench, in great hardship, was given a roasted sheep's head as a gift. He gave it to another, who gave it to another, and it went round until it came back to the first. See how the scholars' state has been turned around. What was fled is sought, and what was sought is fled." },
      { title: "Four things they pushed away", body: "It is reported: “Only three give people rulings: a ruler, one he appoints, or one who takes it on without need.” Someone said the Companions pushed four things away from each other: leading the prayer, being executor of a will, holding a deposit, and giving rulings. Someone said: “The quickest of them to give rulings had the least knowledge, and the strongest in pushing them away was the most careful.” The Companions and their followers were busy with five things: reciting the Quran, building up mosques, remembering God, commanding good and forbidding wrong. The Prophet said: “All of a person's speech is against him, not for him, except three: commanding good, forbidding wrong, or remembering God.” God says: “There is no good in much of their secret talk, except one who orders charity, good, or making peace between people.”" },
      { title: "Calling the people of Badr", body: "A scholar saw in a dream one of the Kufan men of personal opinion. He asked: “What did you find of the rulings and opinion you held?” The man frowned, turned away and said: “We found it was nothing, and we did not like how it ended.” Ibn Husayn said: “One of them will give a ruling on a question at once. Had it come to Umar, he would have gathered the veterans of Badr for it.” Silence remained the habit of the people of knowledge except when needed. A report says: “When you see a man given silence and doing without, draw near him, for he is taught wisdom.”" },
      { title: "The Tigris and the covered well", body: "It was said there are two kinds of scholar. One is the scholar of the public: those who give rulings, the companions of rulers. The other is the scholar of the few, who knows God's oneness and the acts of the heart, the people of the corners, scattered and alone. It was said Ahmad ibn Hanbal was like the Tigris, from which everyone draws. Bishr ibn al-Harith like a sweet covered well, visited one person at a time. They used to say: so-and-so is a scholar, so-and-so a talker; one talks more, the other does more. Abu Sulayman said: “Knowing God is nearer to silence than to speech.” It was said: “When knowledge grows, speech shrinks; when speech grows, knowledge shrinks.”" },
      { title: "Doctor or pretender", body: "Salman wrote to Abu al-Darda, his brother by the Prophet's pairing: “Brother, I hear you have sat down as a doctor to treat the sick. See to it. If you are a doctor, speak, for your words are a cure. If you are a pretender, for God's sake do not kill a Muslim.” After that Abu al-Darda held back when asked. When Anas was asked, he said: “Ask our master al-Hasan.” Ibn Abbas said: “Ask Haritha ibn Zayd.” Ibn Umar said: “Ask Sa'id ibn al-Musayyib.” A Companion reported twenty reports with al-Hasan present, and was asked to explain them. He said: “I have only what I reported.” Al-Hasan explained them one by one, and they marvelled. The Companion took a handful of pebbles, threw them at them and said: “You ask me about knowledge while this great scholar is among you?”" },
    ],
    closer: [
      { title: "The roasted head", body: "The sheep's head going round the Bench is the same shape as the questions going round the mosque. The Companions pushed away gifts and rulings alike. Each wanted the other to have them." },
      { title: "A shield", body: "Ibn Mas'ud calls “I don't know” the scholar's shield. It is not a weakness to hide. A scholar who drops it is struck where it kills." },
    ],
    distinction: ["Two kinds of scholar in the saying", "The scholar of the public", "Gives rulings; like the Tigris, everyone draws from him; often near rulers.", "The scholar of the few", "Knows God's oneness and the heart's acts; like a covered well, visited one at a time."],
    misreading: "Holding back is not refusing to answer what is known. Ghazali says to answer what is certain from text, agreement or clear analogy. What he warns against is guessing for others where one does not know.",
    reflection: "When were you last asked something you did not know? Did you say so?",
    audit: ["Can I say “I don't know” without shame?", "Do I speak before I am asked?", "Do I pass questions to someone who knows better?", "Do I fear being asked on the Day of Resurrection where my answer came from?"],
    nodes: ["ulama-akhira", "samt"],
    model: chain("Three kinds of question", "The scholar of the next life's rule.", [["Known for certain", "From clear text, agreement or clear analogy: answer.", "support"], ["Doubted", "Say “I don't know”: half of knowledge.", "support"], ["Guessed by reasoning", "Be cautious; pass it on if someone else can answer.", "balance"], ["Speaking before asked", "A hidden desire to talk.", "warning"]]),
  }),
  makeChapter({
    id: 40, shortTitle: "Sign 7: the heart's knowledge", formalTitle: "The seventh sign: caring most for inner knowledge and watching the heart, and Ali's words to Kumayl",
    overview: "The seventh sign is caring most for inner knowledge, watching the heart, and walking the road to the next life, hoping for unveiling through striving and watchfulness. Books do not give this; action and solitude with God do. Ali described these scholars to Kumayl and wept with longing to see them.",
    thesis: "Striving leads to witnessing. Whoever acts on what he knows is given by God knowledge he did not know. Fine meanings of the Quran come to hearts devoted to remembrance that commentaries do not hold. Such scholars are few in number and great in worth; through them God keeps His proofs alive on earth.",
    moves: [
      { title: "Striving leads to seeing", body: "The seventh sign is that his main concern is inner knowledge, watching the heart, and knowing the road to the next life and walking it. He truly hoping for it to be unveiled by striving and watchfulness. Striving leads to witnessing, and the fine points of the heart's knowledge make springs of wisdom burst from the heart. Books and teaching do not reach this. Wisdom beyond counting opens only by striving, watchfulness, and doing outward and inward deeds. It opens by sitting alone with God with a present heart, clear thought, and cutting off from all but Him. That is the key of inspiration and the spring of unveiling." },
      { title: "Knowledge inherited by acting", body: "Many students study long and cannot go one word beyond what they heard. Many keep to the essentials in learning and give themselves to action and watching the heart, and God opens to them subtle wisdom that bewilders the wise. That is why the Prophet said: “Whoever acts on what he knows, God makes him inherit knowledge of what he did not know.” Many fine meanings of the Quran's secrets come to the hearts of those devoted to remembrance and thought. The commentaries lack them, and that the best commentators have not seen. When they are shown to commentators, they approve, and know they are prompts of pure hearts and God's kindness to high aims turned to Him." },
      { title: "Each an ocean", body: "So too in the knowledge of unveiling, the secrets of practice, and the fine thoughts of hearts. Each of these is an ocean whose depth cannot be reached. Each seeker wades in as far as he is given, and by the good deeds he was helped to do. Sahl al-Tustari said: “The scholars, worshippers and ascetics left the world with their hearts locked. Only the hearts of the truthful and the martyrs were opened.” Then he recited: “With Him are the keys of the unseen; none knows them but He.”" },
      { title: "Ask your heart", body: "A heart lit by inner light has a grasp that rules over outward knowledge. Otherwise the Prophet would not have said: “Ask your heart for a ruling, even if they give you rulings, and give you rulings, and give you rulings.” He said, telling from his Lord: “My servant keeps coming near to Me with voluntary deeds until I love him. When I love him, I am his hearing by which he hears,” to the end of the report." },
      { title: "Ali to Kumayl: three kinds of people", body: "Ali described these scholars in a long saying to Kumayl: “Hearts are vessels, and the best is the one that holds most good. People are three: a scholar devoted to his Lord, a learner on the road to salvation, and a rabble following every crier, bending with every wind. They did not seek light from knowledge, and did not take refuge in a firm support. Knowledge is better than money: knowledge guards you, and you guard money. Knowledge grows by spending, and money shrinks by it. Knowledge is a religion lived by; it earns obedience in life and a good name after death. Knowledge judges and money is judged. Money's benefit goes when it goes. The hoarders of money are dead while alive, and the scholars live as long as time lasts.”" },
      { title: "If only I found carriers", body: "Then Ali sighed deeply and said: “Here is much knowledge, if only I found people to carry it. But I find a student who cannot be trusted, who uses religion as a tool to seek the world. He lords it over God's friends with God's blessings, and uses God's proofs against His creatures. Or one who obeys the people of truth but has no insight. Doubt takes root in his heart at the first difficulty; he is neither this nor that. Or one greedy for pleasures, easily led by desires. Or one eager to gather and hoard wealth, led by his desire; the nearest likeness to them is grazing cattle. O God, so knowledge dies when its carriers die.”" },
      { title: "The few and great", body: "Ali went on: “Yet the earth is never without someone standing for God with His proof. He is either open and known, or afraid and overpowered, so that God's proofs and signs are not wiped out. How many are they, and where? They are few in number and great in worth. Their persons are missing, but their likeness is in hearts. Through them God keeps His proofs, until they pass them to those after them and plant them in hearts like theirs. Knowledge has rushed them to the truth of things. They have touched the spirit of certainty, found easy what the pampered find harsh, and found comfort in what frightens the heedless. They kept company with the world with bodies whose spirits hang from the highest place. They are God's friends among His creatures, His trustees and workers on earth, and those who call to His religion.” Then he wept and said: “How I long to see them!” Ghazali says this last description is of the scholars of the next life, and their knowledge comes mostly from action and constant striving." },
    ],
    closer: [
      { title: "Learning by doing", body: "The report about inheriting knowledge turns the usual order around. Most people learn first and act later. Here, acting on the little you know is how more knowledge arrives." },
      { title: "Ali's four failures", body: "Ali's list of unsuitable students is a mirror: the one who uses religion for the world, the one with no insight, the pleasure-seeker, and the hoarder. The fit carrier is none of these." },
    ],
    distinction: ["Two ways knowledge arrives", "From books and teaching", "Many study long and cannot go one word past what they heard.", "From action and watching the heart", "Whoever acts on what he knows inherits what he did not know."],
    misreading: "Ghazali does not throw away books or teachers. He speaks of keeping to the essentials in learning and then giving oneself to action. What he denies is that books alone open the heart's knowledge.",
    reflection: "Pick one thing you already know and have not acted on. What might acting on it teach you?",
    audit: ["Do I sit alone with God with a present heart?", "Do I act on the little I know?", "Which of Ali's four unfit students am I most like?", "Is my heart a vessel that holds good?"],
    nodes: ["ulama-akhira", "muraqaba", "mukashafa"],
    model: spectrum("Ali's three kinds of people", "From his words to Kumayl.", [["The devoted scholar", "Knows his Lord; knowledge has rushed him to the truth.", "support"], ["The learner", "On the road to salvation.", "support"], ["The rabble", "Follows every crier and bends with every wind.", "warning"]]),
  }),
  makeChapter({
    id: 41, shortTitle: "Sign 8: certainty", formalTitle: "The eighth sign: strengthening certainty, its two meanings, and its fields",
    overview: "The eighth sign is working to strengthen certainty, which is the capital of religion. Ghazali explains that the word has two uses. For theologians it means no doubt. For lawyers, Sufis and most scholars it means a belief that rules the heart. He shows how certainty grows stronger, clearer and wider, and names its main fields.",
    thesis: "Everyone is certain of death, yet few are ruled by that certainty. The scholar of the next life works on both: removing doubt, and then letting certainty take over the self. In God's oneness, in provision, in reward and punishment, and in God seeing you, certainty is the tree, good character the branches, and good deeds the fruit.",
    moves: [
      { title: "The capital of religion", body: "The eighth sign is caring greatly to strengthen certainty, since certainty is the capital of religion. The Prophet said: “Certainty is the whole of faith.” So one must learn the knowledge of certainty, its beginnings, and then its road opens to the heart. The Prophet said: “Learn certainty.” That means sit with the certain, hear the knowledge of certainty from them, and keep following them, so your certainty grows strong as theirs did. A little certainty is better than a lot of deeds." },
      { title: "Sins do not harm him", body: "The Prophet was told of a man of good certainty with many sins, and a man who works hard at worship with little certainty. He said: “Every human has sins. But one whose nature is reason and whose character is certainty is not harmed by sins. Whenever he sins he repents, asks forgiveness and regrets, so his sins are wiped out and he keeps a surplus to enter the Garden.” He said: “Among the least of what you were given are certainty and firm patience. Whoever is given his share of them does not mind what he misses of night prayer and day fasting.” Luqman told his son: “Deeds are only possible with certainty. A person acts only as much as he is certain, and falls short only when his certainty falls short.” Yahya ibn Mu'adh said: “Oneness has a light and idolatry a fire. The light of oneness burns up believers' sins more than the fire of idolatry burns up idolaters' good deeds.”" },
      { title: "Four steps to certainty", body: "What is certainty? The word is used by two groups for two meanings. Theologians use it for the absence of doubt. The self's leaning to believe something has four steps. First, belief and denial are balanced: asked whether a stranger will be punished, you lean neither way. That is doubt. Second, you lean one way while aware the other is possible. Asked about a man known for goodness, you lean to thinking he will not be punished, while allowing that something hidden may deserve it. That is opinion. Third, the self leans so strongly that nothing else comes to mind, and if it did, the self would refuse it, but without real knowledge. If he listened to doubts, he would allow them. That is belief close to certainty. It is how ordinary people hold all religious matters: each group trusts its school and imam, and recoils at the thought he could be wrong." },
      { title: "Proof of the eternal", body: "Fourth is real knowledge by a proof that cannot be doubted. That is certainty for the theologians. For example, ask a sensible person whether anything eternal exists. He cannot accept it at once. The eternal is not seen like the sun and moon. It is not self-evident like two being more than one, or like the impossibility of an event with no cause. Some people hear it and accept it firmly: that is belief, the state of ordinary people. Others accept it by proof. Things that exist are either all eternal, all made, or some of each. If all were made, something would have come about with no cause, which is impossible. So either all are eternal, or some are. Either way there is something eternal." },
      { title: "Many roads to it", body: "For them, any knowledge reached this way is certainty. It may come by reasoning, by the senses, or by the mind's nature, as with the impossibility of an event with no cause. It may come by mass report, as with knowing Mecca exists, or by experience, as with knowing boiled scammony loosens the bowels. The condition is no doubt. So on this use, certainty cannot be called weak, since there are no degrees in having no doubt." },
      { title: "Ruled by it", body: "The second use is that of lawyers, Sufis and most scholars. They look not at whether doubt is possible but at how far the belief takes over the mind. So they say: “He has weak certainty of death,” though he has no doubt of it. They say: “He has strong certainty that his provision will come,” though it may not. When the self leans to believe something and it takes over the heart until it rules and directs the self, allowing and forbidding, that is certainty. Everyone is sure of death and free of doubt about it. But some never think of it or prepare, as if they were not sure. Others are so taken over by it that preparing fills all their attention and leaves no room for anything else. That is strong certainty. So someone said: “I have never seen a certainty without doubt more like a doubt without certainty than death.”" },
      { title: "Stronger, clearer, wider", body: "The scholars of the next life work at both: removing doubt, then letting certainty rule the self. Certainty differs in three ways. In strength and weakness, by the second use: how far it rules the heart, which has endless degrees; people differ in preparing for death by this. It differs in clearness, even without doubt. You are sure of Mecca and of Fadak, and of Moses and of Joshua, all by mass report. Yet some are clearer to you because more people told of them. A proof from many arguments is clearer than from one, though neither leaves doubt. A theologian who takes knowledge from books and does not look at his own states may deny this. In amount, by how many things it covers, as one person knows more than another. A scholar may be strongly certain of all the law brings, or of only some of it." },
      { title: "The pen and the hand", body: "Everything the prophets brought is a field for certainty. Ghazali names the main ones. First, God's oneness: seeing all things as from the Cause of causes. You do not look to go-betweens, but seeing them as made to serve with no power of their own. Whoever believes this with no doubt is certain in the first sense. It may take over his heart until he no longer grows angry at go-betweens, or is pleased with them or thanks them. He sees them as a pen and a hand in the service of the king who signs a gift. Then he is certain in the second sense. He does not thank the pen or the hand, or grow angry at them. Sun, stars, plants, animals and all creatures are made to serve by God's command, as the pen serves the writer. When he sees that, trust, contentment and acceptance take over his heart. He becomes free of anger, spite, envy and bad character." },
      { title: "Provision, and reward", body: "Another field is trust in God's guarantee of provision: “There is no creature on earth whose provision is not God's to give.” It is certainty that what was decreed for him will be brought to him. When this rules his heart, he seeks gently, without fierce greed or grief for what he missed. Another is certainty of reward and punishment: “Whoever does an atom's weight of good will see it, and whoever does an atom's weight of evil will see it.” He sees acts of obedience related to reward as bread to fullness, and sins related to punishment as poisons and snakes to death. He keeps every act of obedience, small and great, as he keeps bread, and avoids every sin, small and great, as he avoids poison. In the first sense all believers may have it; in the second, only those brought near. Its fruit is true watchfulness over movement, stillness and passing thought." },
      { title: "God sees you", body: "Another is certainty that God sees you in every state, and watches the whispers of your mind and your hidden thoughts. Every believer is certain of this in the first sense. In the second sense, which is the aim, it is rare and belongs to the truthful. Its fruit is that a person alone behaves in every state like someone sitting before a great king who is watching him. He keeps his eyes down, his manners correct, and holds back from any movement against good manners. His inner thoughts are like his outer deeds, since he is sure God sees his inside as people see his outside. He works harder at building, cleaning and adorning his inside for God's eye than at adorning his outside for people. This level brings shame, fear, brokenness, humility and many praised traits, and they bring high acts of obedience." },
      { title: "Tree, branches, fruit", body: "So in every field, certainty is like a tree. These traits in the heart are like the branches growing from it. The deeds and acts of obedience that come from the traits are like the fruit and the blossoms on the branches. Certainty is the root and foundation. It has more fields and doors than those listed, and the Quarter of Things that Save will give them." },
    ],
    closer: [
      { title: "Certain of death, and careless", body: "The line about death sums up the chapter. No one doubts it, and most live as if it were not coming. Removing doubt is not enough; the certainty has to rule." },
      { title: "The pen and the hand", body: "Nobody thanks the pen that signed a gift. The one who sees people as pens in God's hand stops resenting them and stops worshipping them." },
    ],
    distinction: ["Two meanings of certainty", "No doubt", "The theologians' meaning: every believer is certain of death in this sense. It has no degrees.", "Ruling the heart", "The lawyers' and Sufis' meaning: the belief takes over and directs the self. It grows stronger or weaker."],
    misreading: "Ghazali does not despise the ordinary believer's firm belief. He calls it close to certainty. He wants more: that what is believed should rule the heart, as death rules the heart of someone who prepares for it.",
    reflection: "You are certain you will die. Does that certainty rule anything you do this week?",
    audit: ["Which of my beliefs actually rules my heart?", "Do I thank or resent the pen instead of the Writer?", "Do I avoid small sins as I would small poisons?", "Would I behave differently if I felt God watching?"],
    nodes: ["ulama-akhira", "yaqin"],
    model: chain("Four steps to certainty", "The theologians' ladder.", [["Doubt", "Both sides balanced.", "warning"], ["Opinion", "Leaning one way, the other still possible.", "balance"], ["Firm belief", "Nothing else comes to mind, but without proof: close to certainty.", "balance"], ["Certainty", "Knowledge by a proof that cannot be doubted.", "support"]]),
  }),
  makeChapter({
    id: 42, shortTitle: "Sign 9: fear that shows", formalTitle: "The ninth sign: sadness, humility and the visible fear of God",
    overview: "The ninth sign is that fear of God shows on him: sad, broken, eyes lowered, quiet, calm and humble. Ghazali explains why with Sahl al-Tustari's three kinds of scholar, and gathers sayings on calm, gentleness and the Quran learned for action.",
    thesis: "Only knowledge of God together with knowledge of His days, His hidden punishments and blessings on past peoples, brings fear and humility. Chatter, loud laughter and sharpness are the marks of the heedless. The scholars of the next life have the traits of five verses: fear, humility, lowliness, good character and doing without.",
    moves: [
      { title: "His face reminds you of God", body: "The ninth sign is that he is sad, broken, eyes lowered and quiet. The mark of fear shows in his bearing, clothing, way of life, movement and stillness, speech and silence. No one looks at him without being reminded of God. His appearance points to his deeds; a good horse's eye is its mirror. The scholars of the next life are known by their marks of calm, lowliness and humility. It was said: “God never clothed a person in anything finer than humility with calm. It is the clothing of prophets and the mark of the righteous, the truthful and the scholars.” Rushing into talk, grand speech, drowning in laughter and sharpness in movement and speech are the marks of wildness, feeling safe, and forgetting God's great punishment. That is the way of the heedless children of the world." },
      { title: "Sahl's three scholars", body: "Sahl al-Tustari said scholars are three. One knows God's command but not God's days: the ones who give rulings on the lawful and forbidden, and this knowledge does not bring fear. One knows God, but not His command or His days: ordinary believers. One knows God, His command and His days: the truthful, and fear and humility take them over. By God's days he meant the kinds of hidden punishment and inner blessing God poured on past and later peoples. Whoever grasps that fears greatly and shows humility." },
      { title: "Calm, dignity and gentleness", body: "Umar said: “Learn knowledge, and learn for it calm, dignity and forbearance. Be humble to those you learn from, and let those who learn from you be humble to you. Do not be tyrant scholars, so that your ignorance cancels your knowledge.” It was said: “God never gave anyone knowledge without giving him with it forbearance, humility, good character and gentleness. That is useful knowledge.” A saying goes: “Whoever God gives knowledge, doing without, humility and good character is the leader of the mindful.”" },
      { title: "Laughing aloud, weeping in secret", body: "A report says: “Among the best of my community are people who laugh aloud at the breadth of God's mercy. They weep in secret for fear of His punishment. Their bodies are on earth and their hearts in heaven, their spirits in this world and their minds in the next. They walk with calm and draw near by the means.” Al-Hasan said: “Forbearance is knowledge's minister, gentleness its father, and humility its garment.” Bishr ibn al-Harith said: “Whoever seeks leadership by knowledge, come near to God by hating him. He is hated in heaven and on earth.”" },
      { title: "Three hundred and sixty books", body: "Among the Israelite stories: a wise man wrote three hundred and sixty works of wisdom and was called “the wise”. God revealed to their prophet: “Tell him: you have filled the earth with hypocrisy and wanted nothing of Me in it. I accept none of your hypocrisy.” The man regretted it, left all that, mixed with ordinary people in the markets, ate with the Israelites, and humbled himself. God revealed to their prophet: “Tell him: now you have found My pleasure.” Bilal ibn Sa'd said: “One of you sees a policeman and seeks God's refuge from him. He sees the worldly scholars who put on airs for people and long for leadership, and does not hate them, though they deserve hate more than that policeman.”" },
      { title: "Who is most knowing", body: "Someone asked the Prophet which deed is best. He said: “Avoiding the forbidden, and keeping your mouth moist with God's remembrance.” Which companion is best? “One who helps you when you remember God, and reminds you when you forget.” Which is worst? “One who does not remind you when you forget, and does not help you when you remember.” Who is most knowing? “The one who fears God most.” Tell us the best of us to sit with? “Those who, when seen, make you remember God.” Who is worst? He said: “O God, forgive.” They insisted, and he said: “Scholars, when they are corrupt.” He said: “The safest on the Day of Resurrection are those who thought most in this world. Those who laugh most in the next life are those who wept most in this. The happiest in the next life are those who grieved longest in this.”" },
      { title: "Ali's sermon", body: "Ali said in a sermon: “I pledge my word on it: no people's crop dries up on mindfulness, and no root thirsts on guidance. The most ignorant person is one who does not know his own worth. The most hateful to God is a man who scraped up knowledge and ran with it through the darkness of trouble. People like him, and the lowest, called him a scholar, though he never spent one sound day in knowledge. He gathered much, when a little that is enough is better than much that distracts. When he had drunk his fill of stale water and gathered much of no worth, he sat as a teacher to untangle what confused others. When a hard case came, he prepared the stuffing of his own opinion. He does not know if he is right or wrong. He rides ignorance and stumbles in the dark. He does not apologise for what he does not know, to be safe, nor bite on knowledge firmly, to gain. Blood weeps at him, and forbidden marriages are made lawful by his rulings. He is not able to answer what comes to him, nor fit for what was put in his hands. Such people deserve that wailing and weeping be made over them while they still live.”" },
      { title: "No jokes mixed in", body: "Ali said: “When you hear knowledge, hold it in, and do not mix it with joking, or hearts will spit it out.” One of the early Muslims said: “When a scholar laughs a laugh, he spits out a spit of knowledge.” It was said: “When a teacher has three things, the student's blessing is complete: patience, humility and good character. When a student has three things, the teacher's blessing is complete: reason, manners and good understanding.” In short, the scholars of the next life are never without the traits the Quran teaches, because they learn the Quran to act on it, not for leadership." },
      { title: "Faith before the Quran", body: "Ibn Umar said: “We lived a while when one of us was given faith before the Quran. A chapter would come down and he would learn its lawful and forbidden, its commands and prohibitions, and where he should stop in it. I have seen men given the Quran before faith. They read from the opening to the end, not knowing its commands, prohibitions or where to stop, scattering it like dry dates.” Another report: “We, the Prophet's Companions, were given faith before the Quran. After you will come people given the Quran before faith. They get its letters right and neglect its limits and rights. They say: we have read, who reads better than us? We know, who knows more than us? That is their share.” In another wording: “They are the worst of this community.”" },
      { title: "Five traits from five verses", body: "It was said five traits of the scholars of the next life come from five verses. Fear: “Only those of His servants who know truly fear God.” Humility: “humble before God, not selling God's signs for a small price.” Lowliness: “Lower your wing to the believers.” Good character: “By mercy from God you were gentle with them.” Doing without: “Those given knowledge said: woe to you, God's reward is better for whoever believes and does good.” When the Prophet recited “Whomever God wants to guide, He opens his breast to Islam,” he was asked what this opening is. He said: “When light is thrown into the heart, the breast opens and widens.” Is there a sign of it? “Yes: drawing back from the home of delusion, turning to the home of forever, and preparing for death before it comes.”" },
    ],
    closer: [
      { title: "God's days", body: "Sahl's term explains the whole sign. Knowing the rulings does not bring fear. Knowing what God did to peoples before us, His hidden punishments and hidden gifts, does." },
      { title: "Faith before the Quran", body: "Ibn Umar's contrast is about order. The Companions believed first and then learned each chapter to live by it. Later people recited all of it perfectly and lived by none." },
    ],
    distinction: ["Two kinds of reader in Ibn Umar's words", "Faith before the Quran", "Learns each chapter's commands and where to stop, and lives by them.", "The Quran before faith", "Gets every letter right and neglects its limits: “Who reads better than us?”"],
    misreading: "The sign is not gloominess. The same report praises people who laugh aloud at the breadth of God's mercy. What is blamed is the laughter of feeling safe from God, and chatter that empties knowledge from the heart.",
    reflection: "When people look at you, what do they remember?",
    audit: ["Does my knowledge include God's days?", "Do I mix what I teach with joking?", "Did I learn the Quran before faith, or faith before the Quran?", "Is my breast opened, by the Prophet's three signs?"],
    nodes: ["ulama-akhira", "khashya"],
    model: spectrum("Sahl's three scholars", "What each knows, and what it brings.", [["Knows God's command only", "The lawyers of rulings: no fear from this alone.", "balance"], ["Knows God only", "Ordinary believers.", "balance"], ["Knows God, His command and His days", "The truthful: fear and humility take them over.", "support"]]),
  }),
  makeChapter({
    id: 43, shortTitle: "Sign 10: knowing what spoils deeds", formalTitle: "The tenth sign: studying what spoils deeds and troubles hearts, and Hudhayfa, keeper of the secret",
    overview: "The tenth sign is that most of his study is about deeds and what spoils them, troubles the heart, stirs whispers and raises evil. Hudhayfa asked the Prophet about evil to avoid it, and became the keeper of the secret of the hypocrites. This knowledge has become a stranger.",
    thesis: "The root of religion is guarding against evil, and you cannot guard against what you do not know. The outward acts are near at hand; the work is in knowing what spoils them. The worldly scholars chase rare cases that never happen to them; the scholars of the next life study what happens to them every hour.",
    moves: [
      { title: "Know evil to avoid it", body: "The tenth sign is that most of his searching is about the knowledge of deeds, and what spoils them, troubles hearts, stirs whispers and raises evil. The root of religion is guarding against evil. As the verse says: “I learned evil not for evil but to guard against it; whoever does not know evil falls into it.” The outward acts are near, and the highest of them is keeping up remembrance of God with heart and tongue. The real matter is knowing what spoils and troubles them. That has many branches and details, and it is needed constantly by everyone on the road to the next life." },
      { title: "Rare cases for others", body: "The worldly scholars follow strange branches in judgments and verdicts. They tire themselves inventing cases that ages pass without happening. If they happen, they happen to others, not to them, and when they do, plenty of people can deal with them. They leave what sticks to them and recurs night and day in their thoughts, whispers and deeds. How far from happiness is someone who sells what his own self urgently needs for what someone else rarely needs! He prefers nearness and acceptance with people to nearness to God! His evil is that the idle children of the world call him excellent, exact, a scholar of fine points. His reward from God is that he does not even enjoy people's acceptance in this world; its pleasure is spoiled by the blows of time. Then he comes to the Day of Resurrection bankrupt, grieving at the profit of those who acted and the winning of those brought near. That is the clear loss." },
      { title: "Where al-Hasan learned it", body: "Al-Hasan al-Basri was the most like the prophets in his speech, and the nearest to the Companions in his way; all agree on that. Most of his talk was about the thoughts of hearts, the corruption of deeds, the whispers of the self, and the hidden, subtle traits of its desires. He was told: “Abu Sa'id, you speak in a way no one else does. Where did you take it from?” He said: “From Hudhayfa ibn al-Yaman.”" },
      { title: "Hudhayfa asked about evil", body: "Hudhayfa was asked: “You speak in a way none of the other Companions do. Where did you take it from?” He said: “The Prophet gave it to me especially. People used to ask him about good, and I asked him about evil, for fear of falling into it. I knew that knowledge of good would not pass me by.” Once he said: “I knew that whoever does not know evil does not know good.” In another wording: “They asked: messenger of God, what is the reward for doing this or that? They asked about the merits of deeds. I asked: messenger of God, what spoils this or that? When he saw me asking about the harms of deeds, he gave me this knowledge especially.”" },
      { title: "Keeper of the secret", body: "Hudhayfa was also given knowledge of the hypocrites, alone knowing hypocrisy and its causes and the fine points of trials. Umar, Uthman and the great Companions asked him about general and particular trials. He was asked about the hypocrites, and told how many were left without naming them. Umar asked him whether he knew any hypocrisy in him, and he cleared him. When Umar was called to a funeral prayer, he looked to see if Hudhayfa was there. If he was, he prayed; if not, he did not. Hudhayfa was called the keeper of the secret." },
      { title: "A stranger now", body: "So care for the heart's levels and states is the way of the scholars of the next life, since the heart is what travels to God's nearness. This field has become a faded stranger. When a scholar touches any of it, people find it strange and say: “This is preachers' decoration; where is the real research?” They think real research is the fine points of debate. The poet was right: “The roads are many and the road of truth is one; those who walk it are few. They are not known and their aims are not seen; they walk slowly, on purpose. People are heedless of what is meant for them; most of them are asleep to the way of truth.”" },
      { title: "Bitter medicine", body: "Most people lean only to what is easiest and suits their nature. The truth is bitter, hard to stand on, hard to grasp, and its road is rough, especially knowing the heart's traits and cleaning it of blamed character. That is like the pulling out of the soul, without end. Whoever does it is like someone drinking medicine and bearing its bitterness in hope of cure. He is like someone who has made his whole life a fast, bearing hardship so that his breaking of the fast comes at death. When will many want this road? It was said that in Basra there were a hundred and twenty preachers. Only three spoke of the knowledge of certainty, the states of hearts and the inner traits: Sahl al-Tustari, al-Subayhi and Abd al-Rahim. Countless crowds sat with the others, and with these three a few, rarely more than ten. The precious and rare suits only the few; what is given to everyone is cheap." },
    ],
    closer: [
      { title: "Knowing evil to know good", body: "Hudhayfa's reasoning is simple. Knowledge of good would come to him anyway; knowledge of what spoils good would not. So he asked about evil, and became the one the Companions asked." },
      { title: "Ten in the room", body: "The crowds went to the hundred and seventeen, and ten went to the three. Ghazali does not count the crowd as proof. The precious always has few buyers." },
    ],
    distinction: ["Two things a scholar can study", "What rarely happens to others", "Invented cases in judgments: earns the name of expert and nothing else.", "What happens to him every hour", "His own thoughts, whispers and the harms of his deeds: what Hudhayfa asked about."],
    misreading: "Asking about evil is not a morbid interest in sin. Hudhayfa asked in order to avoid it, and his knowledge made him the one the great Companions trusted.",
    reflection: "Pick one good deed you do regularly. Do you know what could spoil it?",
    audit: ["Do I study what I need, or what impresses?", "Do I know the harms that spoil my prayer?", "Would I ask about evil to avoid it, as Hudhayfa did?", "Am I in the crowd or among the ten?"],
    nodes: ["ulama-akhira", "afat-amal"],
    model: pair("Two kinds of question", "What the Companions asked, and what Hudhayfa asked.", [["The merits of deeds", "What is the reward for this? Most people asked this.", "balance"], ["The harms of deeds", "What spoils this? Hudhayfa asked, and was given the secret.", "support"]]),
  }),
  makeChapter({
    id: 44, shortTitle: "Sign 11: insight, not only books", formalTitle: "The eleventh sign: relying on insight, not on books or copying, and how books began",
    overview: "The eleventh sign is relying on his own insight and a clear heart, not on pages or copying what others say. Only the Prophet is followed without question. Ghazali tells how the early Muslims disliked writing books, when the first ones were made, and how the knowledge of certainty faded as theology and storytelling rose.",
    thesis: "Someone who only memorises is a vessel of knowledge, not a scholar. The Prophet is followed in everything, and the Companions because their acts show what they heard; everyone else's word may be taken or left. As theology and preaching spread, the name of scholar passed to debaters and storytellers, and the knowledge of the next life was folded away.",
    moves: [
      { title: "A vessel is not a scholar", body: "The eleventh sign is that he relies in his knowledge on his insight and what he grasps with a clear heart. He does not rely on pages and books, or on copying what he hears from others. The only one to be followed as such is the Prophet, in what he commanded and said. The Companions are followed because their acts show what they heard from him. When he follows the Prophet in accepting his words and acts, he should be eager to understand their secrets. The follower does the act because the Prophet did it, and it must have a secret. If he is content to memorise what is said, he is a vessel of knowledge, not a scholar. That is why it was said: “So-and-so is one of the vessels of knowledge.” He is not called a scholar if his work is memorising without seeing the wisdom and secrets." },
      { title: "Taken or left", body: "Whoever's heart has had the cover lifted and is lit by the light of guidance becomes himself one who is followed, and should not follow others blindly. So Ibn Abbas said: “There is no one whose knowledge is not partly taken and partly left, except the messenger of God.” He learned law from Zayd ibn Thabit and recitation from Ubayy ibn Ka'b, then differed from both in law and in recitation. One of the early Muslims said: “What comes to us from the Prophet we accept on our heads and eyes. What comes from the Companions we take some of and leave some. What comes from the next generation: they are men and we are men.”" },
      { title: "Why the Companions are above", body: "The Companions were above others because they witnessed the circumstances of the Prophet's life. Their hearts caught things grasped from circumstances, which set them right in ways that do not go into reports and words. The light of prophethood poured over them and mostly guarded them from error. If relying on what you hear from others is a copying that is not approved, relying on books and writings is further still." },
      { title: "Books came later", body: "Books and writings are new. None existed in the Companions' time or the early years of the next generation. They began after the year one hundred and twenty. By then all the Companions and most of the next generation had died, including Sa'id ibn al-Musayyib, al-Hasan and the best of that generation. The early ones disliked writing reports and composing books, so people would not be distracted from memorising, from the Quran, and from reflection and remembrance. They said: “Memorise as we memorised.”" },
      { title: "Even the Quran in one book", body: "That is why Abu Bakr and a group of Companions disliked writing the Quran in one volume. They said: “How can we do something the Prophet did not?” They feared people would rely on the written copy. They said: “Let the Quran be passed from one to another by teaching and reciting, so that is their work and care.” Then Umar and the other Companions advised writing it. They feared people would grow slack and lazy, and that a dispute might arise over a word or reading with no source to go back to. Abu Bakr's heart opened to it, and he gathered the Quran in one volume." },
      { title: "The first books", body: "Ahmad ibn Hanbal objected to Malik composing the Muwatta, saying: “He has started what the Companions did not do.” It is said the first book written in Islam was Ibn Jurayj's on reports and Quran commentary from Mujahid, Ata and the followers of Ibn Abbas in Mecca. Then Ma'mar ibn Rashid's in Yemen, gathering reported Sunnas of the Prophet. Then Malik's Muwatta in Medina. Then the Collection of Sufyan al-Thawri." },
      { title: "How the name moved", body: "In the fourth century, books of theology appeared, and there was much going into argument and refuting opinions. People leaned to it, and to stories and preaching with them. From that time the knowledge of certainty began to fade. After that, the knowledge of hearts, searching out the self's traits and Satan's tricks, became strange, and all but a few turned from it. The debating theologian was called a scholar, and the storyteller who decorated his words with rhyme was called a scholar. That was because ordinary people were their listeners and could not tell real knowledge from anything else. The Companions' lives and knowledge were not known to them, so they could not see how different these men were. The name of scholar stuck, and the title passed down from later to later. The knowledge of the next life was folded away. The difference between knowledge and talk was lost, except to the few. When asked whether so-and-so or so-and-so knew more, they said: “This one has more knowledge, and that one more talk.”" },
      { title: "Better to be silent", body: "So the few could tell knowledge from the ability to talk. That is how religion weakened in past centuries. What then of your time, Ghazali asks, when it has come to this: whoever objects openly is taken for mad. Better that a person busy himself with himself and keep quiet." },
    ],
    closer: [
      { title: "Not against books", body: "Ghazali wrote many books, and the Ihya is one. His point is not that books are bad, but that they came later and cannot replace understanding. A person who only has pages is a vessel." },
      { title: "They are men and we are men", body: "The saying sets an order. The Prophet is accepted without question, the Companions weighed with great respect, and everyone after them heard as equals." },
    ],
    distinction: ["Two things a person with knowledge can be", "A vessel", "Memorises what is said and passes it on, without seeing its wisdom.", "A scholar", "Follows the Prophet and seeks the secret behind each act, relying on his own insight."],
    misreading: "This sign does not let anyone ignore scholars and follow his own whims. It is about a heart already lit by guidance, and it keeps the Prophet above all, and the Companions above later people.",
    reflection: "Think of a practice you do only because you were told. Have you ever asked what its secret is?",
    audit: ["Am I a vessel or a scholar in what I know?", "Do I seek the wisdom behind the Prophet's acts?", "Do I rely on books where understanding is needed?", "Can I tell knowledge from talk?"],
    nodes: ["ulama-akhira", "basira"],
    model: chain("How the name of scholar moved", "Ghazali's history of books and talk.", [["The Companions", "Memorised; disliked even writing the Quran in one volume at first.", "support"], ["The first books", "After the year 120: Ibn Jurayj, Ma'mar, Malik, Sufyan.", "balance"], ["The fourth century", "Books of theology, argument, storytelling.", "warning"], ["The name moved", "Debaters and storytellers called scholars; the next life's knowledge folded away.", "warning"]]),
  }),
  makeChapter({
    id: 45, shortTitle: "Sign 12: wary of what is new", formalTitle: "The twelfth sign: guarding against new things in religion, even when most people agree on them",
    overview: "The twelfth sign is being very wary of new things in religion, even if most people have agreed on them. The most knowing person of any age is the one most like the Companions. Ghazali lists practices of his day that were once condemned, tells how Iblis failed with the Companions and succeeded later, and ends the twelve signs.",
    thesis: "What is good today was often bad in the Companions' time: decorated mosques, debate, singing the Quran, obsessive purity. Whatever was added after the Companions beyond need is play. Sinful ordinary people are better off than ignorant people who think they are scholars, because the first repent and the second never do.",
    moves: [
      { title: "Most like the Companions", body: "The twelfth sign is being very wary of new things, even if most people agree on them. He is not fooled by everyone agreeing on what was added after the Companions. He is eager to search out the Companions' states, lives and deeds, and what they cared most about. Was it teaching, writing, debating, judging, governing, running endowments and wills, eating orphans' money, and keeping company with rulers? Or was it fear, sadness, thought, striving, watching outside and inside, avoiding sin small and great, and eagerness to know the self's hidden desires and Satan's tricks? Be certain of this. The most knowing person of the age, and nearest to the truth, is the one most like the Companions and most familiar with the early Muslims' way. Religion was taken from them." },
      { title: "The best follower", body: "That is why Ali, when told “You differed from so-and-so,” said: “The best of us is the one who follows this religion most.” So one should not mind differing from the people of his time to agree with the people of the Prophet's time. People formed opinions about what they were doing because their nature leaned to it, and could not bring themselves to admit it would keep them from the Garden. So they claimed there was no other way to it. Al-Hasan said: “Two new things came into Islam. One is a man of bad opinion who claims the Garden is for those who think as he does. The other is a pampered man who worships the world, is angry for it and pleased for it and seeks it. Throw them both into the Fire. A man may wake in this world between a pampered man calling him to his world and a man of desire calling him to his desire. God protects him from both, and he longs for the early Muslims, asks about their deeds and follows their tracks. He is open to a great reward. So be like that.”" },
      { title: "Every new thing", body: "Ibn Mas'ud said, and it is also reported from the Prophet: “There are only two things, speech and guidance. The best speech is God's speech and the best guidance is the guidance of God's messenger. Beware of new things; the worst matters are the new ones, every new thing is an innovation, and every innovation is misguidance. Do not let the time grow long for you so that your hearts harden. Whatever is coming is near. The far is only what will not come.” The Prophet said in a sermon: “Good news for one whose own faults keep him from others' faults, and who spends from money earned without sin. He mixes with people of understanding and wisdom, and avoids people of error and sin. Good news for one who is humble in himself, good in character, sound inside, and keeps his evil from people. Good news for one who acts on what he knows, spends the extra of his money, and holds back the extra of his words. He finds the Sunna wide enough and does not pass it into innovation.”" },
      { title: "The careful one wins now", body: "Ibn Mas'ud said: “Good guidance at the end of time is better than many deeds.” He said: “You are in a time when the best of you is quick in matters. After you will come a time when the best is careful and slow, because of the many doubtful things.” He was right. Whoever in this time is not careful, and agrees with the crowd and plunges in with them, is ruined as they are. Hudhayfa said: “Stranger still, what you count good today was bad in a time now gone. What you count bad today will be good in a time to come. You will be well as long as you know the truth, and the scholar among you is not taken lightly.”" },
      { title: "Good things that were bad", body: "He was right. Most of what is counted good in these times was bad in the Companions' time. Among the finest good deeds of Ghazali's day is decorating mosques, covering them, spending huge sums on fine details of building, and spreading rich carpets in them. Spreading even reed mats in a mosque used to be counted an innovation; it is said al-Hajjaj started it. The early ones rarely put anything between themselves and the dust. So too, the fine points of argument and debate are among the most honoured sciences of the time. They think them among the greatest acts of nearness, though they used to be counted bad. So too singing the Quran and the call to prayer. So too going to extremes in cleanliness and obsessing over purification, imagining distant ways clothes could be unclean, while being careless about whether food is lawful." },
      { title: "Desire following knowledge", body: "Ibn Mas'ud was right: “You are today in a time when desire follows knowledge. A time will come when knowledge follows desire.” Ahmad ibn Hanbal said: “They left knowledge and turned to rarities. How little knowledge they have!” Malik said: “People did not use to ask about these things as they do today. The scholars did not say forbidden and lawful. I found them saying recommended and disliked.” He meant they looked into the fine points of disliked and recommended; the forbidden was plainly foul. Hisham ibn Urwa said: “Do not ask them today about what they invented themselves; they have prepared an answer. Ask them about the Sunna; they do not know it.”" },
      { title: "Check it against the reports", body: "Abu Sulayman al-Darani said: “Someone inspired with some good should not act on it until he hears it in the reports. Then he praises God that it agrees with what is in him.” He said this because invented opinions have reached people's ears and caught in hearts, and may cloud the heart's clarity, so that falsehood looks true. So one takes care by seeking support from the reports. When Marwan put a pulpit in the prayer ground for the Eid prayer, Abu Sa'id al-Khudri stood and said: “Marwan, what is this innovation?” Marwan said: “It is not an innovation. It is better than what you know. The people have grown many, and I wanted my voice to reach them.” Abu Sa'id said: “By God, you will never bring something better than what I know. By God, I will not pray behind you today.” He objected because the Prophet used to lean on a bow or staff in the Eid and rain sermons, not on a pulpit." },
      { title: "Overthrowing the kingdom", body: "A famous report says: “Whoever brings into our religion what is not of it, it is rejected.” Another: “Whoever cheats my community, God's curse is on him, and the angels' and all people's.” What is cheating your community? “To invent an innovation and make people follow it.” The Prophet said: “God has an angel who calls every day: whoever goes against the Sunna of God's messenger will not receive his intercession.” Compare someone who harms religion by an innovation against the Sunna with someone who commits a sin. The first is like someone who rebels against a king by overthrowing his kingdom, compared with someone who disobeys an order in one task. The second may be forgiven; the first is not. A scholar said: “What the early Muslims spoke of, silence about it is neglect. What they kept silent about, speaking of it is pretence.” Another said: “The truth is heavy. Whoever passes it does wrong, whoever falls short of it is helpless, and whoever stops with it has enough.” The Prophet said: “Keep to the middle way, which the high come back to and the low rise to.”" },
      { title: "Iblis and his troops", body: "Ibn Abbas said: “Misguidance has a sweetness in its people's hearts.” God says: “Leave those who took their religion as play and amusement.” He also says: “Is one whose bad deed was made to look good to him, so he sees it as good...?” So everything added after the Companions beyond need is play and amusement. It is told that Iblis sent his troops out in the Companions' time. They came back worn out. He asked what happened. They said: “We have never seen people like these. We get nothing from them, and they have exhausted us.” He said: “You cannot manage them. They kept company with their Prophet and saw their Lord's revelation come down. But people will come after them from whom you will get what you want.”" },
      { title: "The next generations", body: "When the next generation came, he sent his troops, and they came back with heads down. They said: “We have never seen anything stranger. We get a sin from them now and then, but at the end of the day they start asking forgiveness, and God changes their bad deeds into good.” He said: “You will get nothing from these, because their oneness is sound and they follow their Prophet's Sunna. But after them will come people who will delight your eyes. You will play with them and lead them by the reins of their desires wherever you like. If they ask forgiveness they will not be forgiven, and they will not repent so that God changes their bad deeds to good.” After the first centuries people came among whom he spread desires and made innovations look fine. They made them lawful and took them as religion, and did not ask forgiveness or repent. So enemies were set over them, who led them where they wished." },
      { title: "How was Iblis heard?", body: "You may ask how the teller knew what Iblis said, when he never saw Iblis or heard him. The people of hearts are shown the secrets of the unseen kingdom. Sometimes it is by inspiration, coming to them from where they do not know. Sometimes by a true dream. Sometimes while awake, by meanings shown in images, as in sleep. This last is the highest level, and one of the high levels of prophethood, as the true dream is one of forty-six parts of prophethood. Beware of your share of this knowledge being the denial of whatever goes past your own limit. That is how the clever scholars who think they have mastered the sciences of reason were ruined. Ignorance is better than a mind that leads you to deny such things to God's friends. Whoever denies it to the friends must deny it to the prophets, and has left religion entirely." },
      { title: "Ignorance of one's ignorance", body: "One of the knowers said: “The Abdal went off to the ends of the earth and hid from the crowds. That is because they cannot bear to look at the scholars of the time. To them those scholars are ignorant of God, while they think themselves scholars, and so do the ignorant.” Sahl al-Tustari said: “Among the greatest sins are ignorance of one's ignorance, looking at the crowd, and listening to the heedless.” Any scholar who plunges into the world should not be listened to. He should be suspected in all he says, since everyone dives into what he loves and pushes away what does not suit his beloved. God says: “Do not obey one whose heart We have made heedless of Our remembrance, who follows his desire, and whose affair is lost.”" },
      { title: "The sinner and the false scholar", body: "Sinful ordinary people are better off than those ignorant of the road of religion who believe they are scholars. The sinful ordinary person admits his shortcoming, so he asks forgiveness and repents. The ignorant one thinks he is a scholar. He thinks the sciences he is busy with, which are his means to the world, are the road of religion. So he does not repent or ask forgiveness. He keeps at it until death. This has taken over most people, except those God protects, and hope of setting them right is cut off. So the safest course for a careful religious person is solitude, as the Book of Solitude will explain." },
      { title: "Selling a sword to robbers", body: "Yusuf ibn Asbat wrote to Hudhayfa al-Mar'ashi: “What do you think of someone left with no one to remember God with? He cannot do it without being sinful or his remembering being a sin?” That is because he does not find its people. He was right. Mixing with people never escapes backbiting, hearing backbiting, or keeping silent at wrong. At best, a person gives or gets knowledge. If he thought about it, he would see his teaching is not free of showing off and wanting followers and leadership. The one who learns wants to make it a tool for the world and a means to evil. So the teacher helps him, like someone who sells a sword to highway robbers. Knowledge is like a sword. Its fitness for good is like the sword's for fighting in God's cause. So he may not sell it to someone whose circumstances show he means to use it for robbery." },
      { title: "Twelve signs, and three men", body: "These are twelve signs of the scholars of the next life. Each gathers a set of the early scholars' traits. Be one of two men: either you have these traits, or you admit your shortcoming and confess it. Beware of being the third, who deceives himself by swapping the world's tools for religion. He likens the lives of the idle to the lives of the firmly grounded scholars, and joins, by his ignorance and his denial, the ruined and hopeless. Ghazali ends: we seek refuge in God from Satan's tricks, by which the crowds were ruined. We ask Him to make us of those whom this world's life does not deceive, and whom the Deceiver does not deceive about God." },
    ],
    closer: [
      { title: "Two men and a third", body: "The twelve signs end with permission to fall short. You may lack them, as long as you admit it. The ruined one is the man who lacks them and calls what he has religion." },
      { title: "Better than the false scholar", body: "The comparison is startling on purpose. The sinner who knows he sins is nearer to repentance than the scholar who thinks his worldly skill is the road to God." },
    ],
    distinction: ["Two kinds of wrongdoer", "The sinful ordinary person", "Knows he falls short, so he asks forgiveness and repents.", "The ignorant who thinks he is a scholar", "Takes his worldly tools for religion, so he never repents, until death."],
    misreading: "This sign is not against every new thing in life. Ghazali says what goes beyond need; he himself accepts written books and the gathered Quran, which the Companions came to agree on. The danger is new things in religion taken as religion.",
    reflection: "Choose one of the twelve signs you lack. Can you admit it plainly, as the second man does?",
    audit: ["Do I measure practices against the Companions, or against the crowd?", "Do I deny what goes past my own limits?", "Am I the sinner who repents or the false scholar who never does?", "Would I sell a sword to a robber?"],
    nodes: ["ulama-akhira", "bida"],
    model: spectrum("Three men at the end", "Ghazali's closing choice.", [["Has the signs", "The scholar of the next life.", "support"], ["Admits he lacks them", "Confesses his shortcoming; still safe.", "balance"], ["Swaps the world's tools for religion", "Deceives himself and joins the ruined.", "warning"]]),
  }),
  makeChapter({
    id: 46, shortTitle: "The excellence of reason", formalTitle: "The excellence of reason: why it hardly needs proving, and what the reports say",
    overview: "The last chapter turns to reason, the source of knowledge. Its excellence is almost self-evident: even the strongest animal is wary of a human. Ghazali then gathers the verses and reports. God called it light, the first thing He created, and people rise in the next life by the measure of their reason.",
    thesis: "Knowledge comes from reason as fruit from a tree, light from the sun and sight from the eye. The reasonable person is the one who obeys God, however poor he looks; the ignorant one disobeys God, however grand he looks. People's deeds are only as much as the reason God gave them, and they are rewarded for their deeds.",
    moves: [
      { title: "Tree, sun and eye", body: "This hardly needs effort to show, especially since the excellence of knowledge has already been shown. Reason is the spring, the rising place and the foundation of knowledge. Knowledge comes from it as fruit from a tree, light from the sun, and sight from the eye. How could the means to happiness in both worlds not be noble? Even an animal, with its little discernment, is in awe of reason. The biggest, fiercest, strongest animal, when it sees a human shape, is wary of it, sensing that he can master it by the cunning he alone has." },
      { title: "Why elders are honoured", body: "That is why the Prophet said: “The elder among his people is like the prophet among his community.” It is not for his wealth, size or strength, but for his greater experience, which is the fruit of his reason. So you see Turks, Kurds, rough desert Arabs and other peoples, though near the level of animals, honour their elders by nature. When many enemies set out to kill the Prophet and their eyes fell on him and took in his noble face, they were in awe of him. The light of prophethood shone on his face, though it was hidden inside him as reason is hidden. The excellence of reason is known by necessity. Ghazali's aim here is to give the verses and reports about it." },
      { title: "Light, spirit and life", body: "God called it light: “God is the light of the heavens and the earth; His light is like a niche.” He called the knowledge that comes from it spirit, revelation and life: “So We have revealed to you a spirit from Our command.” He also said: “Is one who was dead, and We gave him life and made for him a light to walk by among people...?” Wherever light and darkness are mentioned, He means knowledge and ignorance, as in: “He brings them out of the darknesses into the light.”" },
      { title: "Monkeys and swine", body: "The Prophet said: “People, understand from your Lord and urge one another to reason. You will know what you are commanded and forbidden. Be sure it will help you before your Lord. The reasonable one is he who obeys God, even if he is ugly to look at, of small worth, low in standing and shabby. The ignorant one is he who disobeys God, even if he is handsome, important, high in standing, well dressed and eloquent. Monkeys and swine have more reason in God's sight than one who disobeys Him. Do not be fooled by how the people of the world honour them; they are the losers.”" },
      { title: "The first thing created", body: "The Prophet said: “The first thing God created was reason. He said to it: come forward, and it came forward. Then He said: go back, and it went back. Then God said: By My might and majesty, I have created nothing more honoured by Me than you. By you I take, by you I give, by you I reward, and by you I punish.” You may ask: if reason is a quality, how was it created before bodies? If it is a substance, how can a substance stand by itself without taking up space? Ghazali says this belongs to the knowledge of unveiling, and does not fit the knowledge of practice, which is the present aim." },
      { title: "How is his reason?", body: "Anas said some people praised a man before the Prophet, going to great lengths. He asked: “How is the man's reason?” They said: “We tell you of his effort in worship and all kinds of good, and you ask about his reason?” He said: “The fool does more harm by his folly than the wicked man by his wickedness. People will rise tomorrow in the levels of nearness to their Lord by the measure of their reason.” Umar reported: “No man has gained anything like the grace of reason that guides him to guidance and turns him back from ruin. A person's faith is not complete, nor his religion straight, until his reason is complete.”" },
      { title: "The pillar of the believer", body: "The Prophet said: “A man reaches by his good character the level of one who fasts and prays at night. But his good character is not complete until his reason is complete. Then his faith is complete, he obeys his Lord and disobeys his enemy Iblis.” Abu Sa'id reported: “Everything has a pillar, and the believer's pillar is his reason. His worship is by the measure of his reason. Have you not heard the wicked in the Fire say: If we had listened or reasoned, we would not be among the people of the blaze?” Umar asked Tamim al-Dari: “What is leadership among you?” He said: “Reason.” Umar said: “You are right. I asked the Prophet as I asked you, and he answered as you did. Then he said: I asked Gabriel what leadership is, and he said: reason.”" },
      { title: "The mount of a person", body: "Al-Bara' said questions multiplied on the Prophet one day, and he said: “People, everything has a mount, and a person's mount is reason. The best of you in guiding and knowing proof is the best of you in reason.” Abu Hurayra said that when the Prophet came back from Uhud he heard people saying: “So-and-so was braver than so-and-so; so-and-so did what so-and-so did not.” He said: “You have no knowledge of that. They fought by the measure of reason God gave them. Their help and intention were by the measure of their reason. Those who fell fell at many levels. On the Day of Resurrection they will share out their places by their intentions and their reason.”" },
      { title: "Only as much as they were given", body: "Al-Bara' reported: “The angels strove in obeying God by reason, and the believers among Adam's children strive by the measure of their reason. The one who does most in obeying God has most reason.” A'isha asked: “Messenger of God, by what do people surpass each other in this world?” He said: “By reason.” “And in the next?” “By reason.” “Are they not rewarded for their deeds?” He said: “A'isha, did they do anything except by the measure of reason God gave them? Their deeds were by what they were given of reason, and they are rewarded by what they did.”" },
      { title: "Tool, mount and tent", body: "Ibn Abbas reported: “Everything has a tool and an equipment, and the believer's tool is reason. Everything has a mount, and a person's mount is reason. Everything has a pillar, and religion's pillar is reason. Every people has a goal, and the goal of God's servants is reason. Every people has a caller, and the worshippers' caller is reason. Every trader has goods, and the strivers' goods are reason. Every household has a keeper, and the keeper of the houses of the truthful is reason. Every ruin has its building, and the building of the next life is reason. Everyone has a descendant by whom he is remembered, and the truthful are remembered by reason. Every journey has a tent, and the believers' tent is reason.” He said: “The dearest believer to God is one who tires himself in obeying God and gives sincere advice to His servants. He completes his reason, advises himself, sees and acts on it all his life, and so succeeds.” He also said: “The most complete of you in reason is the one who fears God most and looks best into what He commanded and forbade. That holds even if he does least of the voluntary.”" },
    ],
    closer: [
      { title: "Reason is obedience", body: "The report about monkeys and swine defines reason by what it does. However clever or grand, the one who disobeys God has less reason in God's sight than an animal." },
      { title: "By their reason", body: "The Uhud report looks past what everyone saw on the battlefield. Who was braver is unknown. What counts is the reason and intention behind each stroke." },
    ],
    distinction: ["Two kinds of person in the report", "The reasonable", "Obeys God, even if ugly, poor and low.", "The ignorant", "Disobeys God, even if handsome, rich, high and eloquent."],
    misreading: "These reports do not praise cleverness at argument. They tie reason to fear of God, obedience and knowing what is commanded. Ghazali will say at the end that some Sufis blamed “reason” only because the word had been moved to debate.",
    reflection: "The Prophet asked about a praised man: “How is his reason?” If someone asked it about you, what would the answer be?",
    audit: ["Does my reason lead me to obey God?", "Do I judge people by their looks or their obedience?", "Is my good character complete, by the measure of my reason?", "What is the mount I ride to God?"],
    nodes: ["aql"],
    model: chain("What reason is to knowledge", "Ghazali's three pictures.", [["The tree", "Knowledge is its fruit.", "support"], ["The sun", "Knowledge is its light.", "support"], ["The eye", "Knowledge is its sight.", "support"], ["The measure", "People rise in the next life by the measure of their reason.", "support"]]),
  }),
  makeChapter({
    id: 47, shortTitle: "Four meanings of reason", formalTitle: "The reality of reason and its kinds: one word with four meanings",
    overview: "People disagreed about what reason is because they did not notice that the word has four meanings, like the word for “eye” in Arabic. Ghazali separates them: an inborn instinct, the self-evident truths a child grasps, knowledge from experience, and the strength to see consequences and master desire.",
    thesis: "The instinct is the root; the self-evident truths are its nearest branch; experience grows from both; and mastering desire is the final fruit. The first two come by nature, the last two by effort. The truths are hidden in the instinct from birth, like water under the ground, and remembering God's covenant is drawing them out.",
    moves: [
      { title: "One word, four meanings", body: "People disagreed about the definition and reality of reason. Most did not notice that the word is used for different meanings, and that is what made them disagree. The truth that lifts the cover is that reason is a word shared by four meanings, as the Arabic word for eye is used for several things. So one should not look for one definition for all of them, but explain each by itself." },
      { title: "First: the instinct", body: "The first is the quality that sets a human apart from other animals. By it he is ready to take in theoretical knowledge and manage subtle crafts of thought. Al-Harith al-Muhasibi meant this when he defined reason as “an instinct by which one is made ready to grasp theoretical knowledge.” It is as if it were a light thrown into the heart that prepares it to grasp things. Whoever denies this and reduces reason to self-evident knowledge is unfair. A person who is unaware of knowledge, or asleep, is still called reasonable, because the instinct is in him though the knowledge is not." },
      { title: "The donkey and the stone", body: "Life is an instinct by which a body is ready for chosen movement and sensing. Reason is an instinct by which some living beings are ready for theoretical knowledge. Suppose one said man and donkey do not differ in instinct, but God simply creates knowledge in man by His usual way and not in the donkey. Then one could equally say the donkey and a stone do not differ in life, but God creates certain movements in the donkey. If the donkey were a dead stone, God could still create in it every movement we see. We must say the donkey differs from the stone by an instinct called life. So man differs from animals in grasping knowledge by an instinct called reason." },
      { title: "The mirror and the eye", body: "It is like a mirror, which differs from other bodies in showing forms and colours by a quality of its own, its polish. It is like the eye, which differs from the forehead in qualities that make it ready to see. This instinct is to knowledge as the eye is to seeing. The Quran and the law, in leading this instinct to knowledge, are to it as sunlight is to eyesight." },
      { title: "Second: self-evident truths", body: "The second is the knowledge that appears in a child old enough to tell things apart: that possible things are possible and impossible things impossible. For example, that two is more than one, and one person cannot be in two places at once. Some theologians meant this when they defined reason as some self-evident knowledge, such as the possible being possible and the impossible impossible. This is also right in itself, since such knowledge exists and is plainly called reason. What is wrong is to deny the instinct and say only this knowledge exists." },
      { title: "Third: experience; fourth: mastery", body: "The third is knowledge gained from experience of how things go. Someone seasoned by experience and trained by life is usually called reasonable, and someone without it is called dull, green and ignorant. The fourth is when the instinct's strength reaches the point of knowing the consequences of things, and crushing and mastering the desire that calls to quick pleasure. When someone has this strength he is called reasonable, because his stepping forward and holding back follow what the consequences require, not quick desire. This too is special to humans." },
      { title: "Root, branch and fruit", body: "The first is the foundation, root and spring. The second is the branch nearest to it. The third is a branch of the first two, since experience is gained by the strength of the instinct and self-evident knowledge. The fourth is the last fruit and the final goal. The first two come by nature, the last two by effort. So Ali said: I saw that reason is two, the inborn and the heard. The heard is no use without the inborn, just as the sun is no use when the eye's light is blocked." },
      { title: "Which the reports mean", body: "The first is meant by the Prophet's words: “God created nothing more honoured by Him than reason.” The last is meant by: “When people come near by the doors of good and good deeds, come near by your reason.” It is also meant by his words to Abu al-Darda: “Grow in reason and you will grow in nearness to your Lord.” He asked: “How can I?” The Prophet said: “Avoid what God forbade and do what God required, and you will be reasonable. Do good deeds, and you will grow in this world in height and honour, and in the next win nearness and honour from your Lord.”" },
      { title: "The reasonable is the mindful", body: "Sa'id ibn al-Musayyib said Umar, Ubayy ibn Ka'b and Abu Hurayra went in to the Prophet and asked: “Who is the most knowing of people?” He said: “The reasonable.” “The most devoted?” “The reasonable.” “The best?” “The reasonable.” They said: “Is not the reasonable one whose manliness is complete, whose eloquence shows, whose hand is generous and whose standing is great?” He recited: “All that is only the enjoyment of this world's life, and the next life with your Lord is for the mindful.” He said: “The reasonable one is the mindful, even if he is low and humble in this world.” In another report: “The reasonable one is he who believes in God, believes His messengers and obeys Him.”" },
      { title: "A name for the instinct", body: "The word probably belongs first, in the language and in use, to the instinct. It was used for the kinds of knowledge because they are its fruit, as a thing is known by its fruit. So it is said: knowledge is fear of God, and the scholar is one who fears God, since fear is knowledge's fruit. Then the word is almost a figure of speech for anything other than the instinct. But the aim is not to study language. The point is that all four kinds exist and the name is used for all. There is no disagreement about any of them except the first, and the truth is that it exists and is the root." },
      { title: "Water under the ground", body: "These kinds of knowledge are as if contained in the instinct from birth. They appear when some cause brings them out, as if they were not something coming from outside but were hidden in it and came out. It is like water in the earth: it appears when a well is dug, gathers and is seen, not because something new is brought to it. So too oil in almonds and rose water in roses. That is why God spoke of the covenant. He said: “When your Lord took from the children of Adam, from their backs, their descendants, and made them testify of themselves: Am I not your Lord? They said: yes.” This means the testimony of their souls, not their tongues. With tongues, once tongues and persons existed, they split into those who admit and those who deny." },
      { title: "Remembering what was always there", body: "God says: “If you ask them who created them, they will say: God.” That is, if you look at their states, their souls and insides testify to it. God speaks of “the nature God made people with.” Every human is made with faith in God, and even with knowing things as they are. That means it is as if contained in them because they are so ready to grasp it. Since faith is set in souls by nature, people split in two. Some turned away and forgot: the unbelievers. Some turned their thoughts and remembered, like someone who carried a testimony, forgot it through heedlessness, and then recalled it. So God says: “that they may remember,” and “that people of understanding may remember.” He says: “remember God's blessing on you and His covenant,” and “We have made the Quran easy to remember; is there anyone who will remember?”" },
      { title: "The blind man and the pots", body: "Calling this remembering is not far-fetched. Remembering is of two kinds. One is recalling a form that was present in the heart and then went away. The other is recalling a form contained in it by nature. These truths are plain to someone who looks with the light of insight. They are heavy for someone who finds comfort only in hearing and copying, not in unveiling and seeing. He stumbles over such verses and strains to explain away remembering as the souls' testimony. He imagines contradictions in the reports and verses, and may come to look down on them as incoherent. He is like a blind man who enters a house and trips over the pots laid out in it. He says: “Why are these pots not taken off the path and put in their places?” He is told: “They are in their places. The fault is in your sight.”" },
      { title: "The blind rider", body: "The fault of insight is like that, and worse. The soul is like the rider and the body like the horse, and a blind rider is worse than a blind horse. Inner insight is like outer sight. So God said: “The heart did not lie about what it saw.” He also said: “So We showed Abraham the kingdom of the heavens and the earth.” He called its opposite blindness: “It is not the eyes that go blind, but the hearts in the breasts.” He also said: “Whoever is blind in this world will be blind in the next, and further astray.” Of the things shown to the prophets, some were by sight and some by insight, and all were called seeing. In short, whoever's inner insight is not sharp catches only religion's shells and images, not its kernel and truths. These are the kinds of thing the name reason is used for." },
    ],
    closer: [
      { title: "The argument disappears", body: "Once the four meanings are pulled apart, the old dispute ends. Al-Muhasibi and the theologians were each right about a different meaning. The only mistake was denying the others." },
      { title: "Water already there", body: "The well does not bring water to the ground; it lets it out. Ghazali's picture of learning is the same: the truths were set in the soul, and teaching is digging." },
    ],
    distinction: ["Two ways reason comes", "By nature", "The instinct, and the self-evident truths that appear in a child: the root and its nearest branch.", "By effort", "Experience, and the strength to see consequences and master desire: the branch and the final fruit."],
    misreading: "Ghazali does not say faith comes from arguments. He says it is set in the soul by nature, and that the unbeliever has forgotten what he knew. Reason's work is remembering, not inventing.",
    reflection: "Which of the four meanings do you mean when you call someone clever? Which does God value most?",
    audit: ["Do I have the fourth kind: seeing consequences and mastering desire?", "Is my learning digging a well, or pouring water on the ground?", "Do I blame the pots when the fault is in my sight?", "What have I forgotten that my soul once testified to?"],
    nodes: ["aql", "fitra"],
    model: chain("One word, four meanings", "From root to fruit.", [["The instinct", "What sets humans apart; ready for knowledge. The root.", "support"], ["Self-evident truths", "Two is more than one; one body, one place. The nearest branch.", "balance"], ["Experience", "Knowledge from how things go.", "balance"], ["Mastery", "Seeing consequences and crushing desire. The fruit and goal.", "support"]]),
  }),
  makeChapter({
    id: 48, shortTitle: "How people differ in reason", formalTitle: "How souls differ in reason, and why some Sufis blamed it",
    overview: "People differ in three of the four kinds of reason, but not in self-evident truths. The instinct itself grows like the dawn until about forty, and differs between people as eyesight does. The prophets are like oil that almost shines with no fire. Ghazali ends the book by explaining why some Sufis spoke against reason.",
    thesis: "Whoever denies that people differ in reason has left reason, and whoever thinks the Prophet's reason was like a villager's is lower than the villager. Some understand by themselves, some need teaching, and some teaching cannot help, as some ground gushes springs, some needs digging, and some is dry. The light of insight cannot be blamed, since by it the truth of the law itself is known.",
    moves: [
      { title: "Where people differ", body: "People disagreed about whether reason differs between people. There is no point reporting the views of those who achieved little; better to state the truth plainly. People differ in all four kinds except the second, the self-evident knowledge that the possible is possible and the impossible impossible. Whoever knows two is more than one also knows a body cannot be in two places. He knows one thing cannot be both eternal and made in time, and so on for all he grasps with no doubt." },
      { title: "Mastering desire", body: "In the fourth kind, the strength to crush desires, people plainly differ, and even one person differs over time. This is sometimes because desires differ: a reasonable person can leave some desires and not others. A young man may be unable to leave adultery, and when older and more complete in reason he can. But the desire for show and leadership grows stronger with age, not weaker. It may also be because knowledge of the desire's harm differs. A doctor can keep away from some harmful foods where someone of equal reason who is not a doctor cannot, though he believes in general they harm. The doctor's fuller knowledge makes his fear stronger. Fear is a soldier of reason and its weapon for crushing desires." },
      { title: "The real scholar resists", body: "So the scholar can leave sins more easily than the ignorant, because he knows their harm better. Ghazali means the real scholar, not the men of fine gowns and empty talk. If the difference comes from desire, it is not a difference in reason. If it comes from knowledge, that kind of knowledge has also been called reason, since it strengthens the instinct. It may also come from the instinct alone: when it is stronger, it crushes desire more." },
      { title: "Experience and the dawn", body: "In the third kind, knowledge from experience, people plainly differ in how often they are right and how quickly they grasp. The cause is either the instinct or practice. In the first, the root, the instinct, the difference cannot be denied. It is like a light rising on the soul. Its dawn and first shining come at the age of discernment. Then it keeps growing, by hidden steps, until it is complete near forty. It is like the dawn's light, whose beginnings are so faint they are hard to see, and which grows until it is complete when the sun's disc rises." },
      { title: "The Prophet's reason", body: "Differences in the light of insight are like differences in eyesight; one can tell a man with weak eyes from a sharp-eyed one. God's way in all His creation is to bring things into being by steps. Even desire does not appear in a boy all at once at puberty, but little by little, and so with all powers and qualities. Whoever denies that people differ in this instinct has slipped out of the bond of reason. Whoever thinks the Prophet's reason was like that of some villager or rough desert dweller is himself lower than any villager." },
      { title: "Oil that almost shines", body: "How can anyone deny differences in the instinct? Without them people would not differ in understanding. They would not divide into three. There are the dull, who understand only after long effort by the teacher, and the sharp, who understand at the least hint. There are the complete, from whose own souls the truths of things spring without teaching. As God says: “Its oil would almost shine even if no fire touched it; light upon light.” That is like the prophets. Hidden matters become clear inside them without learning or hearing. This is called inspiration. The Prophet described it: “The Holy Spirit breathed into my heart. Love whom you will, for you will leave him. Live as you will, for you will die. Do what you will, for you will be repaid for it.”" },
      { title: "Knowing is not being", body: "This way the angels inform the prophets differs from open revelation, which is hearing a voice with the ear and seeing the angel with the eye. That is why this was described as breathing into the heart. The levels of revelation are many, and going into them does not suit the knowledge of practice; it belongs to unveiling. Do not think knowing the levels of revelation requires the office of revelation. A doctor can know the levels of health while ill, and a sinful scholar the levels of uprightness while lacking them. Knowledge is one thing and the existence of what is known is another. Not everyone who knows prophethood and sainthood is a prophet or a saint, and not everyone who knows the fine points of mindfulness and caution is mindful." },
      { title: "Springs, wells and dry ground", body: "People divide into those who wake up and understand by themselves, those who understand only by being alerted and taught, and those whom neither teaching nor alerting helps. This is like ground. Some gathers water until it grows strong and bursts into springs by itself. Some needs digging for the water to come out into channels. Some is dry, and digging does not help. That is because the substance of the ground differs. So souls differ in the instinct of reason." },
      { title: "Grains of sand", body: "The reports also show that reason differs. Abd Allah ibn Salam asked the Prophet a long question, ending with a description of the greatness of the Throne. The angels said: “Our Lord, have You created anything greater than the Throne?” He said: “Yes, reason.” They asked: “How great is it?” He said: “It cannot be encompassed. Do you know the number of grains of sand?” They said no. God said: “I created reason in kinds as many as the grains of sand. Some people were given one grain, some two, some three or four, some a measure, some a camel-load, and some more than that.”" },
      { title: "Why some Sufis blamed reason", body: "You may ask: why do some Sufis blame reason and what is reasoned? The reason is that people moved the name of reason to argument and debate with refutations and forced conclusions, which is the craft of theology. The Sufis could not persuade them that they had used the name wrongly, since it would not leave their hearts after being on everyone's tongue and settled there. So they blamed “reason”, meaning what those people called by the name." },
      { title: "The light that cannot be blamed", body: "As for the light of insight by which God is known and the truth of His messengers is known, how could it be blamed? God has praised it. If it were blamed, what would be praised after it? If the law is what is praised, how was the truth of the law known? If it was known by a blamed reason that cannot be trusted, then the law would be blamed too. Ghazali pays no attention to someone who says it is grasped by the eye of certainty and the light of faith, not by reason. By reason he means what that person means by the eye of certainty and the light of faith. It is the inner quality that sets humans apart from animals, by which they grasp the truth of things. Most of this confusion came from people who sought truths from words, and stumbled because people's use of words stumbles. That is enough on reason. So the Book of Knowledge ends, with praise to God and blessings on the Prophet and every chosen servant of the people of earth and heaven." },
    ],
    closer: [
      { title: "The book ends where it began", body: "The Book of Knowledge opened with a stolen word. It ends with another: reason, moved to mean debate, and then blamed by people who were really blaming debate." },
      { title: "Light upon light", body: "The oil that almost shines with no fire is the top of the ladder of souls. At the bottom is dry ground. Most people are the ground that needs digging, which is why teachers exist." },
    ],
    distinction: ["Two things called reason", "The craft of debate", "What the name was moved to: refutations and forced conclusions. What some Sufis blamed.", "The light of insight", "By which God and His messengers' truth are known. It cannot be blamed without blaming the law itself."],
    misreading: "Ghazali does not side with those who scorn reason for faith. He says the eye of certainty and the light of faith are what he means by reason. The quarrel was only over a word.",
    reflection: "Are you ground that gushes, ground that needs digging, or dry ground? Who is digging for you?",
    audit: ["Do I blame reason when I mean arguing?", "Do I think my mind is as complete as anyone's?", "Does my knowledge of a sin's harm make me fear it?", "Do I confuse knowing about goodness with being good?"],
    nodes: ["aql", "basira"],
    model: spectrum("Three kinds of ground", "How souls differ in reason.", [["Springs by itself", "Understands without teaching: the prophets, oil that almost shines.", "support"], ["Needs digging", "Understands when taught and alerted.", "balance"], ["Dry ground", "Neither teaching nor alerting helps.", "warning"]]),
  }),
];

